"""Прототипы ЕГЭ по математике, базовый уровень (КИМ 2026/2027, 21 задание).

Для каждого номера — каталог разновидностей открытого банка ФИПИ и генератор аналогов
к каждой. Сюжеты и формулировки свои; числа выбираются так, чтобы ответ был «экзаменационным»
(целое или конечная десятичная дробь того же масштаба, что в банке). Проверка ответа — независимый
пересчёт другим путём: моделирование по шагам, перебор, sympy, Fraction.

Самопроверка: python3 gen_math.py --protos --exam ege-base --n 60 --fipi $SP/fipi
"""
