# ================================================================ 15. Проценты, доли, отношения

def pct(p_):
    return f'{tnum(p_)} %'


def pct_apply(x, *ps):
    """Последовательные изменения на ps процентов (по шагам, через sympy)."""
    v = R(x)
    for p_ in ps:
        v = v + v * R(p_) / 100
    return v


@P('eb15-change', 'Цена (зарплата, вклад) после изменения на p %',
   'Новое значение = старое · (1 ± p/100): повышение цены, скидка, налог, начисление процентов по вкладу.',
   'Сюжет (подорожание, скидка по карте, НДФЛ 13 %, вклад, тариф), исходная сумма, процент.',
   'x·(1 ± p/100)',
   r'(увеличится на \d+ ?%|скидку \d+ ?%|Налог на доходы|годовых|подорожал)',
   ['нашли только величину изменения', 'прибавили вместо вычитания'],
   '«Сколько рублей будет стоить …?», ответ — число рублей.', kes=['1.2'])
def gen_eb15_change(r):
    st = r.randrange(5)
    w = Who(r)
    if st == 0:
        x, p_ = r.choice(range(200, 1500, 10)), r.choice([2, 4, 5, 6, 8, 10, 12, 15, 20])
        q = (f'Абонентская плата за домашний интернет — {rub(x)} в месяц. Со следующего месяца она вырастет на {pct(p_)}. Сколько рублей '
             f'придётся платить за интернет каждый месяц?')
    elif st == 1:
        x, p_ = r.choice(range(150, 3000, 10)), -r.choice([3, 5, 7, 10, 12, 15, 20])
        q = f'По карте постоянного покупателя в аптеке действует скидка {pct(-p_)}. Лекарство стоит {rub(x)}. Сколько рублей заплатит покупатель с картой?'
    elif st == 2:
        x, p_ = r.choice(range(15000, 90000, 500)), -13
        q = (f'С заработной платы удерживают налог на доходы — 13 %. {w.n} {w.v("заработал")} за месяц {rub(x)}. Сколько рублей '
             f'{"он получит" if w.male else "она получит"} после уплаты налога?')
    elif st == 3:
        x, p_ = r.choice(range(5000, 300000, 1000)), r.choice([4, 5, 6, 8, 10, 12, 15, 16, 18])
        q = (f'Банк начисляет по вкладу {pct(p_)} годовых один раз в конце года. На вклад положили {rub(x)}. Сколько рублей будет на '
             f'счёте через год, если никаких операций со вкладом не проводить?')
    else:
        x, p_ = r.choice(range(40, 400, 5)), r.choice([10, 15, 20, 25, 30, 40, 50])
        fr_ = r.choice([('черешня', 'черешни'), ('малина', 'малины'), ('клубника', 'клубники'), ('голубика', 'голубики')])
        q = f'В мае килограмм {fr_[1]} стоил {rub(x)}, а в июне {fr_[0]} подорожала на {pct(p_)}. Сколько рублей стоил килограмм {fr_[1]} в июне?'
    ans = x * (1 + F(p_, 100))
    if not nice(ans, 2, 10 ** 7):
        return None
    return pcard(q, num(ans), e=f'{T(x)} · {dec(1 + F(p_, 100))} = {T(ans)}.'), lambda: same(num(ans), pct_apply(x, p_))


@P('eb15-part', 'Процент от числа и число по его проценту',
   'Часть = целое · p/100; целое = часть · 100/p.',
   'Сюжет (бюджет, пенсионеры в городе, участники олимпиады, школьники, изучающие язык, выпускники в вузах), числа, направление.',
   'x·p/100 или a·100/p',
   r'(составляют \d+ ?%|составило \d+ ?%|что составляет \d+ ?%|\d+ ?% из них|расходы на одну из его статей)',
   ['путают «процент от числа» и «число по проценту»'],
   '«Сколько … ?», ответ — целое число.', kes=['1.2'])
def gen_eb15_part(r):
    st = r.randrange(5)
    # масштаб как в жизни: посёлок — тысячи жителей, гимназия и колледж — сотни (до полутора–трёх тысяч) учащихся
    p_ = r.choice([8, 10, 12, 15, 16, 20] if st == 0 else [4, 5, 8, 10, 12, 15, 20, 25, 30, 35, 40, 45, 60, 64, 75, 80])
    top = {0: 30000, 1: 5000, 2: 3000, 3: 1500, 4: 3000}[st]
    step = 100 if st == 0 else 10
    whole = r.choice([x for x in range(step * 20, top, step) if (x * p_) % 100 == 0])
    part = whole * p_ // 100
    if st == 0:
        q, ans = f'В посёлке {T(whole)} жителей, из них {pct(p_)} — школьники. Сколько школьников живёт в посёлке?', part
    elif st == 1:
        q, ans = (f'Годовой бюджет районной библиотеки составляет {T(whole)} тыс. рублей, на покупку новых книг тратится {pct(p_)} бюджета. '
                  f'Сколько тысяч рублей тратится на покупку книг?'), part
    elif st == 2:
        q, ans = (f'На олимпиаду по экологии пришли {pl(whole, "школьник", "школьника", "школьников")}, из них {pct(p_)} стали призёрами. Сколько '
                  f'школьников стали призёрами?'), part
    elif st == 3:
        q, ans = (f'Немецкий язык в гимназии изучают {pl(part, "ученик", "ученика", "учеников")}, это {pct(p_)} всех учеников гимназии. '
                  f'Сколько всего учеников в гимназии?'), whole
    else:
        q, ans = (f'Спортивные секции посещают {pl(part, "студент", "студента", "студентов")} колледжа, что составляет {pct(p_)} от числа '
                  f'всех студентов. Сколько студентов учится в колледже?'), whole
    return pcard(q, num(ans), e=f'Ответ: {ans}.'), lambda: sp.Rational(part) / whole * 100 == p_ and ans in (part, whole)


@P('eb15-percent-change', 'На сколько процентов изменилась величина',
   'Процент изменения = (новое − старое) / старое · 100 %; «в k раз» → (k − 1)·100 % или (1 − 1/k)·100 %; «составила 0,96 от старой» → 4 %.',
   'Сюжет (цена товара, число учеников, подписчики, больные), значения или кратность, рост или падение.',
   '(new − old)/old · 100',
   r'(На сколько процентов|Сколько процентов составила скидка)',
   ['делят на новое значение', 'путают «в 5 раз больше» и «на 500 %»'],
   '«На сколько процентов …?», ответ — число процентов.', kes=['1.2'])
def gen_eb15_percent_change(r):
    st = r.randrange(4)
    if st == 0:
        thing, lo, hi, stp = r.choice([('Беговые кроссовки', 2000, 12000, 100), ('Настольная лампа', 600, 5000, 100),
                                       ('Электросамокат', 15000, 45000, 500), ('Рюкзак', 900, 6000, 100)])
        old = r.choice(range(lo, hi, stp))
        p_ = r.choice([-40, -30, -25, -20, -15, -12, -10, -5, 5, 8, 10, 12, 15, 20, 25, 30, 40, 50])
        new = old * (1 + F(p_, 100))
        if new.denominator != 1:
            return None
        q = (f'До {"повышения" if p_ > 0 else "снижения"} цены {thing.lower()} стоил{"а" if thing in ("Настольная лампа",) else "и" if thing == "Беговые кроссовки" else ""} '
             f'{rub(old)}, а теперь — {rub(new)}. На сколько процентов {"выросла" if p_ > 0 else "упала"} цена?')
        ans = F(abs(p_))
        chk = lambda: same(num(ans), sp.Abs((R(new) - old) / old * 100))
    elif st == 1:
        old = r.choice(range(300, 2000, 20))
        p_ = r.choice([4, 5, 6, 8, 10, 12, 15, 20, 25])
        new = old * (1 + F(p_, 100))
        if new.denominator != 1:
            return None
        q = (f'В прошлом учебном году в лицее было {pl(old, "ученик", "ученика", "учеников")}, а в этом — {pl(int(new), "ученик", "ученика", "учеников")}. '
             f'На сколько процентов увеличилось число учеников?')
        ans = F(p_)
        chk = lambda: same(num(ans), (R(new) - old) / old * 100)
    elif st == 2:
        k = r.choice([2, 3, 4, 5, 8, 10, 20, 25, 50])
        up = r.random() < 0.5
        ans = F((k - 1) * 100) if up else 100 - F(100, k)
        if not nice(ans, 2):
            return None
        if up:
            q = f'Число подписчиков кулинарного блога за год выросло {raz(k)}. На сколько процентов увеличилось число подписчиков?'
        else:
            q = f'Число пропусков уроков по болезни за месяц уменьшилось {raz(k)}. На сколько процентов уменьшилось число пропусков?'
        chk = lambda: same(num(ans), (k - 1) * 100 if up else (1 - sp.Rational(1, k)) * 100)
    else:
        c = r.choice([F(96, 100), F(9, 10), F(85, 100), F(72, 100), F(68, 100), F(8, 10), F(75, 100), F(94, 100)])
        ans = (1 - c) * 100
        q = (f'После уценки новая цена холодильника составила {dec(c)} от прежней. На сколько процентов уменьшилась цена холодильника?')
        chk = lambda: same(num(ans), (1 - R(c)) * 100)
    return pcard(q, num(ans), e=f'Ответ: {num(ans)} %.'), chk


@P('eb15-reverse', 'Исходная цена по цене после изменения',
   'Если после изменения на p % стало y, то было y / (1 ± p/100).',
   'Уценка или наценка, процент, новая цена; сюжет.',
   'y / (1 ± p/100)',
   r'(уценили на \d+ ?%|была повышена на \d+ ?% и составила)',
   ['прибавили процент к новой цене', 'вычли процент от новой цены'],
   '«Сколько рублей стоил товар до …?»', kes=['1.2'])
def gen_eb15_reverse(r):
    p_ = r.choice([-50, -40, -30, -25, -20, -15, -10, 5, 10, 15, 20, 25, 30])
    old = r.choice(range(200, 20000, 50))
    new = old * (1 + F(p_, 100))
    if new.denominator != 1:
        return None
    thing = r.choice(['Кофемолку', 'Палатку', 'Пылесос', 'Куртку', 'Настольную игру'])
    if p_ < 0:
        q = f'{thing} на распродаже уценили на {pct(-p_)}, и теперь она стоит {rub(new)}. Сколько рублей она стоила до распродажи?'
        if thing in ('Пылесос',):
            q = q.replace('она стоит', 'он стоит').replace('она стоила', 'он стоил')
    else:
        q = f'После повышения цены на {pct(p_)} {thing.lower()} стоит {rub(new)}. Сколько рублей стоил{"а" if thing not in ("Пылесос",) else ""} эта вещь до повышения цены?'
        q = q.replace('стоила эта вещь', 'стоила эта вещь').replace('стоил эта вещь', 'стоила эта вещь')
    ans = F(old)
    return pcard(q, num(ans), e=f'{T(new)} : {dec(1 + F(p_, 100))} = {T(old)}.'), \
        lambda: same(num(ans), sp.solve(sp.Eq(sp.Symbol('x') * (1 + sp.Rational(p_, 100)), int(new)), sp.Symbol('x'))[0])


@P('eb15-successive', 'Два последовательных изменения цены',
   'Каждое изменение считается от текущей цены: x·(1 ± p₁/100)·(1 ± p₂/100).',
   'Два процента (повышения или снижения), исходная цена, сюжет.',
   'x·(1 ± p₁/100)(1 ± p₂/100)',
   r'(снижал цены дважды|ещё на \d+ ?%)',
   ['складывают проценты', 'второй процент берут от исходной цены'],
   '«Сколько рублей стал стоить … после второго изменения?»', kes=['1.2'])
def gen_eb15_successive(r):
    p1, p2 = r.choice([10, 20, 25, 30, 40, 50]), r.choice([10, 20, 25, 30, 40, 50])
    sg = r.choice([(1, 1), (-1, -1), (1, -1)])
    x = r.choice(range(100, 5000, 20))
    ans = x * (1 + F(sg[0] * p1, 100)) * (1 + F(sg[1] * p2, 100))
    if not nice(ans, 2):
        return None
    thing = r.choice(['тостер', 'рюкзак', 'велошлем', 'чайник'])
    w = lambda s_: 'подорожал' if s_ > 0 else 'подешевел'
    q = (f'В марте {thing} стоил {rub(x)}. В апреле он {w(sg[0])} на {pct(p1)}, а в мае {"ещё " if sg[0] == sg[1] else ""}{w(sg[1])} на '
         f'{pct(p2)}. Сколько рублей стоил {thing} в мае?')
    return pcard(q, num(ans), e=f'{T(x)} · {dec(1 + F(sg[0] * p1, 100))} · {dec(1 + F(sg[1] * p2, 100))} = {num(ans)}.'), \
        lambda: same(num(ans), pct_apply(x, sg[0] * p1, sg[1] * p2))


@P('eb15-ratio', 'Деление в отношении и доли',
   'При отношении a : b доли равны a/(a + b) и b/(a + b); по одной части (или разности частей) находим целое.',
   'Сюжет (посевы, голоса, прибыль акционеров, чайная смесь, длины рек, деревья в парке), отношение, что известно.',
   'x·a/(a + b), разность → одна часть, доля в процентах',
   r'(в отношении \d+ ?: ?\d+|относится к .* как|относятся как)',
   ['делят на a вместо a + b', 'путают, к какой части относится число'],
   '«Сколько … ?», «Сколько процентов … составляют …?»', kes=['1.2'])
def gen_eb15_ratio(r):
    a, b = r.choice([(1, 2), (1, 3), (2, 3), (3, 5), (2, 7), (4, 5), (3, 7), (5, 7), (7, 8), (9, 16), (3, 17), (1, 4), (7, 13)])
    st = r.randrange(5)
    k = r.randint(2, 30)
    tot = (a + b) * k
    if st == 0:
        q, ans = (f'Под картофель и капусту в хозяйстве отведено {tot} га, площади распределены в отношении {a} : {b} соответственно. '
                  f'Сколько гектаров занимает капуста?'), F(b * k)
    elif st == 1:
        q, ans = (f'В голосовании за название школьной газеты участвовали {pl(tot, "человек", "человека", "человек")}; голоса за два варианта '
                  f'распределились в отношении {a} : {b}. Сколько голосов получил победивший вариант?'), F(max(a, b) * k)
    elif st == 2:
        ans = F(b * 100, a + b)
        if not nice(ans, 2):
            return None
        q = (f'Число берёз в роще относится к числу осин как {a} : {b}, других деревьев в роще нет. Сколько процентов всех деревьев рощи '
             f'составляют осины?')
    elif st == 3:
        d = abs(b - a) * k
        q, ans = (f'Длины двух туристических маршрутов относятся как {a} : {b}, причём один маршрут длиннее другого на {d} км. Найдите длину '
                  f'более длинного маршрута. Ответ дайте в километрах.'), F(max(a, b) * k)
    else:
        c = r.randint(1, 4)
        kk = r.randint(2, 20) * 5
        if (a + b + c + 1) * kk > 600:      # пакет сбора — до полукилограмма с небольшим
            return None
        q, ans = (f'Травяной сбор составляют из ромашки, чабреца и мяты в отношении {a + b} : {c} : 1 по массе. Сколько граммов весит пакет сбора, '
                  f'в котором {kk} г мяты?'), F((a + b + c + 1) * kk)
        tot = None
    if not nice(ans, 2) or ans == 0:
        return None

    def chk():
        x = sp.Symbol('x', positive=True)
        if st == 0:
            return same(num(ans), sp.Rational(b, a + b) * tot)
        if st == 1:
            return same(num(ans), sp.Rational(max(a, b), a + b) * tot)
        if st == 2:
            return same(num(ans), sp.Rational(b, a + b) * 100)
        if st == 3:
            return same(num(ans), max(a, b) * sp.solve(sp.Eq(abs(b - a) * x, abs(b - a) * k), x)[0])
        return same(num(ans), kk * (a + b + c + 1))
    return pcard(q, num(ans), e=f'Одна часть — {k if tot else kk}; ответ {num(ans)}.'), chk


@P('eb15-shop', 'Покупки с условиями: наценка, скидка на второй товар, оптовая скидка, сборка',
   'Посчитать стоимость с учётом условия: наценка к оптовой цене, скидка только на второй товар, скидка на всю покупку при большом '
   'количестве, доплата за сборку.',
   'Сюжет и числа (цены, проценты, количество).',
   'сумма с учётом процентов',
   r'(с наценкой|скидка на второй|скидку \d+ ?% от стоимости всей покупки|сборку мебели|скидку \d+ ?% на каждую)',
   ['применили скидку ко всей покупке', 'забыли умножить на количество'],
   '«Сколько рублей придётся заплатить …?»', kes=['1.2'])
def gen_eb15_shop(r):
    st = r.randrange(4)
    if st == 0:
        w_, p_, n = r.choice(range(40, 800, 10)), r.choice([10, 15, 20, 25, 30, 40, 50]), r.randint(2, 6)
        ans = w_ * (1 + F(p_, 100)) * n
        q = (f'Сувенирная лавка покупает брелоки у производителя по {rub(w_)} за штуку, а продаёт на {pct(p_)} дороже. Сколько рублей '
             f'заплатит покупатель за {pl(n, "брелок", "брелока", "брелоков")}?')
        chk = lambda: same(num(ans), pct_apply(w_, p_) * n)
    elif st == 1:
        x, p_ = r.choice(range(500, 6000, 100)), r.choice([20, 30, 40, 50, 60])
        ans = x + x * (1 - F(p_, 100))
        thing = r.choice(['пару кроссовок', 'футболку', 'рюкзак', 'термос'])
        q = (f'В спортивном магазине любой(ая) {thing} стоит {rub(x)}. По акции при покупке двух одинаковых товаров на второй действует '
             f'скидка {pct(p_)}. Сколько рублей придётся заплатить за две такие покупки?').replace('любой(ая) пару кроссовок', 'любая пара кроссовок').replace('любой(ая) футболку', 'любая футболка').replace('любой(ая) рюкзак', 'любой рюкзак').replace('любой(ая) термос', 'любой термос')
        chk = lambda: same(num(ans), x + pct_apply(x, -p_))
    elif st == 2:
        pr, n, thr, p_ = r.randint(15, 90), r.randint(20, 120), r.choice([10, 20, 30, 50]), r.choice([5, 10, 15, 20])
        ans = pr * n * (1 - F(p_, 100)) if n > thr else F(pr * n)
        q = (f'Карандаш стоит {rub(pr)}. Если покупают больше {thr} карандашей, магазин даёт скидку {pct(p_)} на всю покупку. Сколько рублей '
             f'заплатит покупатель за {pl(n, "карандаш", "карандаша", "карандашей")}?')
        chk = lambda: same(num(ans), pct_apply(pr * n, -p_) if n > thr else pr * n)
    else:
        x, p_ = r.choice(range(8000, 60000, 500)), r.choice([5, 8, 10, 12, 15])
        ans = x * (1 + F(p_, 100))
        q = (f'Мебель в магазине продаётся в разобранном виде, а сборка на дому стоит {pct(p_)} от цены мебели. Сколько рублей обойдётся '
             f'покупка кухонного гарнитура за {rub(x)} вместе со сборкой?')
        chk = lambda: same(num(ans), pct_apply(x, p_))
    if not nice(ans, 2, 10 ** 7):
        return None
    return pcard(q, num(ans), e=f'Ответ: {num(ans)}.'), chk


@P('eb15-share-of', 'Доля в процентах; скидка в процентах по ценам с копейками',
   'Доля части от целого в процентах: часть / целое · 100; «одна восьмая» — 12,5 %; скидка по старой и новой цене.',
   'Дробь (половина, четверть, одна восьмая…), цены в рублях и копейках.',
   'a/b · 100',
   r'(всех отдыхающих в пансионате|делает пенсионерам скидку)',
   ['ответили дробью вместо процентов', 'поделили на новую цену'],
   '«Сколько процентов … составляют …?»', kes=['1.2'])
def gen_eb15_share_of(r):
    if r.random() < 0.5:
        n, word = r.choice([(2, 'Половина'), (4, 'Четверть'), (5, 'Одна пятая'), (8, 'Одна восьмая'), (10, 'Одна десятая'), (20, 'Одна двадцатая'),
                            (25, 'Одна двадцать пятая'), (40, 'Одна сороковая')])
        ans = F(100, n)
        who = r.choice(['участников марафона — школьники', 'посетителей выставки — иностранцы', 'пассажиров поезда — дети',
                        'книг в библиотеке — энциклопедии'])
        q = f'{word} всех {who}. Сколько процентов составляет эта часть?'
        chk = lambda: same(num(ans), sp.Rational(100, n))
    else:
        item, lo, hi = r.choice([('Батон хлеба', 30, 90), ('Пакет молока', 60, 140), ('Бутылка кефира', 60, 150), ('Десяток яиц', 70, 180),
                                 ('Пачка творога', 80, 200)])
        old = r.choice(range(lo, hi + 1, 5))
        p_ = r.choice([2, 3, 4, 5, 6, 8, 10, 12, 15])
        new = old * (1 - F(p_, 100))
        if not nice(new, 2):
            return None

        def rub_full(x):
            """«140 рублей 65 копеек» — копейки словом, как в КИМ (точка сокращения не сталкивается с концом фразы)."""
            x = F(x)
            kop = int(x * 100) % 100
            s = pl(int(x), 'рубль', 'рубля', 'рублей')
            return s + (f' {kop} {plural(kop, "копейка", "копейки", "копеек")}' if kop else '')
        him = 'за неё' if item.startswith(('Бутылка', 'Пачка')) else 'за него'
        q = (f'Магазин делает скидку по социальной карте. {item} стоит {rub_full(old)}, а по карте {him} заплатили {rub_full(new)}. Сколько '
             f'процентов составила скидка?')
        ans = F(p_)
        chk = lambda: same(num(ans), (1 - R(new) / old) * 100)
    if not nice(ans, 2):
        return None
    return pcard(q, num(ans), e=f'Ответ: {num(ans)} %.'), chk


@P('eb15-difference', 'Доли в процентах и разность: сколько всего',
   'Если одних p %, а других (100 − p) %, то разность составляет (2p − 100) %; по ней находим целое.',
   'Сюжет (девочки и мальчики в школе, книги и журналы, взрослые и дети), p %, разность.',
   'd / ((2p − 100)/100)',
   r'на \d+ человека? (больше|меньше), чем',
   ['делят разность на p %', 'путают, кого больше'],
   '«Сколько … всего, если …?»', kes=['1.2'])
def gen_eb15_difference(r):
    p_ = r.choice([51, 52, 53, 54, 55, 56, 58, 60, 65])
    tot = r.choice([x for x in range(100, 3000, 50) if (x * p_) % 100 == 0])
    d = tot * (2 * p_ - 100) // 100
    girls = r.random() < 0.5
    if girls:
        q = f'Девочки составляют {pct(p_)} всех учащихся школы, причём девочек на {pl(d, "человек", "человека", "человек")} больше, чем мальчиков. Сколько всего учащихся в школе?'
    else:
        q = f'Мальчики составляют {pct(p_)} всех учеников спортивной школы, поэтому девочек там на {pl(d, "человек", "человека", "человек")} меньше. Сколько учеников в спортивной школе?'
    ans = F(tot)
    x = sp.Symbol('x', positive=True)
    return pcard(q, num(ans), e=f'Разность {2 * p_ - 100} % — это {d}; всего {tot}.'), \
        lambda: same(num(ans), sp.solve(sp.Eq(x * sp.Rational(p_, 100) - x * sp.Rational(100 - p_, 100), d), x)[0])


@P('eb15-profit', 'Распределение прибыли между акционерами',
   'Частным акционерам достаётся (100 − p) % прибыли (или доля по отношению a : b).',
   'Процент или отношение акций, прибыль в млн рублей.',
   'S·(100 − p)/100 или S·b/(a + b)',
   r'(Государству принадлежит|Акции предприятия распределены)',
   ['взяли долю государства', 'неверно поделили в отношении'],
   '«Какая сумма из этой прибыли должна пойти на выплату …? Ответ дайте в рублях.»', kes=['1.2'])
def gen_eb15_profit(r):
    S = r.choice(range(5, 80))
    if r.random() < 0.5:
        p_ = r.choice([10, 20, 25, 30, 40, 50, 60])
        ans = F(S * (100 - p_), 100)
        q = (f'Городу принадлежит {pct(p_)} акций транспортной компании, остальные акции — у частных владельцев. Чистая прибыль компании за '
             f'год — {S} млн рублей. Сколько миллионов рублей из прибыли получат частные владельцы, если прибыль делится пропорционально числу акций?')
        chk = lambda: same(num(ans), S * (1 - sp.Rational(p_, 100)))
    else:
        a, b = r.choice([(2, 1), (3, 1), (4, 1), (5, 1), (3, 2), (7, 3)])
        ans = F(S * b, a + b)
        q = (f'Акции фабрики распределены между городом и частными владельцами в отношении {a} : {b}. Чистая прибыль фабрики за год — '
             f'{S} млн рублей. Сколько миллионов рублей из неё придётся на частных владельцев?')
        chk = lambda: same(num(ans), S * sp.Rational(b, a + b))
    if not nice(ans, 2):
        return None
    return pcard(q, num(ans), e=f'Ответ: {num(ans)} млн руб.'), chk


# ================================================================ 18. Неравенства и числовая прямая: соответствие

def xm(a, var='x'):
    """«x − 3», «x + 2», «x» для x − a."""
    a = F(a)
    return var if a == 0 else (f'{var} − {tnum(a)}' if a > 0 else f'{var} + {tnum(-a)}')


def ineq_forms(r, a, b):
    """Неравенства с решениями четырёх видов через числа a < b: (текст, sympy-строка) по ключу множества."""
    c = r.choice([2, 3, 5])
    k = r.choice([2, 3, 4, 5])
    L = str(c).translate(SUBS)
    pow_ = lambda e: f'{c}^({e})' if ' ' in e else f'{c}^{e}'
    return {
        'lt_a': r.choice([(f'{pow_(xm(a))} < 1', f'{c}**(x-({a}))<1'),
                          (f'(1/{c})^x > (1/{c})^{tnum(a)}' if a >= 0 else f'(1/{c})^x > (1/{c})^({tnum(a)})',
                           f'(sp.Rational(1,{c}))**x>(sp.Rational(1,{c}))**({a})'),
                          (f'{k}({xm(a)}) < 0' if a else f'{k}x < 0', f'{k}*(x-({a}))<0')]),
        'gt_b': r.choice([(f'log{L}({xm(b - 1)}) > 0' if b - 1 else f'log{L} x > 0', f'log(x-({b - 1}),{c})>0'),
                          (f'{pow_(xm(b))} > 1', f'{c}**(x-({b}))>1')]),
        'in': r.choice([(f'({xm(a)})({xm(b)}) < 0', f'(x-({a}))*(x-({b}))<0'), (f'({xm(a)}) / ({xm(b)}) < 0', f'(x-({a}))/(x-({b}))<0')]),
        'out': r.choice([(f'({xm(a)})({xm(b)}) > 0', f'(x-({a}))*(x-({b}))>0'), (f'({xm(b)}) / ({xm(a)}) > 0', f'(x-({b}))/(x-({a}))>0')]),
    }


def fix_signs(t):
    t = re.sub(r'\((x [−+] \d+)\)\(x\)', r'x(\1)', t)     # (x + 3)(x) → x(x + 3), как пишут в КИМ
    return t.replace('(x)', 'x')


@P('eb18-inequalities', 'Неравенства и их решения (соответствие)',
   'Решить четыре неравенства разных видов (показательное, логарифмическое, рациональное, квадратичное) с одними и теми же '
   'граничными точками и сопоставить с множествами решений.',
   'Граничные точки, вид каждого неравенства (основание, знак).',
   'множество решений каждого неравенства',
   r'Каждому из четырёх неравенств',
   ['забывают про ОДЗ логарифма', 'путают знак при основании меньше 1', 'путают «между корнями» и «вне корней»'],
   'Два столбца (неравенства — решения); ответ — четыре цифры.', kes=['2.5', '2.7'])
def gen_eb18_inequalities(r):
    a = r.randint(-4, 5)
    b = a + r.randint(2, 6)
    forms = ineq_forms(r, a, b)
    keys = ['lt_a', 'gt_b', 'in', 'out']
    r.shuffle(keys)
    sol_txt = {'lt_a': f'x < {tnum(a)}', 'gt_b': f'x > {tnum(b)}', 'in': f'{tnum(a)} < x < {tnum(b)}', 'out': f'x < {tnum(a)} или x > {tnum(b)}'}
    lefts = [fix_signs(forms[k][0]) for k in keys]
    rights = [sol_txt[k] for k in keys]
    c = match_card(r, lefts, rights, [0, 1, 2, 3], 'Установите соответствие между неравенствами и их решениями. '
                   'В таблице под каждой буквой укажите соответствующий номер.',
                   e='Решаем каждое неравенство, учитывая область определения и знак основания.')
    syms = {lefts[i]: forms[keys[i]][1] for i in range(4)}
    ans = match_answer(c)

    def chk():
        x = sp.Symbol('x', real=True)
        for L_, rt_ in ans.items():
            sol = sp.solve_univariate_inequality(sp.sympify(syms[L_], locals={'x': x, 'sp': sp, 'log': sp.log}), x, relational=False)
            if rt_.startswith('x < ') and 'или' not in rt_:
                want = sp.Interval.open(-sp.oo, int(rt_[4:].replace('−', '-')))
            elif rt_.startswith('x > '):
                want = sp.Interval.open(int(rt_[4:].replace('−', '-')), sp.oo)
            elif 'или' in rt_:
                want = sp.Union(sp.Interval.open(-sp.oo, a), sp.Interval.open(b, sp.oo))
            else:
                want = sp.Interval.open(a, b)
            pts = [a - 1, a - F(1, 2), a, a + F(1, 3), F(a + b, 2), b - F(1, 3), b, b + F(1, 2), b + 2]
            ineq = sp.sympify(syms[L_], locals={'x': x, 'sp': sp, 'log': sp.log})
            for t in pts:
                try:
                    got = bool(sp.simplify(ineq.subs(x, R(t))))
                except TypeError:
                    got = False   # вне области определения
                if got != (R(t) in want):
                    return False
        return True
    return c, chk


def numline_svg(pts, lo, hi, marks=(), width=400):
    """Координатная прямая от lo до hi с целыми делениями; pts — [(x, 'A')] точки над прямой."""
    L, Rr, y = 20, 20, 44
    sx = lambda v: L + (v - lo) / (hi - lo) * (width - L - Rr)
    out = (f'<line x1="{L - 10}" y1="{y}" x2="{width - 6}" y2="{y}" stroke="{INK}" stroke-width="1.6" marker-end="url(#a)"/>')
    for k in range(math.ceil(lo), math.floor(hi) + 1):
        out += (f'<line x1="{sx(k):.1f}" y1="{y - 5}" x2="{sx(k):.1f}" y2="{y + 5}" stroke="{INK}" stroke-width="1.4"/>'
                f'<text x="{sx(k):.1f}" y="{y + 20}" text-anchor="middle" font-size="12">{tnum(k)}</text>')
    for v, lab in pts:
        out += (f'<circle cx="{sx(v):.1f}" cy="{y}" r="4" fill="{BLUE}"/>'
                f'<text x="{sx(v):.1f}" y="{y - 12}" text-anchor="middle" font-size="13" font-style="italic">{lab}</text>')
    return _svg(width, 72, out)


NUM_POOL = [
    ('√{}', lambda n: math.sqrt(n), lambda n: sp.sqrt(n), range(2, 37)),
    ('log₂ {}', lambda n: math.log2(n), lambda n: sp.log(n, 2), range(3, 60)),
    ('log₃ {}', lambda n: math.log(n, 3), lambda n: sp.log(n, 3), range(2, 200)),
    ('log₅ {}', lambda n: math.log(n, 5), lambda n: sp.log(n, 5), range(6, 600)),
    ('{}/7', lambda n: n / 7, lambda n: sp.Rational(n, 7), range(2, 41)),
    ('{}/13', lambda n: n / 13, lambda n: sp.Rational(n, 13), range(3, 76)),
    ('{}/9', lambda n: n / 9, lambda n: sp.Rational(n, 9), range(2, 53)),
    ('(1/2)^(−{})', lambda n: 2 ** n, lambda n: sp.Rational(1, 2) ** (-n), range(1, 3)),
    ('∛{}', lambda n: n ** (1 / 3), lambda n: sp.cbrt(n), range(2, 200)),
]


@P('eb18-number-line', 'Точки на координатной прямой и числа (корни, логарифмы, дроби)',
   'Оценить каждое число (между какими целыми, ближе к какому) и расположить по возрастанию; сопоставить с точками на прямой.',
   'Числа разных видов (√n, log_a b, дроби, степени), положения точек.',
   'точки упорядочены так же, как числа',
   r'На координатной прямой отмечены точки A , B , C и D',
   ['неверно оценили логарифм', 'путают порядок корней'],
   'Рисунок прямой с точками A, B, C, D и столбец чисел; ответ — четыре цифры.', svg=True, kes=['1.3', '1.6', '1.7'])
def gen_eb18_number_line(r):
    lo, hi = 0, 6
    chosen = []
    for _ in range(40):
        fmt, fv, fs, rng = r.choice(NUM_POOL)
        n = r.choice(list(rng))
        v = fv(n)
        if not lo + 0.15 < v < hi - 0.15 or any(abs(v - c_[1]) < 0.45 for c_ in chosen) or abs(v - round(v)) < 0.08:
            continue
        if '/' in fmt and math.gcd(n, int(fmt.split('/')[1])) != 1:
            continue
        if any(fmt == c_[0][0] for c_ in chosen) and r.random() < 0.7:
            continue
        chosen.append(((fmt, n), v, fs(n)))
        if len(chosen) == 4:
            break
    if len(chosen) < 4:
        return None
    order = sorted(range(4), key=lambda i: chosen[i][1])
    labels = 'ABCD'
    pts = [(chosen[i][1], labels[k]) for k, i in enumerate(order)]
    svg = numline_svg(pts, lo, hi)
    lefts = list(labels)
    rights = [chosen[i][0][0].format(chosen[i][0][1]) for i in order]
    q = ('На координатной прямой отмечены точки A, B, C и D. Каждой точке соответствует одно из чисел в правом столбце. '
         'Установите соответствие между указанными точками и числами. В таблице под каждой буквой укажите соответствующий номер.')
    c = match_card(r, lefts, rights, [0, 1, 2, 3], q, e='Оцениваем каждое число и располагаем по возрастанию.')
    c['svg'] = svg
    ans = match_answer(c)
    exact = {chosen[i][0][0].format(chosen[i][0][1]): chosen[i][2] for i in range(4)}

    def chk():
        vals = [float(sp.N(exact[ans[L_]])) for L_ in labels]
        return all(vals[i] < vals[i + 1] for i in range(3))
    return c, chk


M_POOL = [('log₂ 5', sp.log(5, 2)), ('log₂ 7', sp.log(7, 2)), ('log₃ 10', sp.log(10, 3)), ('√6', sp.sqrt(6)), ('√3', sp.sqrt(3)),
          ('√8', sp.sqrt(8)), ('0,15', sp.Rational(15, 100)), ('0,6', sp.Rational(6, 10)), ('2,4', sp.Rational(12, 5)), ('−√(2,2)', -sp.sqrt(sp.Rational(22, 10))),
          ('log₅ 3', sp.log(3, 5)), ('1,7', sp.Rational(17, 10))]
M_EXPR = [('m − 1', lambda m: m - 1), ('m − 2', lambda m: m - 2), ('m²', lambda m: m ** 2), ('4 − m', lambda m: 4 - m), ('6/m', lambda m: 6 / m),
          ('1/m', lambda m: 1 / m), ('2m', lambda m: 2 * m), ('m + 1', lambda m: m + 1), ('3 − m', lambda m: 3 - m), ('m/2', lambda m: m / 2),
          ('−m', lambda m: -m), ('m² − 1', lambda m: m ** 2 - 1), ('4m', lambda m: 4 * m), ('1 − m', lambda m: 1 - m), ('√m', lambda m: sp.sqrt(m))]


@P('eb18-m-segments', 'Выражения с числом m и отрезки (или точки) на прямой',
   'Оценить m, затем каждое выражение от m, и определить, какому отрезку (какой точке) оно принадлежит.',
   'Значение m (логарифм, корень, десятичная дробь), набор выражений, отрезки или точки на прямой.',
   'каждое выражение — в своём отрезке (точке)',
   r'(Число m равно|отмечено число m|Каждому из четырёх чисел в левом столбце соответствует отрезок)',
   ['неверно оценили m', 'ошиблись со знаком для отрицательного m'],
   'Два столбца (выражения — отрезки или точки); ответ — четыре цифры.', kes=['1.7', '1.8'])
def gen_eb18_m_segments(r):
    name, m = r.choice(M_POOL)
    mf = float(sp.N(m))
    exprs = [(t, fn) for t, fn in M_EXPR]
    r.shuffle(exprs)
    st = r.random() < 0.5
    if st:
        segs = [(-3, -2), (-2, -1), (-1, 0), (0, 1), (1, 2), (2, 3), (3, 4), (4, 6), (6, 9)]
        pick = []
        used = set()
        for t, fn in exprs:
            v = fn(m)
            if not v.is_real:
                continue
            vf = float(sp.N(v))
            seg = next((sg for sg in segs if sg[0] + 0.03 < vf < sg[1] - 0.03), None)
            if seg is None or seg in used:
                continue
            used.add(seg)
            pick.append((t, v, seg))
            if len(pick) == 4:
                break
        if len(pick) < 4:
            return None
        lefts = [t for t, _, _ in pick]
        rights = [f'[{tnum(a)}; {tnum(b)}]' for _, _, (a, b) in pick]
        q = (f'Число m равно {name}. Установите соответствие между числами и отрезками из правого столбца. '
             f'В таблице под каждой буквой укажите соответствующий номер.')
        c = match_card(r, lefts, rights, [0, 1, 2, 3], q, e=f'm ≈ {ap(mf, 2)}; оцениваем каждое выражение.')
        ans = match_answer(c)
        vals = {t: v for t, v, _ in pick}

        def chk():
            for L_, seg in ans.items():
                a, b = [int(x.replace('−', '-')) for x in seg.strip('[]').split('; ')]
                v = float(sp.N(vals[L_]))
                if not a <= v <= b:
                    return False
            return True
        return c, chk
    pick = []
    for t, fn in exprs:
        v = fn(m)
        if not v.is_real:
            continue
        vf = float(sp.N(v))
        if -3.8 < vf < 3.8 and all(abs(vf - float(sp.N(p_[1]))) > 0.4 for p_ in pick):
            pick.append((t, v))
        if len(pick) == 4:
            break
    if len(pick) < 4:
        return None
    order = sorted(range(4), key=lambda i: float(sp.N(pick[i][1])))
    labels = 'ABCD'
    svg = numline_svg([(float(sp.N(pick[i][1])), labels[k]) for k, i in enumerate(order)], -4, 4)
    rights = [pick[i][0] for i in order]
    q = (f'На координатной прямой отмечены точки A, B, C и D. Число m равно {name}. Каждой точке соответствует одно из чисел '
         f'в правом столбце. Установите соответствие между указанными точками и числами. В таблице под каждой буквой укажите '
         f'соответствующий номер.')
    c = match_card(r, list(labels), rights, [0, 1, 2, 3], q, e=f'm ≈ {ap(mf, 2)}; вычисляем значения и сравниваем с положением точек.')
    c['svg'] = svg
    ans = match_answer(c)
    vals = {t: v for t, v in pick}

    def chk():
        vs = [float(sp.N(vals[ans[L_]])) for L_ in labels]
        return all(vs[i] < vs[i + 1] for i in range(3))
    return c, chk


@P('eb18-domains', 'Функции и их области определения (соответствие)',
   'Корень чётной степени — подкоренное выражение неотрицательно; логарифм — аргумент положителен; знаменатель не равен нулю.',
   'Вид функций (с корнем, логарифмом, дробью), числа.',
   'область определения каждой функции',
   r'область её определения|областями определения',
   ['забывают, что под корнем может быть ноль', 'для логарифма пишут нестрогое неравенство'],
   'Два столбца (функции — области определения); ответ — четыре цифры.', kes=['3.2'])
def gen_eb18_domains(r):
    a = r.randint(-6, 6)
    forms = [(f'y = √({xm(a)})', f'sqrt(x-({a}))', f'[{tnum(a)}; +∞)'), (f'y = log₂({xm(a)})', f'log(x-({a}),2)', f'({tnum(a)}; +∞)'),
             (f'y = 1/({xm(a)})', f'1/(x-({a}))', f'(−∞; {tnum(a)}) ∪ ({tnum(a)}; +∞)'),
             (f'y = √({tnum(a)} − x)' if a else 'y = √(−x)', f'sqrt({a}-x)', f'(−∞; {tnum(a)}]')]
    forms = [(fix_signs(t), s_, d) for t, s_, d in forms]
    r.shuffle(forms)
    c = match_card(r, [t for t, _, _ in forms], [d for _, _, d in forms], [0, 1, 2, 3],
                   'Установите соответствие между функциями и их областями определения. В таблице под каждой буквой укажите '
                   'соответствующий номер.', e='Корень — не меньше нуля, логарифм — больше нуля, знаменатель — не нуль.')
    ans = match_answer(c)
    sy = {t: s_ for t, s_, _ in forms}

    def chk():
        x = sp.Symbol('x', real=True)
        for L_, dom in ans.items():
            got = sp.calculus.util.continuous_domain(sp.sympify(sy[L_], locals={'x': x}), x, sp.S.Reals)
            want = {f'[{tnum(a)}; +∞)': sp.Interval(a, sp.oo), f'({tnum(a)}; +∞)': sp.Interval.open(a, sp.oo),
                    f'(−∞; {tnum(a)}) ∪ ({tnum(a)}; +∞)': sp.Union(sp.Interval.open(-sp.oo, a), sp.Interval.open(a, sp.oo)),
                    f'(−∞; {tnum(a)}]': sp.Interval(-sp.oo, a)}[dom]
            if got != want:
                return False
        return True
    return c, chk


# ================================================================ 19. Цифры и делимость (ответ однозначный: наименьшее/наибольшее)

def digits(n):
    return [int(ch) for ch in str(n)]


def extreme_card(r, q_small, q_big, cands, e_hint, check_fn):
    """Карточка «наименьшее/наибольшее такое число»: cands — все подходящие числа (перебор), check_fn(n) — независимая проверка
    свойства числа (другим способом); проверяем, что ответ — крайний среди всех чисел диапазона, удовлетворяющих check_fn."""
    if len(cands) < 2:
        return None
    small = r.random() < 0.5
    ans = min(cands) if small else max(cands)
    q = q_small if small else q_big
    return ans, q, small


@P('eb19-digits-kind', 'Число заданной длины, кратное M, все цифры которого различны и (не)чётны',
   'Используем признаки делимости (на 5, 25, 4, 8, 9, 11 …) и ограничения на цифры; перебираем от наименьшего (наибольшего).',
   'Число цифр, делитель, условие на цифры (все чётные / все нечётные / все различные), наименьшее или наибольшее.',
   'крайнее число среди подходящих',
   r'все цифры которого различны и (чётны|нечётны)',
   ['забывают, что 0 — чётная цифра и не может стоять первой', 'нарушают различность цифр'],
   '«Найдите наименьшее (наибольшее) … число …» — у нас ответ однозначен (в КИМ — «какое-нибудь одно»).', kes=['1.1'])
def gen_eb19_digits_kind(r):
    n = r.choice([3, 4, 4, 5])
    kind = r.choice(['чётные', 'нечётные', 'различные'])
    M = r.choice([4, 5, 6, 8, 9, 12, 15, 18, 20, 24, 25, 36, 44, 45, 55, 75, 88] if kind != 'нечётные' else [5, 9, 11, 15, 25, 35, 45, 55, 75])
    lo, hi = 10 ** (n - 1), 10 ** n
    ok_d = {'чётные': set('02468'), 'нечётные': set('13579'), 'различные': set('0123456789')}[kind]
    cands = [x for x in range(lo + (-lo) % M, hi, M) if len(set(str(x))) == n and set(str(x)) <= ok_d]
    res = extreme_card(r, None, None, cands, '', None)
    if not res:
        return None
    ans, _, small = res
    word = {3: 'трёхзначное', 4: 'четырёхзначное', 5: 'пятизначное'}[n]
    cond = {'чётные': 'все цифры разные и чётные', 'нечётные': 'все цифры разные и нечётные', 'различные': 'все цифры разные'}[kind]
    q = (f'Среди {word.replace("ое", "ых")} чисел, делящихся на {M}, выберите {"наименьшее" if small else "наибольшее"} число, у которого '
         f'{cond}. Запишите это число в ответ.')

    def chk():
        rng = range(lo, hi) if small else range(hi - 1, lo - 1, -1)
        for x in rng:
            ds = str(x)
            if x % M == 0 and len(ds) == len(set(ds)) and all(ch in ok_d for ch in ds):
                return x == ans
        return False
    return pcard(q, num(ans), e=f'Ответ: {ans}.'), chk


@P('eb19-cross-out', 'Вычеркнуть цифры так, чтобы число делилось на d',
   'Признак делимости на d (4, 6, 12, 15, 18, 22, 45 …): последние цифры и сумма цифр; перебираем варианты вычёркивания.',
   'Исходное число (7–8 цифр), сколько цифр вычеркнуть, делитель, наименьший или наибольший результат.',
   'крайнее из чисел, получаемых вычёркиванием, которые делятся на d',
   r'Вычеркните в числе',
   ['меняют порядок оставшихся цифр', 'забывают про последнюю цифру'],
   '«Вычеркните в числе … три цифры так, чтобы … В ответе укажите наибольшее (наименьшее) из возможных чисел.»', kes=['1.1'])
def gen_eb19_cross_out(r):
    L = r.choice([7, 8])
    N = ''.join(str(r.randint(1, 9)) for _ in range(L))
    k = 3
    d = r.choice([4, 6, 12, 15, 18, 22, 24, 33, 36, 45])
    cands = set()
    for keep in itertools.combinations(range(L), L - k):
        v = int(''.join(N[i] for i in keep))
        if v % d == 0:
            cands.add(v)
    if len(cands) < 2:
        return None
    small = r.random() < 0.5
    ans = min(cands) if small else max(cands)
    q = (f'В записи числа {N} зачеркнули три цифры, не меняя порядка остальных, и получили число, делящееся на {d}. Какое '
         f'{"наименьшее" if small else "наибольшее"} число могло получиться?')

    def chk():
        # независимо: перебираем все подпоследовательности длины L − 3 через маски
        vals = []
        for mask in range(1 << L):
            if bin(mask).count('1') == L - k:
                v = int(''.join(N[i] for i in range(L) if mask >> i & 1))
                if v % d == 0:
                    vals.append(v)
        return (min(vals) if small else max(vals)) == ans
    return pcard(q, num(ans), e=f'Ответ: {ans}.'), chk


@P('eb19-digit-product', 'Число, кратное M, с заданным произведением (суммой) цифр',
   'Разложить произведение цифр на множители-цифры (или подобрать сумму) и учесть признак делимости.',
   'Число цифр, делитель, произведение (или его границы) или сумма цифр, диапазон, наименьшее/наибольшее.',
   'крайнее подходящее число',
   r'(произведение цифр которого|сумма цифр которого равна)',
   ['забывают про цифру 1 в разложении', 'нарушают признак делимости'],
   '«Найдите наименьшее четырёхзначное число, кратное …, произведение цифр которого …»', kes=['1.1'])
def gen_eb19_digit_product(r):
    st = r.randrange(3)
    n = r.choice([4, 4, 5])
    lo, hi = 10 ** (n - 1), 10 ** n
    M = r.choice([6, 12, 15, 18, 22, 24, 25, 36, 45, 55, 75])
    if st == 0:
        P_ = r.choice([10, 12, 18, 20, 24, 30, 36, 40, 45, 60, 72, 90])
        test = lambda x: math.prod(digits(x)) == P_
        cond = f'а произведение его цифр равно {P_}'
    elif st == 1:
        a = r.randint(20, 80)
        b = a + r.randint(4, 12)
        test = lambda x: a < math.prod(digits(x)) < b
        cond = f'а произведение его цифр лежит строго между {a} и {b}'
    else:
        S_ = r.randint(10, 30)
        L_ = r.choice(range(lo, hi - 1000, 100))
        U_ = L_ + r.choice([300, 500, 800, 1000])
        test = lambda x: sum(digits(x)) == S_ and L_ < x < U_
        cond = f'а сумма его цифр равна {S_}; само число заключено между {T(L_)} и {T(U_)}'
    cands = [x for x in range(lo + (-lo) % M, hi, M) if test(x)]
    if len(cands) < 2:
        return None
    small = r.random() < 0.5
    ans = min(cands) if small else max(cands)
    word = {4: 'четырёхзначное', 5: 'пятизначное'}[n]
    q = f'{word.capitalize()} число кратно {M}, {cond}. Каким {"наименьшим" if small else "наибольшим"} может быть такое число?'

    def chk():
        good = [x for x in range(lo, hi) if x % M == 0 and test(x)]
        return (good[0] if small else good[-1]) == ans
    return pcard(q, num(ans), e=f'Ответ: {ans}.'), chk


@P('eb19-reverse', 'Число и число, записанное теми же цифрами в обратном порядке',
   'Разность числа и «перевёртыша» выражается через разности цифр: 999(a − d) + 90(b − c); из делимости на 5 последняя цифра — 5.',
   'Число цифр (4), делитель (5), разность, наименьшее/наибольшее исходное число.',
   'крайнее число с данной разностью',
   r'Цифры четырёхзначного (натурального )?числа, кратного 5, записали в обратном порядке',
   ['забывают, что перевёртыш тоже четырёхзначный', 'неверно раскладывают разность'],
   '«Цифры четырёхзначного числа, кратного 5, записали в обратном порядке… Найдите наименьшее (наибольшее) исходное число.»', kes=['1.1'])
def gen_eb19_reverse(r):
    a, b, c = r.randint(6, 9), r.randint(0, 9), r.randint(0, 9)
    x0 = int(f'{a}{b}{c}5')
    D = x0 - int(str(x0)[::-1])
    if D <= 0:
        return None
    cands = [x for x in range(1005, 10000, 5) if str(x)[::-1][0] != '0' and x - int(str(x)[::-1]) == D]
    if len(cands) < 2:
        return None
    small = r.random() < 0.5
    ans = min(cands) if small else max(cands)
    q = (f'Четырёхзначное число делится на 5. Его цифры переставили в обратном порядке и из исходного числа вычли полученное '
         f'четырёхзначное число; вышло {D}. Найдите {"наименьшее" if small else "наибольшее"} возможное исходное число.')

    def chk():
        good = []
        for d1 in range(1, 10):
            for d2 in range(10):
                for d3 in range(10):
                    xx = 1000 * d1 + 100 * d2 + 10 * d3 + 5
                    rev = 5000 + 100 * d3 + 10 * d2 + d1
                    if xx - rev == D:
                        good.append(xx)
        return (min(good) if small else max(good)) == ans
    return pcard(q, num(ans), e=f'Ответ: {ans}.'), chk


@P('eb19-double', 'Два числа из заданных наборов цифр, одно вдвое больше другого',
   'Перебор перестановок цифр A и проверка, что 2A составлено из цифр набора B.',
   'Наборы цифр, условие на A (наибольшее/наименьшее).',
   'крайнее A из подходящих',
   r'составлено из цифр|состоит из цифр',
   ['не проверяют перенос разрядов при удвоении'],
   '«Четырёхзначное число A составлено из цифр …, а B — из цифр … Известно, что B = 2A. Найдите наибольшее A.»', kes=['1.1'])
def gen_eb19_double(r):
    A_ = r.randint(1000, 4999)
    if len(set(str(A_))) < 4:
        return None
    B_ = 2 * A_
    da, db = sorted(str(A_)), sorted(str(B_))
    cands = [int(''.join(p_)) for p_ in set(itertools.permutations(da)) if p_[0] != '0' and sorted(str(2 * int(''.join(p_)))) == db]
    cands = sorted(set(cands))
    if len(cands) < 2:
        return None
    small = r.random() < 0.5
    ans = min(cands) if small else max(cands)
    q = (f'Четырёхзначное число A записывается цифрами {", ".join(da)} (каждая по одному разу), а четырёхзначное число B — цифрами '
         f'{", ".join(db)}. Известно, что B = 2A. Найдите {"наименьшее" if small else "наибольшее"} возможное значение A.')

    def chk():
        good = [x for x in range(1000, 5000) if sorted(str(x)) == da and sorted(str(2 * x)) == db]
        return (min(good) if small else max(good)) == ans
    return pcard(q, num(ans), e=f'Ответ: {ans}.'), chk


@P('eb19-digit-sum-shift', 'Суммы цифр числа A и A + k делятся на m',
   'При прибавлении k без переноса сумма цифр растёт на k; чтобы обе суммы делились на m, нужен перенос через разряд '
   '(каждый перенос уменьшает сумму на 9).',
   'Число цифр, k, m, диапазон, наименьшее/наибольшее.',
   'крайнее подходящее A',
   r'сумма цифр числа A \+ \d+ делится',
   ['не учитывают перенос через разряд'],
   '«Найдите трёхзначное число A: сумма цифр A делится на m; сумма цифр A + k делится на m …» — у нас наименьшее/наибольшее.', kes=['1.1'])
def gen_eb19_digit_sum_shift(r):
    m = r.choice([5, 7, 8, 9, 10, 12])
    k = r.randint(2, 9)
    lo_ = r.choice([100, 200, 300, 400, 500, 600, 700])
    hi_ = lo_ + r.choice([100, 200, 300])
    ds = lambda x: sum(digits(x))
    cands = [x for x in range(lo_ + 1, hi_) if ds(x) % m == 0 and ds(x + k) % m == 0]
    if len(cands) < 2:
        return None
    small = r.random() < 0.5
    ans = min(cands) if small else max(cands)
    q = (f'У трёхзначного числа A, лежащего строго между {lo_} и {hi_}, сумма цифр кратна {m}. Если к A прибавить {k}, то у '
         f'получившегося числа сумма цифр тоже будет кратна {m}. Каким {"наименьшим" if small else "наибольшим"} может быть A?')

    def chk():
        good = []
        for x in range(lo_ + 1, hi_):
            s1 = x // 100 + x // 10 % 10 + x % 10
            y = x + k
            s2 = y // 1000 + y // 100 % 10 + y // 10 % 10 + y % 10
            if s1 % m == 0 and s2 % m == 0:
                good.append(x)
        return (min(good) if small else max(good)) == ans
    return pcard(q, num(ans), e=f'Ответ: {ans}.'), chk


@P('eb19-power', 'Четырёхзначное число, в k раз меньшее куба (четвёртой степени)',
   'Число = n³/k (или n⁴/k) должно быть целым и четырёхзначным: n кратно нужным множителям k.',
   'k, показатель степени, наименьшее/наибольшее.',
   'крайнее подходящее число',
   r'раза? меньше (куба|четвёртой степени)',
   ['не проверяют, что частное целое', 'выходят за пределы четырёхзначных'],
   '«Найдите четырёхзначное число, которое в k раз меньше куба некоторого натурального числа» — у нас наименьшее/наибольшее.', kes=['1.1', '1.4'])
def gen_eb19_power(r):
    e_ = r.choice([2, 3, 3, 4])
    nd = r.choice([3, 4, 4, 5])
    lo, hi = 10 ** (nd - 1), 10 ** nd
    word = {3: 'трёхзначное', 4: 'четырёхзначное', 5: 'пятизначное'}[nd]
    k = r.choice({2: [2, 3, 5, 6, 7, 10, 11, 13, 15], 3: [2, 3, 4, 5, 6, 9, 12, 18, 25], 4: [2, 3, 4, 8, 16]}[e_])
    cands = sorted({n ** e_ // k for n in range(1, 2000) if (n ** e_) % k == 0 and lo <= n ** e_ // k < hi})
    if len(cands) < 2:
        return None
    small = r.random() < 0.5
    ans = min(cands) if small else max(cands)
    what = {2: 'точный квадрат', 3: 'точный куб', 4: 'четвёртую степень'}[e_]
    q = (f'Какое {"наименьшее" if small else "наибольшее"} {word} число после умножения на {k} даёт {what} натурального числа?')

    def chk():
        good = [x for x in range(lo, hi) if any(t ** e_ == x * k for t in (round((x * k) ** (1 / e_)) + dd for dd in (-1, 0, 1)))]
        return (min(good) if small else max(good)) == ans
    return pcard(q, num(ans), e=f'Ответ: {ans}.'), chk


@P('eb19-two-digits', 'Число только из двух цифр, делящееся на M',
   'Признаки делимости на 8 (последние три цифры), на 3/9 (сумма цифр), на 4 и т. п.; подбираем наименьшее/наибольшее.',
   'Число цифр (5–7), разрешённые цифры (0 и 2, 1 и 2, 0 и 5 …), делитель.',
   'крайнее подходящее число',
   r'записывается только цифрами',
   ['забывают про признак делимости на 8', 'ставят 0 первой цифрой'],
   '«Найдите шестизначное число, которое записывается только цифрами 2 и 0 и делится на 24» — у нас наименьшее/наибольшее.', kes=['1.1'], lim=10 ** 8)
def gen_eb19_two_digits(r):
    n = r.choice([5, 6, 7])
    d1, d2 = r.choice([(0, 2), (1, 2), (0, 5), (1, 3), (2, 4), (0, 7), (3, 6)])
    M = r.choice([12, 15, 18, 24, 36, 45, 48, 72])
    cands = [int(''.join(map(str, t))) for t in itertools.product((d1, d2), repeat=n) if t[0] != 0]
    cands = sorted(x for x in cands if x % M == 0 and len(set(str(x))) == 2)
    if len(cands) < 2:
        return None
    small = r.random() < 0.5
    ans = min(cands) if small else max(cands)
    word = {5: 'пятизначное', 6: 'шестизначное', 7: 'семизначное'}[n]
    q = (f'Найдите {"наименьшее" if small else "наибольшее"} {word} число, в записи которого есть только цифры {d1} и {d2} (обе цифры '
         f'встречаются) и которое делится на {M}.')

    def chk():
        good = [x for x in range(10 ** (n - 1), 10 ** n) if x % M == 0 and set(str(x)) == {str(d1), str(d2)}] if n <= 6 else \
            [x for x in cands if x % M == 0]
        return (min(good) if small else max(good)) == ans
    return pcard(q, num(ans), e=f'Ответ: {ans}.'), chk


@P('eb19-adjacent', 'Число, у которого соседние цифры отличаются на заданное число',
   'Строим число цифра за цифрой (соседние отличаются на d) и проверяем делимость на M.',
   'Число цифр, разность соседних цифр, делитель, наименьшее/наибольшее.',
   'крайнее подходящее число',
   r'любые две соседние цифры которого отличаются',
   ['нарушают условие на последних цифрах из-за признака делимости'],
   '«Найдите пятизначное число, кратное 15, любые две соседние цифры которого отличаются на 2» — у нас наименьшее/наибольшее.', kes=['1.1'])
def gen_eb19_adjacent(r):
    n = r.choice([4, 5])
    d = r.choice([1, 2, 3])
    M = r.choice([4, 5, 6, 9, 11, 12, 15, 25, 44])
    cands = []

    def grow(prefix):
        if len(prefix) == n:
            v = int(''.join(map(str, prefix)))
            if v % M == 0:
                cands.append(v)
            return
        for nx in (prefix[-1] - d, prefix[-1] + d):
            if 0 <= nx <= 9:
                grow(prefix + [nx])
    for first in range(1, 10):
        grow([first])
    if len(cands) < 2:
        return None
    small = r.random() < 0.5
    ans = min(cands) if small else max(cands)
    word = {4: 'четырёхзначное', 5: 'пятизначное'}[n]
    q = (f'У {word.replace("ое", "ого")} числа, делящегося на {M}, каждые две соседние цифры отличаются ровно на {d}. Найдите '
         f'{"наименьшее" if small else "наибольшее"} такое число.')

    def chk():
        good = [x for x in range(10 ** (n - 1), 10 ** n) if x % M == 0 and all(abs(int(a) - int(b)) == d for a, b in zip(str(x), str(x)[1:]))]
        return (min(good) if small else max(good)) == ans
    return pcard(q, num(ans), e=f'Ответ: {ans}.'), chk


@P('eb19-own-digits', 'Число, которое делится на каждую свою цифру (цифры различны)',
   'Перебираем числа в заданном диапазоне, проверяя делимость на каждую цифру и различие цифр.',
   'Число цифр, границы, наименьшее/наибольшее.',
   'крайнее подходящее число',
   r'делится на каждую свою цифру',
   ['забывают, что цифры не должны быть нулями', 'не проверяют различие цифр'],
   '«Найдите трёхзначное число, большее …, которое делится на каждую свою цифру …» — у нас наименьшее/наибольшее.', kes=['1.1'])
def gen_eb19_own_digits(r):
    n = r.choice([3, 4])
    lo_ = r.choice(range(10 ** (n - 1), 10 ** n - 500, 50))
    hi_ = lo_ + r.choice([300, 500, 800, 1000]) if n == 4 else lo_ + r.choice([150, 200, 300])
    cands = [x for x in range(lo_ + 1, min(hi_, 10 ** n)) if '0' not in str(x) and len(set(str(x))) == n and all(x % int(ch) == 0 for ch in str(x))]
    if len(cands) < 2:
        return None
    small = r.random() < 0.5
    ans = min(cands) if small else max(cands)
    q = (f'Найдите {"наименьшее" if small else "наибольшее"} число, большее {T(lo_)} и меньшее {T(hi_)}, которое делится на каждую свою '
         f'цифру, если все его цифры различны и отличны от нуля.')

    def chk():
        good = []
        for x in range(lo_ + 1, hi_):
            ds = digits(x)
            if 0 in ds or len(set(ds)) != len(ds) or len(ds) != n:
                continue
            if all(x % d == 0 for d in ds):
                good.append(x)
        return (min(good) if small else max(good)) == ans
    return pcard(q, num(ans), e=f'Ответ: {ans}.'), chk


@P('eb19-remainders', 'Равные остатки от деления на два числа и условие на цифры',
   'Равные остатки r при делении на a и b ⇒ число = НОК(a, b)·k + r; перебираем и проверяем условие на цифры.',
   'Делители, условие на цифры (первая = сумма двух других, последняя = среднее двух других), граница, наименьшее/наибольшее.',
   'крайнее подходящее число',
   r'даёт равные ненулевые остатки',
   ['берут нулевой остаток', 'путают НОК и произведение'],
   '«Найдите трёхзначное число, которое при делении и на 5, и на 16 даёт равные ненулевые остатки …» — у нас наименьшее/наибольшее.', kes=['1.1'])
def gen_eb19_remainders(r):
    a, b = r.choice([(5, 16), (4, 9), (5, 8), (3, 7), (6, 7), (4, 15), (8, 5), (9, 10), (7, 10), (4, 7), (5, 6), (6, 11), (4, 13),
                     (3, 8), (5, 12), (7, 9)])
    cond = r.choice(['first', 'last', 'none', 'odd'])
    tests = {'first': lambda x: x // 100 == x // 10 % 10 + x % 10, 'last': lambda x: 2 * (x % 10) == x // 100 + x // 10 % 10,
             'none': lambda x: True, 'odd': lambda x: all(int(c_) % 2 for c_ in str(x))}
    txt = {'first': 'первая цифра которого равна сумме двух других цифр', 'last': 'последняя цифра которого равна среднему арифметическому двух других',
           'none': 'все цифры которого различны', 'odd': 'все цифры которого нечётны'}
    if cond == 'none':
        tests['none'] = lambda x: len(set(str(x))) == 3
    cands = [x for x in range(100, 1000) if x % a == x % b != 0 and tests[cond](x)]
    if len(cands) < 2:
        return None
    small = r.random() < 0.5
    ans = min(cands) if small else max(cands)
    q = (f'Найдите {"наименьшее" if small else "наибольшее"} трёхзначное число, которое при делении на {a} и при делении на {b} даёт '
         f'одинаковые ненулевые остатки и {txt[cond]}.')

    def chk():
        L = a * b // math.gcd(a, b)
        good = [L * k + rr for k in range(0, 1000 // L + 1) for rr in range(1, min(a, b)) if 100 <= L * k + rr <= 999]
        good = sorted(x for x in good if tests[cond](x))
        return (good[0] if small else good[-1]) == ans
    return pcard(q, num(ans), e=f'Ответ: {ans}.'), chk


@functools.lru_cache(None)
def _sp_cands(n, dlt, parity):
    return [x for x in range(10 ** (n - 1), 10 ** n) if (x % 2 == 0) == (parity == 'чётное') and sum(digits(x)) + dlt == math.prod(digits(x))]


@P('eb19-sum-product', 'Сумма цифр и произведение цифр связаны условием',
   'Перебираем числа (чётные, заданной длины) и проверяем связь суммы и произведения цифр.',
   'Длина числа, условие (сумма = произведение, сумма на 1 меньше произведения), чётность, наименьшее/наибольшее.',
   'крайнее подходящее число',
   r'сумма цифр которого (равна их произведению|на \d+ меньше их произведения)',
   ['не проверяют чётность', 'путают сумму и произведение'],
   '«Найдите чётное трёхзначное число, сумма цифр которого на 1 меньше их произведения» — у нас наименьшее/наибольшее.', kes=['1.1'])
def gen_eb19_sum_product(r):
    n = r.choice([3, 4, 5])
    dlt = r.choice([0, 1, 2, 3, 4])
    parity = r.choice(['чётное', 'нечётное'])
    cands = _sp_cands(n, dlt, parity)
    if len(cands) < 2:
        return None
    small = r.random() < 0.5
    ans = min(cands) if small else max(cands)
    word = {3: 'трёхзначное', 4: 'четырёхзначное', 5: 'пятизначное'}[n]
    cond = 'произведение цифр совпадает с суммой цифр' if dlt == 0 else f'произведение цифр на {dlt} больше суммы цифр'
    q = r.choice([f'У {parity[:-2]}ого {word[:-2]}ого числа {cond}. Каким {"наименьшим" if small else "наибольшим"} может быть такое число?',
                  f'Какое {"наименьшее" if small else "наибольшее"} {parity} {word} число обладает свойством: {cond}?'])

    def chk():
        good = []
        for x in range(10 ** (n - 1), 10 ** n):
            ds = [int(c_) for c_ in str(x)]
            pr = 1
            for d_ in ds:
                pr *= d_
            if (ds[-1] % 2 == 0) == (parity == 'чётное') and sum(ds) + dlt == pr:
                good.append(x)
        return (min(good) if small else max(good)) == ans
    return pcard(q, num(ans), e=f'Ответ: {ans}.'), chk


@P('eb19-squares', 'Сумма квадратов цифр делится на одно число и не делится на другое',
   'Перебираем кратные M с различными цифрами и проверяем делимость суммы квадратов цифр.',
   'Делитель M, делимость суммы квадратов (на 5 не на 25, на 4 не на 16 …), наименьшее/наибольшее.',
   'крайнее подходящее число',
   r'сумма квадратов цифр делится',
   ['путают сумму квадратов и квадрат суммы'],
   '«Найдите трёхзначное число, кратное 11, все цифры которого различны, а сумма квадратов цифр делится на 4, но не делится на 16.»', kes=['1.1'])
def gen_eb19_squares(r):
    M = r.choice([6, 9, 11, 12, 14, 15, 18, 20, 21, 22, 25, 30, 33, 35, 45, 60])
    p_, q_ = r.choice([(5, 25), (4, 16), (3, 9), (2, 4), (10, 100), (7, 49), (13, 26), (6, 12), (5, 10)])
    cands = [x for x in range(100 + (-100) % M, 1000, M) if len(set(str(x))) == 3 and sum(d * d for d in digits(x)) % p_ == 0 and
             sum(d * d for d in digits(x)) % q_ != 0]
    if len(cands) < 2:
        return None
    small = r.random() < 0.5
    ans = min(cands) if small else max(cands)
    q = (f'Трёхзначное число делится на {M}, все его цифры различны, а сумма квадратов его цифр делится на {p_}, но не делится на {q_}. '
         f'Найдите {"наименьшее" if small else "наибольшее"} такое число.')

    def chk():
        good = [x for x in range(100, 1000) if x % M == 0 and len(set(str(x))) == 3 and sum(int(c_) ** 2 for c_ in str(x)) % p_ == 0
                and sum(int(c_) ** 2 for c_ in str(x)) % q_ != 0]
        return (min(good) if small else max(good)) == ans
    return pcard(q, num(ans), e=f'Ответ: {ans}.'), chk


@P('eb19-cards', 'Карточки с цифрами: составить два числа, сумма которых делится на заданное',
   'Перебираем расстановки карточек в записи двух трёхзначных чисел и отбираем суммы с нужной делимостью.',
   'Набор из шести цифр, условие делимости суммы (на 10, но не на 20; на 5, но не на 10 …), наименьшая/наибольшая сумма.',
   'крайняя подходящая сумма',
   r'На шести карточках написаны цифры',
   ['используют карточку дважды', 'не проверяют второе условие'],
   '«На шести карточках написаны цифры … В ответе запишите наименьшую (наибольшую) такую сумму.»', kes=['1.1'])
def gen_eb19_cards(r):
    ds = sorted(r.choice(range(1, 10)) for _ in range(6))
    p_, q_ = r.choice([(10, 20), (5, 10), (4, 8), (3, 9), (10, 30)])
    sums = set()
    for perm in set(itertools.permutations(ds)):
        a = perm[0] * 100 + perm[1] * 10 + perm[2]
        b = perm[3] * 100 + perm[4] * 10 + perm[5]
        sm = a + b
        if sm % p_ == 0 and sm % q_ != 0:
            sums.add(sm)
    if len(sums) < 2:
        return None
    small = r.random() < 0.5
    ans = min(sums) if small else max(sums)
    sh = ds[:]
    r.shuffle(sh)
    q = (f'Есть шесть карточек, на каждой — одна цифра: {", ".join(map(str, sh[:5]))} и {sh[5]}. Все карточки разложили в два ряда '
         f'по три так, что получились два трёхзначных числа, и сложили эти числа. Сумма '
         f'оказалась кратна {p_}, а кратной {q_} не оказалась. Какой {"наименьшей" if small else "наибольшей"} могла быть эта сумма?')

    def chk():
        best = None
        for idx in itertools.permutations(range(6)):
            v = [ds[i] for i in idx]
            sm = 100 * (v[0] + v[3]) + 10 * (v[1] + v[4]) + v[2] + v[5]
            if sm % p_ == 0 and sm % q_ != 0:
                best = sm if best is None else (min(best, sm) if small else max(best, sm))
        return best == ans
    return pcard(q, num(ans), e=f'Ответ: {ans}.'), chk



@P('eb19-same-digits', 'Число из одинаковых цифр, делящееся на M',
   'Число из k одинаковых цифр a равно a·11…1 (111 = 3·37, 1111 = 11·101); делимость на M сводится к делимости a на M / НОД(M, 11…1).',
   'Число цифр (3–5), делитель, наименьшее/наибольшее.',
   'крайнее подходящее число',
   r'записанное одинаковыми цифрами',
   ['не раскладывают 111 = 3·37', 'берут число вне диапазона'],
   '«Найдите наименьшее трёхзначное число, записанное одинаковыми цифрами и делящееся на 37.»', kes=['1.1'])
def gen_eb19_same_digits(r):
    n = r.choice([3, 4, 5, 6])
    M = r.choice([6, 12, 14, 21, 22, 24, 26, 28, 33, 37, 39, 44, 55, 74, 77, 91, 101, 111, 202, 303, 407])
    cands = [int(str(a) * n) for a in range(1, 10) if int(str(a) * n) % M == 0]
    if len(cands) < 2:
        return None
    small = r.random() < 0.5
    ans = min(cands) if small else max(cands)
    word = {3: 'трёхзначных', 4: 'четырёхзначных', 5: 'пятизначных', 6: 'шестизначных'}[n]
    q = r.choice([f'Все цифры числа одинаковы, число делится на {M}. Какое {"наименьшее" if small else "наибольшее"} из таких {word} чисел?',
                  f'Среди {word} чисел, у которых все цифры одинаковые, найдите {"наименьшее" if small else "наибольшее"} кратное {M}.'])

    def chk():
        rep = (10 ** n - 1) // 9
        good = [a * rep for a in range(1, 10) if (a * rep) % M == 0]
        return (good[0] if small else good[-1]) == ans
    return pcard(q, num(ans), e=f'Ответ: {ans}.'), chk


@P('eb19-no-digit', 'Наибольшее (наименьшее) число без заданной цифры, кратное M',
   'Идём от 999 (от 100) по кратным M и пропускаем числа, в записи которых есть запрещённая цифра.',
   'Запрещённая цифра, делитель, число цифр, наименьшее/наибольшее.',
   'крайнее подходящее число',
   r'в записи которого не используется цифра',
   ['не замечают запрещённую цифру в середине числа'],
   '«Найдите наибольшее трёхзначное число, в записи которого не используется цифра 9 и которое нацело делится на 7.»', kes=['1.1'])
def gen_eb19_no_digit(r):
    n = r.choice([3, 3, 4])
    bad = r.choice('0123456789')
    small = r.random() < 0.5
    if small and bad == '1':
        return None
    M = r.randint(3, 60)
    lo, hi = 10 ** (n - 1), 10 ** n
    cands = [x for x in range(lo + (-lo) % M, hi, M) if bad not in str(x)]
    if len(cands) < 2:
        return None
    ans = min(cands) if small else max(cands)
    triv = min(x for x in range(lo + (-lo) % M, hi, M)) if small else max(range(lo + (-lo) % M, hi, M))
    if triv == ans:
        return None
    word = {3: 'трёхзначное', 4: 'четырёхзначное'}[n]
    q = r.choice([f'Найдите {"наименьшее" if small else "наибольшее"} {word} число, кратное {M}, в записи которого нет цифры {bad}.',
                  f'Цифра {bad} в записи числа не встречается, а само {word} число делится на {M} без остатка. Каким '
                  f'{"наименьшим" if small else "наибольшим"} может быть это число?'])

    def chk():
        rng = range(lo, hi) if small else range(hi - 1, lo - 1, -1)
        for x in rng:
            if x % M == 0 and all(c_ != bad for c_ in str(x)):
                return x == ans
    return pcard(q, num(ans), e=f'Ответ: {ans}.'), chk


@P('eb19-monotone', 'Число в диапазоне, кратное M, цифры которого убывают (возрастают)',
   'Признак делимости (на 90: последняя цифра 0 и сумма цифр кратна 9) плюс перебор убывающих (возрастающих) наборов цифр.',
   'Границы, делитель, убывание/возрастание цифр, наименьшее/наибольшее.',
   'крайнее подходящее число',
   r'каждая следующая цифра которого (меньше|больше) предыдущей',
   ['допускают равные соседние цифры'],
   '«Найдите четырёхзначное число, большее …, но меньшее …, которое делится на 90 и каждая следующая цифра которого меньше предыдущей.»', kes=['1.1'])
def gen_eb19_monotone(r):
    dec_ = r.random() < 0.6
    M = r.choice([15, 18, 30, 36, 45, 60, 90, 9, 12, 24] if dec_ else [3, 6, 9, 12, 15, 18, 24, 27, 36, 45])
    lo_ = r.randrange(1000, 8000, 250)
    hi_ = lo_ + r.choice([1000, 1500, 2000, 2500, 3000])
    if hi_ > 10000:
        return None
    mono = lambda x: all((a > b) if dec_ else (a < b) for a, b in zip(str(x), str(x)[1:]))
    cands = [x for x in range(lo_ + 1, hi_) if x % M == 0 and mono(x)]
    if len(cands) < 2:
        return None
    small = r.random() < 0.5
    ans = min(cands) if small else max(cands)
    q = (f'Четырёхзначное число заключено между {T(lo_)} и {T(hi_)} и делится на {M}; при чтении слева направо его цифры '
         f'{"строго убывают" if dec_ else "строго возрастают"}. Найдите {"наименьшее" if small else "наибольшее"} такое число.')

    def chk():
        good = []
        for c in itertools.combinations(range(10), 4):
            x = int(''.join(map(str, c[::-1] if dec_ else c)))
            if lo_ < x < hi_ and x % M == 0 and x >= 1000:
                good.append(x)
        return (min(good) if small else max(good)) == ans
    return pcard(q, num(ans), e=f'Ответ: {ans}.'), chk


@P('eb19-common-rem', 'Одинаковый остаток при делении на несколько чисел и условие на цифры',
   'Число = НОК·k + r; из кандидатов отбираем числа с нужным свойством цифр (только две разные цифры, чётные цифры, цифры по возрастанию).',
   'Делители (2–3), остаток, граница, свойство цифр, наименьшее/наибольшее.',
   'крайнее подходящее число',
   r'при делении и на \d+, и на \d+',
   ['берут произведение делителей вместо НОК', 'забывают прибавить остаток'],
   '«Найдите трёхзначное число, которое при делении и на 3, и на 5, и на 7 даёт в остатке 2 и …»', kes=['1.1'])
def gen_eb19_common_rem(r):
    ds = r.choice([(3, 5, 7), (3, 4, 5), (4, 5, 6), (3, 5), (4, 7), (5, 6), (3, 8), (2, 9), (4, 9), (2, 5, 7), (3, 4, 7), (6, 7)])
    rem = r.randint(1, min(ds) - 1)
    prop = r.choice(['two', 'even', 'up', 'down', 'odd'])
    ptxt = {'two': 'в его записи ровно две различные цифры', 'even': 'все его цифры чётные', 'odd': 'все его цифры нечётные',
            'up': 'его цифры идут в порядке возрастания', 'down': 'его цифры идут в порядке убывания'}[prop]
    ptest = {'two': lambda x: len(set(str(x))) == 2, 'even': lambda x: all(int(c_) % 2 == 0 for c_ in str(x)),
             'odd': lambda x: all(int(c_) % 2 for c_ in str(x)),
             'up': lambda x: all(a < b for a, b in zip(str(x), str(x)[1:])),
             'down': lambda x: all(a > b for a, b in zip(str(x), str(x)[1:]))}[prop]
    cands = [x for x in range(100, 1000) if all(x % d == rem for d in ds) and ptest(x)]
    if len(cands) < 2:
        return None
    small = r.random() < 0.5
    ans = min(cands) if small else max(cands)
    dtxt = ', '.join(map(str, ds[:-1])) + ' и ' + str(ds[-1])
    q = (f'Трёхзначное число при делении на каждое из чисел {dtxt} даёт остаток {rem}, а {ptxt}. Найдите '
         f'{"наименьшее" if small else "наибольшее"} такое число.')

    def chk():
        L = 1
        for d in ds:
            L = L * d // math.gcd(L, d)
        good = sorted(x for x in range(rem, 1000, L) if x >= 100 and ptest(x))
        return (good[0] if small else good[-1]) == ans
    return pcard(q, num(ans), e=f'Ответ: {ans}.'), chk



# ================================================================ 20. Текстовые задачи (движение, работа, смеси, проценты)

def km(x):
    return pl(x, 'километр', 'километра', 'километров')


def kmh(x):
    return f'{T(x)} км/ч'


def hrs(x):
    return pl(x, 'час', 'часа', 'часов')


def mins_(x):
    return pl(x, 'минута', 'минуты', 'минут')


@P('eb20-walk-back', 'Встреча, когда один дошёл до цели и повернул обратно',
   'К моменту встречи быстрый прошёл d + (d − x), медленный — x за то же время: x / v₁ = (2d − x) / v₂, x = 2d·v₁ / (v₁ + v₂).',
   'Сюжет (прогулка до опушки, пловцы в бассейне, лыжники до флажка, курьеры до склада), расстояние, скорости, что спрашивают.',
   'x = 2d·v₁ / (v₁ + v₂) или d − x',
   r'до опушки леса|Дойдя до опушки',
   ['считают, что встреча в середине', 'путают расстояние от дома и от цели'],
   '«На каком расстоянии от дома произойдёт их встреча? Ответ дайте в километрах.»', maxdec=2)
def gen_eb20_walk_back(r):
    v1, v2 = r.choice([(2, 3), (3, 4), (3, 5), (4, 5), (4, 6), (2, 5), (3, 6), (5, 7), (F(5, 2), F(7, 2)), (F(12, 5), F(18, 5))])
    d = F(r.randint(8, 60), 10)
    x = 2 * d * v1 / (v1 + v2)
    ask_goal = r.random() < 0.35
    ans = d - x if ask_goal else x
    if not nice(ans, 2) or not nice(x, 2):
        return None
    st = r.randrange(4)
    if st == 0:
        q = (f'Два друга одновременно вышли из лагеря и по одной тропе направились к роднику, до которого {km(d)}. Первый шёл со '
             f'скоростью {kmh(v1)}, второй — {kmh(v2)}. Второй, набрав у родника воды, сразу с той же скоростью пошёл назад. '
             f'{"На каком расстоянии от родника" if ask_goal else "На каком расстоянии от лагеря"} они встретились? Ответ дайте в километрах.')
    elif st == 1:
        dm = d * 1000 if d * 1000 <= 3000 else None
        if dm is None or dm.denominator != 1:
            return None
        q = (f'Два лыжника одновременно стартовали по одной лыжне к поворотному флажку, стоящему в {pl(dm, "метре", "метрах", "метрах")} '
             f'от старта. Скорость первого — {kmh(v1)}, второго — {kmh(v2)}. Второй, обогнув флажок, тут же поехал обратно с '
             f'прежней скоростью. {"Сколько метров было от флажка" if ask_goal else "Сколько метров было от старта"} до места их '
             f'встречи?')
        ans = ans * 1000
    elif st == 2:
        q = (f'От посёлка до железнодорожной станции {km(d)}. Бабушка и внук одновременно вышли из посёлка на станцию. Бабушка шла '
             f'со скоростью {kmh(v1)}, внук — {kmh(v2)}. Дойдя до станции, внук тут же повернул назад и пошёл с той же скоростью '
             f'навстречу бабушке. {"Какое расстояние оставалось пройти бабушке до станции" if ask_goal else "Какое расстояние бабушка прошла"} '
             f'к моменту их встречи? Ответ дайте в километрах.')
    else:
        q = (f'Два туриста одновременно отправились от палатки к смотровой вышке, до которой по тропе {km(d)}. Один шёл со скоростью {kmh(v1)}, другой — со скоростью {kmh(v2)}. Второй, поднявшись на вышку, сразу пошёл '
             f'обратно тем же темпом. {"Найдите расстояние от вышки" if ask_goal else "Найдите расстояние от палатки"} до места '
             f'встречи туристов. Ответ дайте в километрах.')
    if not nice(ans, 2):
        return None
    t_ = sp.symbols('t', positive=True)
    t0 = sp.solve(sp.Eq(sp.Rational(v1) * t_ + sp.Rational(v2) * t_, 2 * sp.Rational(d)), t_)[0]

    def chk():
        xx = F(str(sp.Rational(v1) * t0))
        res = (d - xx) if ask_goal else xx
        return (res * (1000 if st == 1 else 1)) == ans
    return pcard(q, num(ans), e=f'До встречи вместе прошли 2 · {dec(d)} км: t = {ap(2 * d / (v1 + v2), 3)} ч; первый прошёл '
                                  f'{dec(x)} км. Ответ: {num(ans)}.'), chk


@P('eb20-solution', 'Концентрация после смешивания или разбавления',
   'Масса вещества сохраняется: c = (m₁c₁ + m₂c₂) / (m₁ + m₂); вода — раствор концентрации 0 %; «такое же количество» — среднее.',
   'Сюжет (раствор, сироп, рассол, уксус, сплав-лом), массы, проценты, вариант (долить воды, смешать два, поровну, выпарить).',
   'c = Σmᵢcᵢ / Σmᵢ',
   r'процентного (водного )?раствора',
   ['складывают проценты', 'забывают, что вода увеличивает массу раствора'],
   '«Сколько процентов составляет концентрация получившегося раствора?»', maxdec=1)
def gen_eb20_solution(r):
    st = r.randrange(4)
    subst = r.choice([('соли', 'солевого раствора'), ('сахара', 'сахарного сиропа'), ('кислоты', 'раствора кислоты'),
                      ('спирта', 'спиртового раствора'), ('удобрения', 'раствора удобрения')])
    if st == 0:
        m1, c1, w = r.randint(2, 12), r.randint(5, 60), r.randint(1, 12)
        ans = F(m1 * c1, m1 + w)
        q = (f'К {pl(m1, "килограмму", "килограммам", "килограммам")} {subst[1]} с содержанием {subst[0]} {c1} % долили '
             f'{pl(w, "килограмм", "килограмма", "килограммов")} чистой воды. Сколько процентов составляет концентрация '
             f'{subst[0]} в новом растворе?')
    elif st == 1:
        m1, m2 = r.randint(2, 15), r.randint(2, 15)
        c1, c2 = r.sample(range(5, 70), 2)
        ans = F(m1 * c1 + m2 * c2, m1 + m2)
        q = (f'В одном бидоне {pl(m1, "литр", "литра", "литров")} {subst[1]}, в котором {c1} % {subst[0]}, в другом — '
             f'{pl(m2, "литр", "литра", "литров")} такого же раствора, но с содержанием {subst[0]} {c2} %. Содержимое бидонов слили в '
             f'одну ёмкость. Сколько процентов {subst[0]} в получившейся смеси?')
    elif st == 2:
        c1, c2 = r.sample(range(4, 60), 2)
        ans = F(c1 + c2, 2)
        q = (f'Лаборант взял некоторое количество {subst[1]} {c1} %-й концентрации и добавил к нему столько же по массе {subst[1]} {c2} %-й концентрации. '
             f'Сколько процентов составляет концентрация {subst[0]} в смеси?')
    else:
        m1, c1 = r.randint(5, 20), r.randint(4, 30)
        w = r.randint(1, m1 - 2)
        ans = F(m1 * c1, m1 - w)
        q = (f'Из {pl(m1, "килограмма", "килограммов", "килограммов")} {subst[1]}, содержащего {c1} % {subst[0]}, выпарили '
             f'{pl(w, "килограмм", "килограмма", "килограммов")} воды. Сколько процентов {subst[0]} содержит оставшийся раствор?')
    if not nice(ans, 1) or ans >= 100 or ans.denominator != 1 and r.random() < 0.6:
        return None
    ms = sp.symbols('ms')

    def chk():
        if st == 0:
            sub, tot = F(m1 * c1, 100), m1 + w
        elif st == 1:
            sub, tot = F(m1 * c1 + m2 * c2, 100), m1 + m2
        elif st == 2:
            sub, tot = F(c1 + c2, 100), 2
        else:
            sub, tot = F(m1 * c1, 100), m1 - w
        return sub / tot * 100 == ans
    return pcard(q, num(ans), e=f'Масса вещества делится на массу всего раствора. Ответ: {num(ans)} %.'), chk


@P('eb20-alloy', 'Два сплава дают третий: найти массу',
   'Правило рычага: m₁(c₁ − c) = m₂(c − c₂); масса третьего сплава m₁ + m₂.',
   'Металл, проценты, масса первого, что спрашивают (масса третьего, второго, на сколько больше).',
   'm₂ = m₁(c₁ − c)/(c − c₂)',
   r'Имеется два сплава|получили третий сплав',
   ['путают, какой сплав известен', 'меняют местами разности'],
   '«Имеется два сплава … Найдите массу третьего сплава. Ответ дайте в килограммах.»')
def gen_eb20_alloy(r):
    metal = r.choice([('олова', 'бронзы'), ('цинка', 'латуни'), ('серебра', 'сплава'), ('никеля', 'сплава'), ('золота', 'сплава'),
                      ('алюминия', 'сплава')])
    c1, c2 = r.sample(range(5, 80, 5), 2)
    c = r.randrange(min(c1, c2) + 5, max(c1, c2), 5) if abs(c1 - c2) > 5 else None
    if c is None:
        return None
    m1 = r.randrange(10, 150, 5)
    m2 = F(m1 * (c1 - c), c - c2)
    if m2 <= 0 or m2.denominator != 1:
        return None
    ask = r.randrange(3)
    ans = [m1 + m2, m2, abs(m2 - m1)][ask]
    if ans == 0:
        return None
    what = ['Найдите массу полученного слитка. Ответ дайте в килограммах', 'Сколько килограммов весил второй слиток',
            'На сколько килограммов масса одного из исходных слитков отличается от массы другого'][ask]
    st = r.randrange(4)
    head = [f'На заводе переплавили вместе два слитка. В первом {c1} % {metal[0]}, во втором — {c2} % {metal[0]}. ',
            f'Мастер сплавил два куска металла: один содержит {c1} % {metal[0]}, другой — {c2} % {metal[0]}. ',
            f'В литейном цехе переплавили вместе два слитка с долей {metal[0]} {c1} % и {c2} % соответственно. ',
            f'Для отливки взяли два слитка: в первом {metal[0]} {c1} %, во втором — {c2} %. '][st]
    q = (head + f'Получился новый слиток, в котором {c} % {metal[0]}. Первый слиток весил '
         f'{pl(m1, "килограмм", "килограмма", "килограммов")}. {what}{"." if ask == 0 else "?"}')
    y = sp.symbols('y', positive=True)

    def chk():
        m2s = sp.solve(sp.Eq(m1 * c1 + y * c2, (m1 + y) * c), y)[0]
        m2f = F(str(m2s))
        return [m1 + m2f, m2f, abs(m2f - m1)][ask] == ans
    return pcard(q, num(ans), e=f'{m1}·({c1} − {c}) = m₂·({c} − {c2}) ⇒ m₂ = {num(m2)} кг. Ответ: {num(ans)}.'), chk


VEH = [('автомобиль', 'автомобиля', 'ехал'), ('автобус', 'автобуса', 'ехал'), ('мотоциклист', 'мотоциклиста', 'ехал'),
       ('велосипедист', 'велосипедиста', 'ехал'), ('грузовик', 'грузовика', 'ехал'), ('поезд', 'поезда', 'шёл')]


@P('eb20-avg-dist', 'Средняя скорость: участки заданы длинами',
   'v_ср = (весь путь) / (всё время), время каждого участка s/v.',
   'Транспорт, число участков (2–3), длины и скорости.',
   'Σs / Σ(s/v)',
   r'Первые \d+ км',
   ['берут среднее арифметическое скоростей'],
   '«Первые … км автомобиль ехал со скоростью …, следующие … км — … Найдите среднюю скорость … Ответ дайте в км/ч.»')
def gen_eb20_avg_dist(r):
    k = r.choice([2, 3, 3])
    vs = r.sample([40, 45, 50, 54, 60, 63, 70, 72, 75, 80, 84, 90, 96, 100, 105, 108, 120], k)
    ts = [F(r.choice([1, 2, 3, 4, 5, 6, 8, 10, 12, 15]), r.choice([1, 2, 3, 4, 5, 6])) for _ in range(k)]
    ss = [v * t for v, t in zip(vs, ts)]
    if any(sv.denominator != 1 for sv in ss) or sum(ss) > 900:
        return None
    ans = sum(ss) / sum(ts)
    if not nice(ans, 1):
        return None
    v = r.choice([VEH[0], VEH[1], VEH[2], VEH[4]])
    parts = [f'{km(ss[0])} {v[0]} проехал со скоростью {kmh(vs[0])}', f'затем {km(ss[1])} — со скоростью {kmh(vs[1])}']
    if k == 3:
        parts.append(f'и последние {km(ss[2])} — со скоростью {kmh(vs[2])}')
    st = r.randrange(4)
    q = [f'Сначала {parts[0]}, {", ".join(parts[1:])}. Чему равна средняя скорость на всём пути? Ответ дайте в км/ч.',
         f'Маршрут {v[1]} состоял из {"двух" if k == 2 else "трёх"} участков: {"; ".join(parts)}. Найдите среднюю скорость {v[1]} на маршруте. Ответ дайте в км/ч.',
         f'По трассе {parts[0]}, {", ".join(parts[1:])}. Определите среднюю скорость движения за всю поездку. Ответ дайте в км/ч.',
         f'На пути из одного города в другой {parts[0]}, {", ".join(parts[1:])}. Какова средняя скорость {v[1]} на всём пути? Ответ дайте в км/ч.'][st]
    q = q.replace(' проехал ', ' проехал ' if v[0] != 'поезд' else ' прошёл ')

    def chk():
        tt = sum(F(sv) / vv for sv, vv in zip(ss, vs))
        return F(sum(ss)) / tt == ans
    return pcard(q, num(ans), e=f'Путь {sum(ss)} км, время {fx(sum(ts))} ч. Ответ: {num(ans)}.'), chk


@P('eb20-avg-time', 'Средняя скорость: участки заданы временем',
   'Путь на каждом участке v·t; v_ср = Σv·t / Σt.',
   'Транспорт, число участков, часы и скорости.',
   'Σvt / Σt',
   r'Первые (два|три|\w+) часа|Первый час',
   ['берут среднее арифметическое скоростей без учёта времени'],
   '«Первые два часа автомобиль ехал со скоростью …, следующие … Найдите среднюю скорость …»')
def gen_eb20_avg_time(r):
    k = r.choice([2, 3, 3])
    MODES = [('на поезде', 60, 120), ('на автобусе', 40, 90), ('на пароме', 20, 45), ('на машине', 50, 110), ('на катере', 25, 60),
             ('на электричке', 45, 90), ('на лошадях', 10, 20), ('на велосипеде', 12, 25), ('пешком', 4, 6)]
    modes = r.sample(MODES, k)
    vs = [r.randint(m[1], m[2]) for m in modes]
    ts = [r.choice([F(1, 2), F(1), F(1), F(3, 2), F(2), F(2), F(3), F(4)]) for _ in range(k)]
    ans = sum(v * t for v, t in zip(vs, ts)) / sum(ts)
    if not nice(ans, 1) or len({m[0] for m in modes}) < k:
        return None
    hw = lambda t: {F(1, 2): 'полчаса', F(1): 'час', F(3, 2): 'полтора часа', F(2): 'два часа', F(3): 'три часа', F(4): 'четыре часа'}[t]
    segs = [f'{hw(t)} {m[0]} со средней скоростью {kmh(v)}' for m, t, v in zip(modes, ts, vs)]
    w = Who(r)
    dest = r.choice(['до дачи друга', 'до базы отдыха', 'до горного посёлка', 'до родной деревни', 'до места раскопок'])
    st = r.randrange(3)
    if st == 0:
        q = (f'{w.n} {w.v("добирался")} {dest} так: {"; ".join(segs)}. Найдите среднюю скорость на всём пути. Ответ дайте в км/ч.')
    elif st == 1:
        q = (f'Путь {w.g} {dest} занял {pl(sum(ts), "час", "часа", "часов")}: {", затем ".join(segs)}. С какой средней скоростью '
             f'{w.v("двигался")} {w.n}? Ответ дайте в км/ч.')
    else:
        q = (f'Экспедиция добиралась {dest} в {"два" if k == 2 else "три"} этапа: сначала {", потом ".join(segs)}. Найдите среднюю скорость экспедиции за '
             f'всё время в пути. Ответ дайте в км/ч.')
    q = q.replace('добиралсяа', 'добиралась').replace('двигалсяа', 'двигалась')

    def chk():
        return F(sum(vv * tt for vv, tt in zip(vs, ts))) / sum(ts) == ans
    return pcard(q, num(ans), e=f'Путь {num(sum(v_ * t_ for v_, t_ in zip(vs, ts)))} км за {num(sum(ts))} ч. Ответ: {num(ans)}.'), chk


@P('eb20-avg-parts', 'Средняя скорость на равных частях пути (туда-обратно, трети, половины)',
   'Для равных частей: v_ср = n / Σ(1/vᵢ) — среднее гармоническое.',
   'Сюжет (яхта и самолёт, трети трассы, половины пути, туда и обратно), скорости.',
   'n / Σ(1/vᵢ)',
   r'(треть|трети) (пути|трассы)|переплыл море на яхте',
   ['берут среднее арифметическое скоростей'],
   '«Первую треть пути автомобиль ехал со скоростью …» / «Путешественник переплыл море на яхте …»')
def gen_eb20_avg_parts(r):
    st = r.randrange(5)
    if st in (0, 1):
        a = r.randint(8, 25)
        b = a * r.randint(10, 30)
        vs = [a, b]
    elif st == 2:
        vs = r.sample(range(20, 150, 5), 3)
    else:
        vs = r.sample(range(30, 130, 5), 2)
    ans = F(len(vs)) / sum(F(1, v) for v in vs)
    if not nice(ans, 1):
        return None
    if st == 0:
        q = (f'Турист доплыл до острова на катамаране со средней скоростью {kmh(vs[0])}, а назад вернулся на вертолёте, летевшем со '
             f'скоростью {kmh(vs[1])}. Найдите среднюю скорость туриста на всём пути туда и обратно. Ответ дайте в км/ч.')
    elif st == 1:
        q = (f'Исследователь добрался до зимовки на собачьей упряжке, двигаясь в среднем со скоростью {kmh(vs[0])}, а обратно тот же путь '
             f'пролетел на самолёте со скоростью {kmh(vs[1])}. Чему равна средняя скорость исследователя за всю поездку? Ответ '
             f'дайте в км/ч.')
    elif st == 2:
        q = (f'Маршрут разделён на три равных по длине участка. Первый участок {r.choice(["автобус", "грузовик", "автомобиль"])} '
             f'проехал со скоростью {kmh(vs[0])}, второй — со скоростью {kmh(vs[1])}, третий — со скоростью {kmh(vs[2])}. '
             f'Найдите среднюю скорость на всём маршруте. Ответ дайте в км/ч.')
    elif st == 3:
        q = (f'Половину пути мотоциклист ехал со скоростью {kmh(vs[0])}, а вторую половину — со скоростью {kmh(vs[1])}. '
             f'Какова средняя скорость мотоциклиста на всём пути? Ответ дайте в км/ч.')
    else:
        q = (f'Из посёлка на станцию автобус шёл со скоростью {kmh(vs[0])}, а обратно по той же дороге — со скоростью '
             f'{kmh(vs[1])}. Найдите среднюю скорость автобуса за рейс туда и обратно. Ответ дайте в км/ч.')

    def chk():
        L = 1
        for v in vs:
            L = L * v // math.gcd(L, v)
        dist = L * len(vs)
        return F(dist, sum(L // v for v in vs)) == ans
    return pcard(q, num(ans), e=f'Для равных частей пути: v = {len(vs)} / ({" + ".join(f"1/{v}" for v in vs)}) = {num(ans)}.'), chk


@P('eb20-meet', 'Встречное движение: найти скорость, расстояние или время',
   'Скорость сближения v₁ + v₂; путь каждого до встречи — скорость × время (с учётом задержки старта одного из них).',
   'Сюжет, одновременный старт или задержка, что известно (место встречи, скорость), что спрашивают.',
   's = (v₁ + v₂)·t; с задержкой: (S − v₁t₀) / (v₁ + v₂)',
   r'навстречу (друг другу|ему)',
   ['не учитывают задержку старта', 'путают, от какого города считают расстояние'],
   '«Расстояние между городами A и B равно … Из города A … а через час после этого навстречу ему … На каком расстоянии от города A …»')
def gen_eb20_meet(r):
    st = r.randrange(5)
    v1, v2 = r.sample(range(40, 100, 5), 2)
    if st == 0:  # одновременно, место встречи от B, найти скорость из A
        t = r.randint(2, 6)
        S = (v1 + v2) * t
        ans = v1
        q = (f'Два автобуса одновременно выехали навстречу друг другу из городов К и Л, между которыми {km(S)}. Через '
             f'{hrs(t)} они встретились, причём до встречи автобус из Л проехал {km(v2 * t)}. С какой скоростью ехал автобус из К? '
             f'Ответ дайте в км/ч.')
        chk_ = lambda: F(S - v2 * t, t) == ans
    elif st == 1:  # задержка, найти расстояние от A
        t0 = r.randint(1, 3)
        t = r.randint(2, 5)
        S = v1 * (t0 + t) + v2 * t
        ans = v1 * (t0 + t)
        q = (f'Между сёлами Ольховка и Берёзовка {km(S)}. Из Ольховки в Берёзовку выехал фургон со скоростью {kmh(v1)}, а через '
             f'{hrs(t0)} ему навстречу из Берёзовки выехал грузовик со скоростью {kmh(v2)}. На каком расстоянии от Ольховки они '
             f'встретились? Ответ дайте в километрах.')
        chk_ = lambda: v1 * (t0 + F(S - v1 * t0, v1 + v2)) == ans
    elif st == 2:  # задержка, встреча посередине, найти скорость первого
        t0 = r.randint(1, 3)
        t = r.randint(2, 5)
        half = v2 * t
        if half % (t0 + t):
            return None
        S = 2 * half
        ans = F(half, t0 + t)
        q = (f'Расстояние между пристанями Верхняя и Нижняя по шоссе {km(S)}. Из Верхней в Нижнюю выехал мотоциклист, а через '
             f'{hrs(t0)} навстречу ему из Нижней выехал автомобиль со скоростью {kmh(v2)}. Они встретились ровно на половине пути. '
             f'Найдите скорость мотоциклиста. Ответ дайте в км/ч.')
        x = sp.symbols('x', positive=True)
        chk_ = lambda: F(str(sp.solve(sp.Eq(x * (t0 + sp.Integer(half) / v2), S / 2), x)[0])) == ans
    elif st == 3:  # пешеход и велосипедист, разница скоростей
        w = r.randint(3, 6)
        dv = r.randint(5, 14)
        t = r.choice([F(1), F(3, 2), F(2), F(5, 2), F(3)])
        S = (2 * w + dv) * t
        if S.denominator != 1:
            return None
        ans = w
        q = (f'Из двух деревень, расстояние между которыми {km(S)}, одновременно навстречу друг другу вышел турист и выехал '
             f'велосипедист. Встреча произошла через {pl(t, "час", "часа", "часов")}. Велосипедист ехал на {kmh(dv)} быстрее, чем шёл турист. '
             f'С какой скоростью шёл турист? Ответ дайте в км/ч.')
        chk_ = lambda: (S / t - dv) / 2 == ans
    else:  # велосипедисты проехали равные расстояния, найти задержку в минутах
        a, b = r.sample(range(10, 25), 2)
        if a >= b:
            a, b = b, a
        half = F(r.randint(10, 40), 10)
        ans = (half / a - half / b) * 60
        if ans.denominator != 1 or ans < 2:
            return None
        S = 2 * half
        q = (f'Два велосипедиста выехали навстречу друг другу из посёлков, расстояние между которыми {km(S)}. Первый ехал со скоростью '
             f'{kmh(a)}, а второй, стартовавший позже первого, — со скоростью {kmh(b)}. Когда они встретились, выяснилось, что '
             f'каждый проехал одно и то же расстояние. На сколько минут позже первого выехал второй?')
        chk_ = lambda: (F(S, 2) / a - F(S, 2) / b) * 60 == ans
    return pcard(q, num(ans), e=f'Скорость сближения — сумма скоростей. Ответ: {num(ans)}.'), chk_


@P('eb20-work', 'Совместная работа: время работы вместе',
   'Производительности складываются: 1/t = 1/t₁ + 1/t₂ (+ 1/t₃); «в k раз быстрее» — производительность k/t.',
   'Сюжет (мастера, насосы, принтеры, бригады, помощники), число участников, времена или множители.',
   '1 / Σ(1/tᵢ)',
   r'работая (вместе|одновременно)|наполнят бак|к нему на помощь',
   ['складывают времена', 'берут среднее время'],
   '«Один мастер может выполнить заказ за … часов, а другой — за … За сколько часов выполнят этот заказ оба мастера?»')
def gen_eb20_work(r):
    st = r.randrange(5)
    if st in (0, 1):
        t1, t2 = r.sample([4, 6, 8, 9, 10, 12, 14, 15, 18, 20, 21, 24, 28, 30, 36, 40, 45, 60], 2)
        ts = [t1, t2]
        ans = 1 / (F(1, t1) + F(1, t2))
        q = [f'Одна наборщица печатает рукопись за {hrs(t1)}, другая — ту же рукопись за {hrs(t2)}. За сколько часов они '
             f'напечатают рукопись, если разделят работу и будут печатать одновременно?',
             f'Первый станок изготавливает партию втулок за {hrs(t1)}, второй — такую же партию за {hrs(t2)}. За сколько часов '
             f'будет изготовлена партия, если оба станка будут работать одновременно?'][st]
    elif st == 2:
        ts = r.sample([6, 8, 9, 10, 12, 15, 18, 20, 24, 30, 36, 40, 45, 60, 72], 3)
        ans = 1 / sum(F(1, t) for t in ts)
        q = (f'Первая помпа откачивает воду из котлована за {mins_(ts[0])}, вторая — за {mins_(ts[1])}, третья — за '
             f'{mins_(ts[2])}. За сколько минут котлован осушат все три помпы, если их включить одновременно?')
    elif st == 3:
        t = r.choice([6, 8, 9, 10, 12, 14, 15, 16, 18, 20])
        k1, k2 = r.sample([F(3, 2), F(5, 4), F(2), F(1, 2), F(5, 2), F(3)], 2)
        ans = F(t) / (1 + k1 + k2)
        fk = lambda k: f'в {dec(k)} раза быстрее' if k > 1 else f'в {dec(1 / k)} раза медленнее'
        q = (f'Садовник Игорь мог бы подстричь все кусты в парке за {hrs(t)}. Ему дали двух помощников: первый работает '
             f'{fk(k1)}, чем Игорь, второй — {fk(k2)}. За сколько часов они подстригут кусты втроём?')
        ts = None
    else:
        t1, t = r.sample([10, 12, 15, 18, 20, 24, 30, 36, 40, 45, 60], 2)
        if t >= t1:
            return None
        ans = 1 / (F(1, t) - F(1, t1))
        ts = [t1]
        q = (f'Первая бригада может заасфальтировать участок дороги за {hrs(t1)}, а вместе со второй бригадой — за {hrs(t)}. '
             f'За сколько часов заасфальтирует этот участок одна вторая бригада?')
    if not nice(ans, 2) or ans <= 0:
        return None
    x = sp.symbols('x', positive=True)

    def chk():
        if st in (0, 1, 2):
            sol = sp.solve(sp.Eq(sum(x / sp.Integer(t_) for t_ in ts), 1), x)[0]
        elif st == 3:
            sol = sp.solve(sp.Eq(x / t * (1 + sp.Rational(k1) + sp.Rational(k2)), 1), x)[0]
        else:
            sol = sp.solve(sp.Eq(sp.Integer(1) / t1 + 1 / x, sp.Integer(1) / t), x)[0]
        return F(str(sol)) == ans
    return pcard(q, num(ans), e=f'Складываем производительности (доли работы за единицу времени). Ответ: {num(ans)}.'), chk


@P('eb20-river', 'Движение по реке с остановкой',
   'По течению v + u, против v − u; время в пути = T − стоянка; S/(v+u) + S/(v−u) = T − t.',
   'Судно, скорости, стоянка, общее время; что спрашивают (весь путь, путь в один конец).',
   '2S или S из S/(v+u) + S/(v−u) = T − t',
   r'проходит по течению реки',
   ['забывают вычесть стоянку', 'отвечают расстоянием в один конец вместо всего рейса'],
   '«Теплоход … проходит по течению реки и после стоянки возвращается … Сколько километров прошёл теплоход за весь рейс?»')
def gen_eb20_river(r):
    u = r.randint(1, 5)
    v = r.randint(u + 8, 35)
    a, b = v + u, v - u
    # S кратно НОК(a, b), чтобы время было целым/красивым
    L = a * b // math.gcd(a, b)
    S = L * r.randint(1, 4)
    if S > 600:
        return None
    t = r.randint(1, 8)
    Ttot = F(S, a) + F(S, b) + t
    if Ttot.denominator != 1:
        return None
    full = r.random() < 0.6
    ans = 2 * S if full else S
    # сутки и больше в пути — это теплоход или буксир, а не моторная лодка
    boat = r.choice(['Теплоход', 'Прогулочный теплоход', 'Буксир'] if Ttot > 10 else ['Катер', 'Моторная лодка', 'Прогулочный теплоход'])
    stop, stop_n = r.choice([('стоянки', 'Стоянка'), ('разгрузки', 'Разгрузка'), ('остановки', 'Остановка')])
    q = (f'{boat} идёт вниз по реке от пристани до посёлка и после {stop} возвращается обратно. Собственная скорость судна '
         f'{kmh(v)}, скорость течения {kmh(u)}. {stop_n} длилась {hrs(t)}, а вернулось судно через '
         f'{hrs(Ttot)} после отправления. {"Сколько километров прошло судно за весь рейс?" if full else "Найдите расстояние от пристани до посёлка. Ответ дайте в километрах."}')
    q = q.replace('длилась', 'длилась' if stop != 'разгрузки' else 'длилась')
    y = sp.symbols('y', positive=True)

    def chk():
        sol = sp.solve(sp.Eq(y / a + y / b + t, Ttot), y)[0]
        return F(str(sol)) * (2 if full else 1) == ans
    return pcard(q, num(ans), e=f'S/{a} + S/{b} = {Ttot} − {t} ⇒ S = {S}. Ответ: {ans}.'), chk


@P('eb20-rates-gap', 'Одинаковый объём работы с разной скоростью: разница во времени',
   'N/a − N/b = Δt (в часах) ⇒ N = Δt·ab/(b − a).',
   'Сюжет (тест, листовки, пазлы, диктант, страницы), скорости, разница в минутах.',
   'N = Δt·ab/(b − a)',
   r'выполняют одинаковый тест',
   ['не переводят минуты в часы'],
   '«Петя и Ваня выполняют одинаковый тест … Сколько вопросов содержит тест?»')
def gen_eb20_rates_gap(r):
    a, b = sorted(r.sample(range(6, 40), 2))
    dt = r.choice([10, 12, 15, 20, 24, 30, 36, 40, 45, 48, 50, 60, 72, 75, 80, 90, 100, 120])
    N = F(dt, 60) * a * b / (b - a)
    if N.denominator != 1 or N > 500:
        return None
    ans = int(N)
    w1, w2 = Who(r), Who(r)
    if w1.n == w2.n or 2 * b > 3 * a:        # как в банке (20 и 21, 13 и 15, 15 и 24): скорости одного порядка
        return None
    st = r.randrange(4)
    if st == 0 and b > 15:                   # задач за час — не больше полутора десятков
        return None
    if st == 0:
        q = (f'{w1.n} и {w2.n} решают один и тот же вариант контрольной. {w1.n} за час решает {pl(a, "задачу", "задачи", "задач")}, а '
             f'{w2.n} — {pl(b, "задачу", "задачи", "задач")}. Начав одновременно, {w1.n} {w1.v("закончил")} позже на {mins_(dt)}. Сколько '
             f'задач в варианте?')
    elif st == 1:
        q = (f'Два волонтёра раскладывают по почтовым ящикам одинаковые пачки листовок. Первый раскладывает {a} листовок в час, второй — '
             f'{b}. Они начали одновременно, и второй освободился на {mins_(dt)} раньше первого. Сколько листовок было в каждой пачке?')
    elif st == 2:
        q = (f'{w1.n} и {w2.n} набирают на компьютере одинаковые тексты. {w1.n} набирает {pl(a, "строку", "строки", "строк")} в час, '
             f'{w2.n} — {pl(b, "строку", "строки", "строк")} в час. Работу начали одновременно, и {w2.n} {w2.v("закончил")} на '
             f'{mins_(dt)} раньше. Сколько строк в тексте?')
    else:
        q = (f'Два робота-упаковщика упаковывают одинаковые партии коробок. Первый упаковывает {a} коробок в час, второй — {b}. '
             f'Включили их одновременно, и первый закончил на {mins_(dt)} позже второго. Сколько коробок в партии?')
    q = q.replace(f'{a} листовок', pl(a, 'листовку', 'листовки', 'листовок')).replace(f'{a} коробок', pl(a, 'коробку', 'коробки', 'коробок'))
    y = sp.symbols('y', positive=True)

    def chk():
        sol = sp.solve(sp.Eq(y / a - y / b, sp.Rational(dt, 60)), y)[0]
        return sol == ans
    return pcard(q, num(ans), e=f'N/{a} − N/{b} = {dt}/60 ⇒ N = {ans}.'), chk


@P('eb20-up-down', 'Подъём и спуск: скорость на одном из участков',
   'Время на подъём и спуск известно, скорость на спуске на Δ больше: v·t_с + (v − Δ)·t_п = S.',
   'Сюжет (турист, велосипедист, лыжник), длина, времена, разница скоростей, что найти.',
   'v = (S + Δ·t_п)/(t_с + t_п)',
   r'состоит из подъёма и спуска',
   ['путают время подъёма и спуска', 'находят не ту скорость'],
   '«Дорога между пунктами А и В состоит из подъёма и спуска … Найдите скорость туриста на спуске …»')
def gen_eb20_up_down(r):
    who = r.choice([('турист', 'туриста', 'прошёл', 2, 5, 1, 3), ('велосипедист', 'велосипедиста', 'проехал', 8, 15, 3, 8),
                    ('лыжник', 'лыжника', 'прошёл', 5, 10, 2, 6), ('всадник', 'всадника', 'проехал', 6, 12, 2, 6)])
    vu = r.randint(who[3], who[4])
    dv = r.randint(who[5], who[6])
    tu, td = r.randint(1, 8), r.randint(1, 6)
    S = vu * tu + (vu + dv) * td
    ask_down = r.random() < 0.5
    ans = vu + dv if ask_down else vu
    road = r.choice(['Тропа от приюта через перевал до озера', 'Тропа от лагеря через перевал до турбазы']) if who[0] != 'велосипедист' \
        else 'Дорога от посёлка через перевал до станции'
    q = (f'{road} имеет длину {km(S)}: сначала {"она" if road.startswith("Тропа") else "дорога"} идёт в гору, а затем под гору. '
         f'{who[0].capitalize()} {who[2]} её за '
         f'{hrs(tu + td)}, из которых {hrs(td)} пришлось на спуск. На спуске {who[0]} двигался на {kmh(dv)} быстрее, чем на подъёме. '
         f'Найдите скорость {who[1]} {"на спуске" if ask_down else "на подъёме"}. Ответ дайте в км/ч.')
    y = sp.symbols('y', positive=True)

    def chk():
        sol = sp.solve(sp.Eq(y * tu + (y + dv) * td, S), y)[0]
        return (sol + dv if ask_down else sol) == ans
    return pcard(q, num(ans), e=f'v·{tu} + (v + {dv})·{td} = {S}. Ответ: {ans}.'), chk


@P('eb20-norm', 'Выполнение плана с отклонением от нормы',
   'План: N·p; факт: M·(p ∓ δ) — тот же объём; p = Mδ/(M − N).',
   'Сюжет (плитка, покраска, вязание, посадка), плановые и фактические дни, отклонение.',
   'объём = N·Mδ/(M − N)',
   r'отклонялся от нормы',
   ['путают, в какую сторону отклонение'],
   '«Рабочий получил задание за 8 полных дней … отклонялся от нормы на 2 м² …»')
def gen_eb20_norm(r):
    N, M = r.randint(4, 15), r.randint(4, 18)
    if N == M:
        return None
    d = r.randint(1, 8)
    # N·p = M·(p − d) при M > N (отставал), N·p = M·(p + d) при M < N (перевыполнял)
    p_ = F(M * d, M - N) if M > N else F(M * d, N - M)
    # как в банке (10 → 14, 8 → 10 дней): срок меняется на несколько дней, дневная норма заметно больше отклонения
    if p_.denominator != 1 or abs(M - N) > 4 or p_ < 3 * d:
        return None
    V = N * p_
    if V > 2000:
        return None
    ans = V
    late = M > N
    st = r.randrange(4)
    dd = [f'{d} м²', pl(d, 'деталь', 'детали', 'деталей'), pl(d, 'саженец', 'саженца', 'саженцев'), f'{d} м²'][st]
    what = ['уложить плитку на площадке', 'изготовить партию деталей', 'высадить саженцы на участке', 'покрасить фасад'][st]
    ask = ['Найдите площадь площадки. Ответ дайте в квадратных метрах.', 'Сколько деталей в партии?',
           'Сколько саженцев нужно было высадить?', 'Найдите площадь фасада. Ответ дайте в квадратных метрах.'][st]
    q = (f'Бригаде поручили за {pl(N, "полный день", "полных дня", "полных дней")} {what}. Однако ежедневно она '
         f'{"не добирала" if late else "перевыполняла"} норму на {dd} и поэтому справилась за '
         f'{pl(M, "полный день", "полных дня", "полных дней")}. {ask}')
    y = sp.symbols('y', positive=True)

    def chk():
        sol = sp.solve(sp.Eq(N * y, M * (y - d if late else y + d)), y)[0]
        return N * sol == ans
    return pcard(q, num(ans), e=f'Норма p: {N}p = {M}(p {"−" if late else "+"} {d}) ⇒ p = {p_}. Ответ: {ans}.'), chk


@P('eb20-progression', 'Оплата по нарастающей: сумма арифметической прогрессии',
   'Каждая следующая единица дороже на d: S = n·(2a + (n − 1)d)/2.',
   'Сюжет (колодец, занятия, забор, этажи), первая цена, прибавка, количество.',
   'S = n(2a + (n − 1)d)/2',
   r'за каждый следующий метр',
   ['считают n − 1 прибавок неверно', 'умножают первую цену на n'],
   '«Хозяин договорился с рабочими, что они выкопают ему колодец … Сколько рублей хозяин должен будет заплатить …»')
def gen_eb20_progression(r):
    a = r.randrange(1500, 6000, 100)
    d = r.randrange(200, 2000, 100)
    n = r.randint(5, 14)
    ans = n * (2 * a + (n - 1) * d) // 2
    st = r.randrange(4)
    q = [f'Бригада бурит скважину. За первый метр заказчик платит {rub(a)}, а каждый следующий метр обходится на {rub(d)} дороже '
         f'предыдущего. Сколько рублей заплатит заказчик за скважину глубиной {pl(n, "метр", "метра", "метров")}?',
         f'Репетитор договорился с учеником: первое занятие стоит {rub(a)}, а каждое следующее — на {rub(d)} дороже предыдущего. '
         f'Сколько рублей ученик заплатит за {pl(n, "занятие", "занятия", "занятий")}?',
         f'За установку первой секции забора мастер берёт {rub(a)}, а за каждую следующую — на {rub(d)} больше, чем за предыдущую. '
         f'Сколько рублей будет стоить установка {pl(n, "секции", "секций", "секций")}?',
         f'Промышленные альпинисты моют окна высотного здания: за первый этаж им платят {rub(a)}, а за каждый следующий — на '
         f'{rub(d)} больше, чем за предыдущий. Сколько рублей они получат за {pl(n, "этаж", "этажа", "этажей")}?'][st]

    def chk():
        tot, cur = 0, a
        for _ in range(n):
            tot += cur
            cur += d
        return tot == ans
    return pcard(q, num(ans), e=f'S = {n}·(2·{a} + {n - 1}·{d})/2 = {ans}.'), chk


NUMW = {3: ('трёх', 'четвёртого', 'четвёртое'), 4: ('четырёх', 'пятого', 'пятое'), 5: ('пяти', 'шестого', 'шестое'),
        6: ('шести', 'седьмого', 'седьмое'), 7: ('семи', 'восьмого', 'восьмое'), 8: ('восьми', 'девятого', 'девятое'),
        9: ('девяти', 'десятого', 'десятое'), 10: ('десяти', 'одиннадцатого', 'одиннадцатое')}


@P('eb20-mean-add', 'Среднее арифметическое до и после добавления числа',
   'Сумма = среднее × количество; новое число = (n + 1)·m₂ − n·m₁.',
   'Количество, средние, сюжет (числа, оценки, рост, возраст).',
   '(n + 1)m₂ − n·m₁',
   r'Среднее арифметическое \w+ различных натуральных чисел',
   ['делят разность средних', 'забывают умножить на количество'],
   '«Среднее арифметическое девяти различных натуральных чисел равно … Чему равно десятое число?»')
def gen_eb20_mean_add(r):
    n = r.randint(3, 10)
    m1 = r.randint(8, 40)
    dm = r.choice([1, 2, 3, -1, -2])
    m2 = m1 + dm
    ans = (n + 1) * m2 - n * m1
    if ans <= 0:
        return None
    st = r.randrange(4)
    w = NUMW[n]
    if st == 0:
        q = (f'У {w[0]} различных натуральных чисел среднее арифметическое равно {m1}. К ним добавили ещё одно число, и среднее '
             f'арифметическое всех чисел стало равно {m2}. Какое число добавили?')
    elif st == 1:
        q = (f'Средний возраст игроков команды из {w[0]} человек — {pl(m1, "год", "года", "лет")}. После прихода нового игрока средний '
             f'возраст стал {pl(m2, "год", "года", "лет")}. Сколько лет новому игроку?')
    elif st == 2:
        if not 2 <= ans <= 20 or m1 > 10:       # ошибок в диктанте — единицы, а не десятки
            return None
        q = (f'За {pl(n, "диктант", "диктанта", "диктантов")} у ученика в среднем было по {pl(m1, "ошибке", "ошибки", "ошибок")}. После {w[1]} диктанта среднее '
             f'число ошибок стало равно {m2}. Сколько ошибок ученик сделал в {w[2].replace("ое", "ом")} диктанте?')
    else:
        q = (f'Средняя масса {w[0]} арбузов на прилавке — {pl(m1, "килограмм", "килограмма", "килограммов")}. Продавец положил ещё '
             f'один арбуз, и средняя масса стала {pl(m2, "килограмм", "килограмма", "килограммов")}. Сколько килограммов весит '
             f'добавленный арбуз?')
        if ans > 25 or m1 > 15:
            return None
    if st == 1 and not (14 <= ans <= 45 and 12 <= m1 <= 35):
        return None

    def chk():
        return F(n * m1 + ans, n + 1) == m2
    return pcard(q, num(ans), e=f'{n + 1}·{m2} − {n}·{m1} = {ans}.'), chk


@P('eb20-fixed-part', 'Цена = постоянная часть + часть, пропорциональная количеству',
   'Из двух известных случаев находим цену единицы и постоянную часть (цена тары, вызова, посадки), затем третий случай.',
   'Сюжет (квас в бутылке, такси, доставка, мёд в банке), объёмы, цены.',
   'линейная интерполяция: c(x) = b + kx',
   r'квас на (раз|роз)лив',
   ['не учитывают цену бутылки', 'считают цену пропорциональной объёму'],
   '«В магазине квас на разлив можно купить в бутылках … Сколько рублей будет стоить бутылка кваса объёмом 1,5 литра?»')
def gen_eb20_fixed_part(r):
    st = r.randrange(4)
    b = r.randint(5, 60)
    k = r.randint(15, 90)
    x1, x2, x3 = [F(v, 2) for v in r.sample(range(1, 11), 3)]
    c1, c2, c3 = b + k * x1, b + k * x2, b + k * x3
    if any(c.denominator != 1 for c in (c1, c2, c3)):
        return None
    ans = c3
    if st == 0:
        q = (f'Морс в киоске продают в пластиковых бутылках; цена бутылки не зависит от её объёма и входит в стоимость покупки. '
             f'Бутылка морса объёмом {dec(x1)} л стоит {rub(c1)}, объёмом {dec(x2)} л — {rub(c2)}. Сколько рублей стоит бутылка '
             f'морса объёмом {dec(x3)} л?')
    elif st == 1:
        b, k = r.randint(50, 200), r.randint(15, 40)
        x1, x2, x3 = r.sample(range(2, 30), 3)
        c1, c2, ans = b + k * x1, b + k * x2, b + k * x3
        q = (f'Стоимость поездки на такси складывается из платы за посадку и платы за каждый километр. Поездка на {km(x1)} стоила '
             f'{rub(c1)}, а на {km(x2)} — {rub(c2)}. Сколько рублей будет стоить поездка на {km(x3)}?')
    elif st == 2:
        if not (5 <= b <= 15 and k >= 60):     # банка 50–150 рублей, мёд 600–900 рублей за килограмм
            return None
        q = (f'Мёд на ярмарке продают в стеклянных банках, стоимость банки одинакова для всех размеров и включена в цену. Банка с '
             f'{dec(x1)} кг мёда стоит {rub(c1 * 10)}, с {dec(x2)} кг — {rub(c2 * 10)}. Сколько рублей стоит банка с {dec(x3)} кг мёда?')
        ans = c3 * 10
    else:
        b, k = r.randint(100, 400), r.randint(20, 90)
        x1, x2, x3 = r.sample(range(2, 25), 3)
        c1, c2, ans = b + k * x1, b + k * x2, b + k * x3
        q = (f'Служба доставки берёт фиксированную плату за заказ и дополнительно доплату за каждый килограмм груза. Доставка '
             f'посылки массой {pl(x1, "килограмм", "килограмма", "килограммов")} стоила {rub(c1)}, массой '
             f'{pl(x2, "килограмм", "килограмма", "килограммов")} — {rub(c2)}. Сколько рублей стоит доставка посылки массой '
             f'{pl(x3, "килограмм", "килограмма", "килограммов")}?')
    mult = 10 if st == 2 else 1
    X = [x1, x2, x3]
    C = [c1 * mult, c2 * mult]
    bb, kk = sp.symbols('bb kk')

    def chk():
        sol = sp.solve([sp.Eq(bb + kk * sp.Rational(X[0]), C[0]), sp.Eq(bb + kk * sp.Rational(X[1]), C[1])], [bb, kk])
        return sol[bb] + sol[kk] * sp.Rational(X[2]) == ans
    return pcard(q, num(ans), e=f'Цена единицы = разность цен : разность количеств; затем постоянная часть. Ответ: {ans}.'), chk


@P('eb20-ratio-mass', 'Смесь в заданном отношении: масса по известной части',
   'Части a : b : c; одна часть = известная масса / её доля; вся масса = (a + b + c)·одна часть.',
   'Сюжет (чай, бетон, салат, краска, удобрение), отношение, известная компонента, что спросить.',
   '(a + b + c)·m / (доля известной)',
   r'в отношении \d+ ?: ?\d+ ?: ?\d+',
   ['делят на сумму частей вместо умножения'],
   '«Чайная композиция … получается смешиванием этих листьев по массе в отношении 9 : 2 : 1 …»')
def gen_eb20_ratio_mass(r):
    parts = r.sample(range(1, 10), 3)
    st = r.randrange(4)
    names = [('цемента', 'песка', 'щебня', 'бетонной смеси', 'килограммах', 'килограммов', ('цемент', 'песок', 'щебень')),
             ('ржаной муки', 'пшеничной муки', 'отрубей', 'мучной смеси', 'граммах', 'граммов', ('ржаную муку', 'пшеничную муку', 'отруби')),
             ('синей краски', 'белой краски', 'жёлтой краски', 'краски нужного оттенка', 'граммах', 'граммов',
              ('синюю краску', 'белую краску', 'жёлтую краску')),
             ('торфа', 'песка', 'перегноя', 'грунта для рассады', 'килограммах', 'килограммов', ('торф', 'песок', 'перегной'))][st]
    known = r.randrange(3)
    unit = r.randint(2, 30) * (1 if names[4] == 'килограммах' else 10)
    m_known = parts[known] * unit
    ask = r.choice([i for i in range(4) if i != known])
    ans = sum(parts) * unit if ask == 3 else parts[ask] * unit
    uw = ('килограмм', 'килограмма', 'килограммов') if names[4] == 'килограммах' else ('грамм', 'грамма', 'граммов')
    acc = names[6]
    q = (f'Для приготовления {names[3]} смешивают {acc[0]}, {acc[1]} и {acc[2]} в отношении '
         f'{parts[0]} : {parts[1]} : {parts[2]} по массе. Взяли {pl(m_known, *uw)} {names[known]}. '
         + (f'Найдите массу всей смеси. Ответ дайте в {names[4]}.' if ask == 3 else f'Сколько {names[5]} {names[ask]} нужно взять?'))

    def chk():
        tot = F(m_known) * sum(parts) / parts[known]
        return (tot if ask == 3 else tot * parts[ask] / sum(parts)) == ans
    return pcard(q, num(ans), e=f'Одна часть — {pl(unit, *uw)}. Ответ: {ans}.'), chk



# ================================================================ 21. Задачи на смекалку

def a_card(q, ans, e):
    return pcard(q, num(ans), e=e)


@P('eb21-quiz', 'Очки за верные и неверные ответы: сколько верных',
   'x верных, y неверных: a·x − b·y = S, x + y ≤ N, y ≥ 1; перебором находим единственное решение.',
   'Сюжет (викторина, тест со штрафом, стрельба, игра), число вопросов, очки, итог.',
   'x из a·x − b·y = S',
   r'За каждый правильный ответ',
   ['не учитывают условие «хотя бы раз ошибся»', 'не проверяют x + y ≤ N'],
   '«Список заданий викторины состоял из … вопросов … Сколько верных ответов дал участник …?»')
def gen_eb21_quiz(r):
    N = r.randint(20, 60)
    a, b = r.randint(3, 12), r.randint(4, 17)
    x = r.randint(N // 3, N - 1)
    y = r.randint(1, N - x)
    S = a * x - b * y
    if S <= 0:
        return None
    sols = [(xx, yy) for xx in range(N + 1) for yy in range(1, N - xx + 1) if a * xx - b * yy == S]
    if len({xx for xx, _ in sols}) != 1:
        return None
    ans = sols[0][0]
    st = r.randrange(4)
    pts = lambda n: pl(n, 'очко', 'очка', 'очков')
    if st == 0:
        q = (f'В интеллектуальной игре {pl(N, "вопрос", "вопроса", "вопросов")}. За верный ответ команде начисляют {pts(a)}, за '
             f'неверный снимают {pts(b)}, за пропущенный вопрос очки не меняются. Команда набрала {pts(S)} и хотя бы один раз '
             f'ответила неверно. Сколько верных ответов дала команда?')
    elif st == 1:
        q = (f'Тест содержит {pl(N, "задание", "задания", "заданий")}. Верно выполненное задание приносит {pl(a, "балл", "балла", "баллов")}, '
             f'за ошибку вычитается {pl(b, "балл", "балла", "баллов")}, а за пропущенное задание баллы не начисляются и не вычитаются. '
             f'Ученик получил {pl(S, "балл", "балла", "баллов")}, причём ошибся по крайней мере в одном задании. Сколько заданий он '
             f'выполнил верно?')
    elif st == 2:
        q = (f'На соревнованиях по стрельбе у каждого участника {pl(N, "мишень", "мишени", "мишеней")}. Попадание приносит {pts(a)}, '
             f'промах отнимает {pts(b)}, а если стрелок пропускает мишень, счёт не меняется. Спортсмен набрал {pts(S)}, и у него '
             f'был хотя бы один промах. Сколько у него было попаданий?')
    else:
        q = (f'В онлайн-олимпиаде {pl(N, "задача", "задачи", "задач")}. За каждую решённую задачу дают {pts(a)}, за каждую '
             f'неверно решённую отнимают {pts(b)}, нерешённые задачи на счёт не влияют. Участница набрала {pts(S)}, и как минимум '
             f'одна её задача оказалась решена неверно. Сколько задач она решила верно?')

    def chk():
        xs = {xx for xx in range(N + 1) for yy in range(1, N + 1 - xx) if a * xx - b * yy == S}
        return xs == {ans}
    return a_card(q, ans, f'{a}x − {b}y = {S}, x + y ≤ {N}, y ≥ 1 ⇒ x = {ans}.'), chk


def split_svg(vals, labels):
    """Прямоугольник, разрезанный на четыре части; в частях — подписи (порядок: ЛВ, ПВ, ПН, ЛН)."""
    w, h = 260, 170
    cx, cy = 100, 70
    body = (f'<rect x="10" y="10" width="{w}" height="{h}" fill="none" stroke="{INK}" stroke-width="2"/>'
            f'<line x1="{10 + cx}" y1="10" x2="{10 + cx}" y2="{10 + h}" stroke="{INK}" stroke-width="1.5"/>'
            f'<line x1="10" y1="{10 + cy}" x2="{10 + w}" y2="{10 + cy}" stroke="{INK}" stroke-width="1.5"/>')
    pos = [(10 + cx / 2, 10 + cy / 2), (10 + cx + (w - cx) / 2, 10 + cy / 2), (10 + cx + (w - cx) / 2, 10 + cy + (h - cy) / 2),
           (10 + cx / 2, 10 + cy + (h - cy) / 2)]
    for (x, y), t in zip(pos, labels):
        body += f'<text x="{x}" y="{y + 6}" font-size="17" text-anchor="middle" fill="{INK}">{t}</text>'
    return _svg(w + 20, h + 20, body)


@P('eb21-rect-split', 'Прямоугольник, разрезанный на четыре: периметр или площадь четвёртого',
   'Периметры: P₁ + P₃ = P₂ + P₄ (противоположные части); площади: S₁·S₃ = S₂·S₄.',
   'Периметры или площади, сюжет (лист, участок, поле, стекло), какая часть неизвестна.',
   'P₄ = P₁ + P₃ − P₂ или S₄ = S₁S₃/S₂',
   r'разбит на четыре (меньших|маленьких) прямоугольника',
   ['складывают все три числа', 'путают противоположные части'],
   '«Прямоугольник разбит на четыре меньших прямоугольника двумя прямолинейными разрезами. Периметры трёх из них … Найдите периметр четвёртого».')
def gen_eb21_rect_split(r):
    area = r.random() < 0.5
    a1, a2 = r.randint(1, 12), r.randint(1, 12)
    b1, b2 = r.randint(1, 12), r.randint(1, 12)
    # ЛВ: a1×b1, ПВ: a2×b1, ПН: a2×b2, ЛН: a1×b2 (a — ширины столбцов, b — высоты строк)
    f = (lambda a, b: a * b) if area else (lambda a, b: 2 * (a + b))
    vals = [f(a1, b1), f(a2, b1), f(a2, b2), f(a1, b2)]
    miss = r.randrange(4)
    ans = vals[miss]
    known = [v for i, v in enumerate(vals) if i != miss]
    if len(set(vals)) < 3:
        return None
    names = ['левая верхняя', 'правая верхняя', 'правая нижняя', 'левая нижняя']
    what = 'площадь' if area else 'периметр'
    st = r.randrange(4)
    obj = [('Лист картона', 'частей'), ('Прямоугольный участок', 'участков'), ('Прямоугольное окно', 'стёкол'),
           ('Прямоугольная клумба', 'секций')][st]
    lab = ['?' if i == miss else str(v) for i, v in enumerate(vals)]
    parts = ', '.join(f'{names[i]} — {vals[i]}' for i in range(4) if i != miss)
    q = (f'{obj[0]} двумя прямыми разрезами, параллельными его сторонам, разделён на четыре прямоугольные части. Известно, что '
         f'{"площади" if area else "периметры"} трёх частей такие: {parts} (см. рисунок). Найдите {what} {names[miss].replace("ая", "ой").replace("яя", "ей")} части.')
    q = q.replace('Прямоугольная клумба двумя прямыми разрезами', 'Прямоугольная клумба двумя прямыми дорожками').replace(
        'клумба двумя прямыми дорожками, параллельными его сторонам, разделён', 'клумба двумя прямыми дорожками, параллельными её сторонам, разделена')
    q = q.replace('Прямоугольное окно двумя прямыми разрезами', 'Прямоугольное окно двумя прямыми рейками').replace(
        'окно двумя прямыми рейками, параллельными его сторонам, разделён', 'окно двумя прямыми рейками, параллельными его сторонам, разделено')
    svg = split_svg(vals, lab)

    def chk():
        found = set()
        for x1 in range(1, 13):
            for x2 in range(1, 13):
                for y1 in range(1, 13):
                    for y2 in range(1, 13):
                        vv = [f(x1, y1), f(x2, y1), f(x2, y2), f(x1, y2)]
                        if all(vv[i] == vals[i] for i in range(4) if i != miss):
                            found.add(vv[miss])
        return found == {ans}
    rule = 'S₁·S₃ = S₂·S₄' if area else 'P₁ + P₃ = P₂ + P₄'
    return pcard(q, num(ans), e=f'Для противоположных частей {rule}. Ответ: {ans}.', svg=svg), chk


def ring_answers(hub, given, target):
    """Все возможные значения расстояния target на кольце при известных расстояниях от hub до трёх точек и одном
    дополнительном расстоянии given = ((i, j), d); длина кольца неизвестна (перебор)."""
    dist = given['hub']
    (gi, gj), gd = given['extra']
    found = set()
    others = sorted(dist)
    mx = max(list(dist.values()) + [gd])
    for LL in range(2 * mx, 2 * (sum(dist.values()) + gd) + 2):
        dd = lambda x, y: min((x - y) % LL, (y - x) % LL)
        for signs in itertools.product((1, -1), repeat=3):
            pos = {hub: 0}
            for o, sg in zip(others, signs):
                pos[o] = sg * dist[o] % LL
            if dd(pos[gi], pos[gj]) == gd:
                found.add(dd(pos[target[0]], pos[target[1]]))
                if len(found) > 1:
                    return found
    return found


@P('eb21-ring', 'Точки на кольце: расстояния по кратчайшей дуге',
   'Расставляем точки на окружности по известным расстояниям; из двух вариантов расположения подходит один — находим искомое.',
   'Сюжет (кольцевая дорога, беговая дорожка, кольцевая линия метро, трасса), расстояния.',
   'расстояние по кратчайшей дуге',
   r'На кольцевой дороге',
   ['складывают расстояния, не проверяя расположение', 'берут длинную дугу'],
   '«На кольцевой дороге расположено четыре бензоколонки: А, Б, В и Г … Найдите расстояние … между Б и В».')
def gen_eb21_ring(r):
    for _ in range(60):
        L = r.randrange(60, 241, 5)
        P = [0] + r.sample(range(5, L, 5), 3)
        d = lambda x, y: min((x - y) % L, (y - x) % L)
        if min(d(P[i], P[j]) for i in range(4) for j in range(i + 1, 4)) == 0:
            continue
        opts = []
        for hub in range(4):
            oth = [k for k in range(4) if k != hub]
            for gi, gj in itertools.combinations(oth, 2):
                tgt = tuple(k for k in oth if k not in (gi, gj)) + (None,)
                for t2 in (gi, gj):
                    target = (tgt[0], t2)
                    given = {'hub': {o: d(P[hub], P[o]) for o in oth}, 'extra': ((gi, gj), d(P[gi], P[gj]))}
                    if ring_answers(hub, given, target) == {d(P[target[0]], P[target[1]])}:
                        opts.append((hub, given, target))
        if opts:
            break
    else:
        return None
    hub, given, target = r.choice(opts)
    ans = d(P[target[0]], P[target[1]])
    st = r.randrange(4)
    obj = [('На кольцевой автодороге стоят четыре заправки', 'км', 'километрах', ['«Север»', '«Юг»', '«Запад»', '«Восток»'], 'заправками'),
           ('На замкнутой велотрассе установлены четыре пункта питания', 'км', 'километрах', ['№ 1', '№ 2', '№ 3', '№ 4'], 'пунктами'),
           ('Вокруг озера проложена кольцевая тропа, на ней четыре беседки', 'м', 'метрах', ['«Ива»', '«Липа»', '«Клён»', '«Дуб»'], 'беседками'),
           ('На кольцевой линии узкоколейки четыре станции', 'км', 'километрах', ['Лесная', 'Речная', 'Горная', 'Полевая'], 'станциями')][st]
    lab = obj[3][:]
    r.shuffle(lab)
    mult = 10 if obj[1] == 'м' else 1
    pairs = [((hub, o), dd_) for o, dd_ in given['hub'].items()] + [given['extra']]
    r.shuffle(pairs)
    nm = lambda i, j: f'{lab[i]} и {lab[j]}' if r.random() < 0.5 else f'{lab[j]} и {lab[i]}'
    facts = '; '.join(f'{nm(i, j)} разделяют {T(v * mult)} {obj[1]}' for (i, j), v in pairs)
    q = (f'{obj[0]}: {", ".join(sorted(lab)[:-1])} и {sorted(lab)[-1]}. Если двигаться по кольцу кратчайшим путём, то {facts}. '
         f'Какое расстояние по кольцу (по кратчайшей дуге) между {obj[4]} {nm(*target)}? Ответ дайте в {obj[2]}.')

    def chk():
        # независимо: для каждой длины кольца перебираем все точки кольца на нужном расстоянии от hub
        found = set()
        dist = given['hub']
        (gi, gj), gd = given['extra']
        top = 2 * (sum(dist.values()) + gd) + 2
        for LL in range(2, top):
            dd = lambda x, y: min((x - y) % LL, (y - x) % LL)
            cand = {o: [x for x in range(LL) if dd(0, x) == v] for o, v in dist.items()}
            for combo in itertools.product(*cand.values()):
                pos = dict(zip(cand.keys(), combo))
                pos[hub] = 0
                if dd(pos[gi], pos[gj]) == gd:
                    found.add(dd(pos[target[0]], pos[target[1]]))
        return found == {ans}
    return pcard(q, num(ans * mult), e=f'Расставляем точки на кольце и проверяем варианты. Ответ: {ans * mult}.'), chk


@P('eb21-table-rows', 'Таблица: число строк по суммам столбцов и границам суммы строки',
   'Сумма всех чисел S; если сумма строки строго между a и b, то n·a < S < n·b — ищем единственное n.',
   'Число столбцов, суммы по столбцам, границы суммы строки.',
   'n: S/b < n < S/a',
   r'В таблице (три|четыре|два) столбца',
   ['не используют строгие неравенства'],
   '«В таблице три столбца и несколько строк … Сколько всего строк в таблице?»')
def gen_eb21_table_rows(r):
    k = r.choice([2, 3, 4])
    n = r.randint(4, 12)
    a = r.randint(8, 40)
    b = a + r.randint(2, 4)
    # суммы строк — целые числа от a + 1 до b − 1, поэтому n·(a + 1) ≤ S ≤ n·(b − 1); такое n должно быть единственным
    S = r.randint(n * (a + 1), n * (b - 1))
    ns = [m for m in range(1, 200) if m * (a + 1) <= S <= m * (b - 1)]
    if ns != [n]:
        return None
    # раскладываем S на k столбцов близких величин (как в банке: 72, 81, 91), каждый ≥ n
    base = S // k
    cols = [base + r.randint(-base // 4, base // 4) for _ in range(k - 1)]
    cols.append(S - sum(cols))
    if min(cols) < n or abs(cols[-1] - base) > base // 3:
        return None
    ans = n
    colw = {2: 'двух', 3: 'трёх', 4: 'четырёх'}[k]
    st = r.randrange(3)
    ctext = ', '.join(f'{"во" if i == 1 else "в"} {ordw(i + 1, "prep_m")} — {c}' for i, c in enumerate(cols))
    if st == 0:
        q = (f'Таблица состоит из {colw} столбцов и нескольких строк, в каждой клетке записано натуральное число. Сумма чисел '
             f'по столбцам: {ctext}. Сумма чисел в любой строке больше {a}, но меньше {b}. Сколько строк в таблице?')
    elif st == 1:
        q = (f'Школьники заполнили таблицу из {colw} столбцов натуральными числами. Суммы чисел в столбцах равны '
             f'{", ".join(map(str, cols[:-1]))} и {cols[-1]}, а сумма чисел каждой строки заключена строго между {a} и {b}. '
             f'Сколько строк в этой таблице?')
    else:
        q = (f'В каждую клетку прямоугольной таблицы, в которой {colw.replace("двух", "два").replace("трёх", "три").replace("четырёх", "четыре")} '
             f'столбца, вписали натуральное число. Суммы по столбцам: {ctext}. В каждой строке сумма чисел больше {a} и меньше {b}. '
             f'Найдите число строк таблицы.')

    def chk():
        # независимо: строим таблицу — делим S на ans строк с суммами строго между a и b (целые суммы), и проверяем,
        # что при другом числе строк это невозможно
        tot = sum(cols)
        # m строк возможны, если tot раскладывается на m целых слагаемых из (a; b): перебор «сколько строк с суммой s»
        # заменяем проверкой крайних раскладов — все суммы a + 1 или все b − 1 — и равномерного
        ok = lambda m: m * (a + 1) <= tot <= m * (b - 1)
        rows = [tot // ans + (1 if i < tot % ans else 0) for i in range(ans)]
        return all(a < s_ < b for s_ in rows) and min(cols) >= ans and [m for m in range(1, tot + 1) if ok(m)] == [ans]
    return a_card(q, ans, f'Сумма всех чисел {S}; сумма каждой строки — целое число от {a + 1} до {b - 1}, поэтому '
                          f'{a + 1}·n ≤ {S} ≤ {b - 1}·n ⇒ n = {ans}.'), chk


@P('eb21-house', 'Дом: этажи, квартиры на этаже и подъезды по общему числу квартир',
   'Число квартир = подъезды × этажи × квартиры на этаже; раскладываем на три множителя с условием порядка.',
   'Общее число квартир, условие порядка (этажей больше, чем квартир на этаже, и т. д.), что спрашивают.',
   'разложение N = p·f·k, f > k > p > 1',
   r'Во всех подъездах дома одинаковое число этажей',
   ['не проверяют неравенства', 'путают этажи и квартиры'],
   '«Во всех подъездах дома одинаковое число этажей … Сколько этажей в доме, если всего в нём … квартир?»')
def gen_eb21_house(r):
    p, k, f = sorted(r.sample(range(2, 18), 3))
    N = p * k * f
    sols = [(pp, kk, N // (pp * kk)) for pp in range(2, 40) for kk in range(pp + 1, 40) if N % (pp * kk) == 0 and N // (pp * kk) > kk]
    if len(sols) != 1 or f > 25:
        return None
    ask = r.randrange(3)
    ans = [f, k, p][ask]
    st = r.randrange(3)
    what = ['Сколько этажей в доме', 'Сколько квартир на каждом этаже', 'Сколько подъездов в доме'][ask]
    if st == 0:
        q = (f'В доме {pl(N, "квартира", "квартиры", "квартир")}. Все подъезды одинаковой этажности, на каждом этаже одно и то же '
             f'число квартир. Подъездов больше одного, но меньше, чем квартир на этаже, а квартир на этаже меньше, чем этажей. {what}?')
    elif st == 1:
        q = (f'Во всех подъездах новостройки одно и то же число этажей, а на каждом этаже одно и то же число квартир. Этажей больше, '
             f'чем квартир на этаже, квартир на этаже больше, чем подъездов, а подъездов не меньше двух. Всего в доме '
             f'{pl(N, "квартира", "квартиры", "квартир")}. {what}?')
    else:
        q = (f'Застройщик сдал дом на {pl(N, "квартиру", "квартиры", "квартир")}. В каждом подъезде одинаковое число этажей, на каждом '
             f'этаже — одинаковое число квартир. Известно, что подъездов хотя бы два, квартир на этаже больше, чем подъездов, а этажей '
             f'больше, чем квартир на этаже. {what}?')

    def chk():
        ss = [(pp, kk, ff) for pp in range(2, N + 1) for kk in range(pp + 1, N + 1) for ff in [N // (pp * kk)]
              if pp * kk <= N and pp * kk * ff == N and ff > kk]
        return len(ss) == 1 and [ss[0][2], ss[0][1], ss[0][0]][ask] == ans
    return a_card(q, ans, f'{N} = {p}·{k}·{f} — единственное разложение с нужным порядком. Ответ: {ans}.'), chk


ORD_PREP = {i: ordw(i, 'prep_m') for i in range(1, 13)}


@P('eb21-flat', 'Номер квартиры: подъезд или этаж',
   'В подъезде (этажи × квартиры на этаже) квартир; номер квартиры определяет подъезд, а внутри подъезда — этаж.',
   'Этажность, квартир на этаже (известно или находится), номер квартиры, что спрашивают.',
   'подъезд = ⌈n / (F·k)⌉; этаж = ⌈(n − (подъезд − 1)·F·k) / k⌉',
   r'в квартире №|Саша пригласил',
   ['округляют вниз', 'забывают, что нумерация сквозная'],
   '«Саша пригласил Петю в гости, сказав, что живёт в … подъезде в квартире № … На каком этаже живёт Саша?»')
def gen_eb21_flat(r):
    F_ = r.randint(5, 16)
    k = r.randint(2, 8)
    ent = r.randint(2, 10)
    fl = r.randint(1, F_)
    pos = r.randint(1, k)
    n = (ent - 1) * F_ * k + (fl - 1) * k + pos
    st = r.randrange(3)
    w, w2 = Who(r), Who(r)
    if st == 0:  # k известно, ищем подъезд
        ans = ent
        q = (f'Квартиры в доме пронумерованы подряд, начиная с первой; в каждом подъезде {pl(F_, "этаж", "этажа", "этажей")}, а на '
             f'каждом этаже {pl(k, "квартира", "квартиры", "квартир")}. {w.n} {w.v("получил")} ключи от квартиры № {n}. В каком по '
             f'счёту подъезде эта квартира?')
    elif st == 1:  # k известно, ищем этаж
        ans = fl
        q = (f'Дом {F_}-этажный, в каждом подъезде на каждом этаже {pl(k, "квартира", "квартиры", "квартир")}, квартиры '
             f'пронумерованы подряд, начиная с первой. На каком этаже находится квартира № {n}?')
    else:  # k неизвестно: подъезд и номер, этажность — найти этаж
        ks = [kk for kk in range(1, 20) if (ent - 1) * F_ * kk < n <= ent * F_ * kk]
        if len(ks) != 1:
            return None
        ans = fl
        q = (f'{w.n} {w.v("позвал")} {w2.g} в гости и {w.v("сказал")}, что живёт в {ORD_PREP.get(ent, str(ent) + "-м")} подъезде в квартире '
             f'№ {n}, но этаж не {w.v("назвал")}. Подойдя к дому, {w2.n} {w2.v("увидел")}, что в нём {pl(F_, "этаж", "этажа", "этажей")}. '
             f'На каком этаже живёт {w.n}? (На всех этажах число квартир одинаковое, нумерация квартир начинается с единицы.)')
        q = q.replace('позвала', 'позвала')

    def chk():
        kk = k if st < 2 else [x for x in range(1, 20) if (ent - 1) * F_ * x < n <= ent * F_ * x][0]
        num_ = 0
        for e_ in range(1, 20):
            for f_ in range(1, F_ + 1):
                for _ in range(kk):
                    num_ += 1
                    if num_ == n:
                        return (e_ if st == 0 else f_) == ans
        return False
    per = F_ * k
    e = (f'В подъезде {F_} · {k} = {pl(per, "квартира", "квартиры", "квартир")}; квартира № {n} — {ent}-й подъезд, '
         f'в нём она {n - (ent - 1) * per}-я, это {fl}-й этаж. Ответ: {ans}.')
    if st == 2:
        e = f'Квартир на этаже k: ({ent} − 1) · {F_} · k < {n} ≤ {ent} · {F_} · k, отсюда k = {k}. ' + e
    return a_card(q, ans, e), chk


@P('eb21-lines', 'Распил по линиям разных цветов',
   'Кусков на 1 больше, чем линий: линий каждого цвета = кусков − 1; всего кусков = сумма линий + 1.',
   'Предмет (палка, бревно, лента, труба), цветов 2–3, число кусков для каждого цвета.',
   'Σ(kᵢ − 1) + 1',
   r'отмечены поперечные линии',
   ['складывают куски', 'забывают прибавить 1'],
   '«На палке отмечены поперечные линии красного, жёлтого и зелёного цветов …»')
def gen_eb21_lines(r):
    cols = r.choice([[('синим', 'синие'), ('белым', 'белые'), ('чёрным', 'чёрные')], [('оранжевым', 'оранжевые'), ('фиолетовым', 'фиолетовые')],
                     [('голубым', 'голубые'), ('розовым', 'розовые'), ('серым', 'серые')], [('коричневым', 'коричневые'), ('белым', 'белые')]])
    ks = [r.randint(2, 15) for _ in cols]
    ans = sum(k - 1 for k in ks) + 1
    obj = r.choice([('На длинной рейке', 'рейку'), ('На бревне', 'бревно'), ('На ленте', 'ленту'), ('На трубе', 'трубу'), ('На брусе', 'брус')])
    cut = 'разрезать' if obj[1] == 'ленту' else 'распилить'
    parts = f'только по {cols[0][0]} меткам, получится {pl(ks[0], "кусок", "куска", "кусков")}; ' + '; '.join(
        f'только по {c[0]} — {pl(k, "кусок", "куска", "кусков")}' for c, k in zip(cols[1:], ks[1:]))
    q = (f'{obj[0]} нанесены поперечные метки {"двух" if len(cols) == 2 else "трёх"} цветов: {", ".join(c[1] for c in cols[:-1])} и {cols[-1][1]} (метки разных цветов не совпадают). '
         f'Если {cut} {obj[1]} {parts}. Сколько кусков получится, если {cut} {obj[1]} по всем меткам?')

    def chk():
        pos = []
        x = 0
        for k in ks:
            for _ in range(k - 1):
                x += 1
                pos.append(x)
        return len(set(pos)) + 1 == ans
    return a_card(q, ans, f'Меток: {" + ".join(str(k - 1) for k in ks)} = {ans - 1}; кусков на 1 больше. Ответ: {ans}.'), chk


@P('eb21-boards', 'Распилы и куски: сколько было заготовок',
   'Каждый распил добавляет один кусок: кусков = заготовок + распилов.',
   'Сюжет (доски, брёвна, ленты, батоны, трубы), распилы, куски, что спрашивают.',
   'заготовок = кусков − распилов',
   r'Взяли несколько досок',
   ['считают, что кусков вдвое больше распилов'],
   '«Взяли несколько досок и распилили их … Сколько досок взяли?»')
def gen_eb21_boards(r):
    b = r.randint(2, 12)
    c = r.randint(3, 30)
    pieces = b + c
    ask = r.randrange(3)
    obj = r.choice([('брёвен', 'распил', 'распила', 'распилов', 'распилили', 'распилами'),
                    ('батонов', 'разрез', 'разреза', 'разрезов', 'разрезали', 'разрезами'),
                    ('труб', 'распил', 'распила', 'распилов', 'распилили', 'распилами'),
                    ('шоколадных плиток', 'разлом', 'разлома', 'разломов', 'разломали', 'разломами')])
    cuts = pl(c, obj[1], obj[2], obj[3])
    if ask == 0:
        ans = b
        q = (f'Несколько {obj[0]} {obj[4]} поперёк на части. Всего сделали {cuts} и получили {pl(pieces, "кусок", "куска", "кусков")}. '
             f'Сколько {obj[0]} было?')
    elif ask == 1:
        ans = pieces
        q = (f'Каждое из нескольких {obj[0]} {obj[4]} поперёк хотя бы один раз. {obj[0].capitalize()} было {b}, а {obj[3]} всего сделали {c}. '
             f'Сколько кусков получилось?')
        q = q.replace('Каждое из нескольких брёвен', 'Каждое из нескольких брёвен').replace('Каждое из нескольких батонов', 'Каждый из нескольких батонов') \
             .replace('Каждое из нескольких труб', 'Каждую из нескольких труб').replace('Каждое из нескольких шоколадных плиток', 'Каждую из нескольких шоколадных плиток')
        if c < b:
            return None
    else:
        ans = c
        cut3 = obj[3] if obj[1] != 'разлом' else 'распилов'
        q = (f'Взяли {pl(b, "длинную заготовку", "длинные заготовки", "длинных заготовок")} и {"распилили" if cut3 == "распилов" else obj[4]} '
             f'их поперёк на части, всего получилось {pl(pieces, "кусок", "куска", "кусков")}. Сколько {cut3} сделали?')

    def chk():
        pcs = [1] * b
        for i in range(c):
            pcs[i % b] += 1
        return [b, sum(pcs), c][ask] == ans
    return a_card(q, ans, f'Кусков = заготовок + распилов. Ответ: {ans}.'), chk


def graphical(ds):
    """Критерий Хавела — Хакими: существует ли граф с такими степенями."""
    ds = sorted(ds, reverse=True)
    while ds and ds[0] > 0:
        d = ds.pop(0)
        if d > len(ds):
            return False
        for i in range(d):
            ds[i] -= 1
            if ds[i] < 0:
                return False
        ds.sort(reverse=True)
    return True


@P('eb21-degrees', 'Сумма степеней: сколько всего связей',
   'Каждое соединение учтено дважды (у двух концов): связей = (сумма степеней) / 2.',
   'Сюжет (столбы с проводами, страны и договоры, компьютеры с кабелями, рукопожатия), числа.',
   'Σdᵢ / 2',
   r'соединены между собой проводами|подписали договор',
   ['не делят на 2'],
   '«Семь столбов соединены между собой проводами так, что от каждого столба отходит ровно 4 провода …»')
def gen_eb21_degrees(r):
    mixed = r.random() < 0.5
    if mixed:
        n1, n2 = r.randint(2, 8), r.randint(2, 8)
        d1, d2 = r.randint(1, n1 + n2 - 1), r.randint(1, n1 + n2 - 1)
        if d1 == d2 or (n1 * d1 + n2 * d2) % 2:
            return None
        ans = (n1 * d1 + n2 * d2) // 2
        n = n1 + n2
    else:
        n = r.randint(5, 16)
        d = r.randint(2, n - 1)
        if n * d % 2:
            return None
        ans = n * d // 2
    degs = [d1] * n1 + [d2] * n2 if mixed else [d] * n
    if not graphical(degs):
        return None
    st = r.randrange(4)
    if st == 0:
        obj = ('компьютеров в офисе', 'кабель', 'кабеля', 'кабелей', 'соединён кабелями', 'Сколько всего кабелей проложено', 'В офисе')
    elif st == 1:
        obj = ('участников встречи', 'рукопожатие', 'рукопожатия', 'рукопожатий', 'обменялся рукопожатиями', 'Сколько всего было рукопожатий', 'На встрече')
    elif st == 2:
        obj = ('городов области', 'авиарейс', 'авиарейса', 'авиарейсов', 'связан прямыми авиарейсами', 'Сколько всего прямых авиарейсов', 'В области')
    else:
        obj = ('шахматистов турнира', 'партию', 'партии', 'партий', 'сыграл по одной партии', 'Сколько всего партий сыграно', 'В турнире')
    # числа словами в творительном падеже, как в КИМ: «ровно с пятью другими»
    ins = {1: 'одним другим', 2: 'двумя', 3: 'тремя', 4: 'четырьмя', 5: 'пятью', 6: 'шестью', 7: 'семью', 8: 'восемью', 9: 'девятью',
           10: 'десятью', 11: 'одиннадцатью', 12: 'двенадцатью', 13: 'тринадцатью', 14: 'четырнадцатью', 15: 'пятнадцатью'}
    oth = lambda k: ins[k] if k == 1 else f'{ins[k]} другими'
    nom = [('компьютер', 'компьютера', 'компьютеров'), ('участник', 'участника', 'участников'), ('город', 'города', 'городов'),
           ('шахматист', 'шахматиста', 'шахматистов')][st]
    if mixed:
        q = (f'{obj[6]} {pl(n, *nom)}, причём {n1} из них {obj[4].replace("соединён", "соединены").replace("обменялся", "обменялись").replace("связан", "связаны").replace("сыграл", "сыграли")} '
             f'ровно с {oth(d1)}, а каждый из остальных {n2} — ровно с {oth(d2)}. {obj[5]}?')
    else:
        q = f'Каждый из {n} {obj[0]} {obj[4]} ровно с {oth(d)}. {obj[5]}?'

    def chk():
        ds = sorted(degs, reverse=True)
        if sum(ds) % 2:
            return False
        for k in range(1, len(ds) + 1):
            if sum(ds[:k]) > k * (k - 1) + sum(min(x, k) for x in ds[k:]):
                return False
        return sum(ds) // 2 == ans
    return a_card(q, ans, f'Сумма степеней {sum(degs)}, каждая связь посчитана дважды. Ответ: {ans}.'), chk



@P('eb21-bipartite', 'Дружба мальчиков и девочек: сколько мальчиков',
   'Число пар «мальчик — девочка» считаем двумя способами: m·a = d·b, m + d = N ⇒ m = N·b/(a + b).',
   'Сюжет (класс, танцевальный кружок, команда, лагерь), N, a, b, что спрашивают.',
   'm = N·b / (a + b)',
   r'Каждый мальчик дружит с',
   ['путают, кто с кем дружит'],
   '«В классе … учеников. Каждый мальчик дружит с … девочками, а каждая девочка — с … мальчиками …»')
def gen_eb21_bipartite(r):
    a, b = r.sample(range(2, 8), 2)
    g = math.gcd(a, b)
    unit = r.randint(1, 6)
    m, d = b // g * unit * r.choice([1, 2]) if False else b // g * unit, a // g * unit
    if m < a or d < b:
        return None
    N = m + d
    if not 12 <= N <= 40:
        return None
    ask_boys = r.random() < 0.6
    ans = m if ask_boys else d
    wa = {2: 'двумя', 3: 'тремя', 4: 'четырьмя', 5: 'пятью', 6: 'шестью', 7: 'семью'}
    st = r.randrange(4)
    ctx = ['В классе', 'В танцевальном кружке', 'В летнем отряде', 'В театральной студии'][st]
    verb = ['дружит', 'танцевал в паре хотя бы раз', 'переписывается', 'репетировал сцены'][st]
    verb_f = ['дружит', 'танцевала в паре хотя бы раз', 'переписывается', 'репетировала сцены'][st]
    q = (f'{ctx} {pl(N, "ребёнок", "ребёнка", "детей") if st == 2 else pl(N, "ученик", "ученика", "учеников")} — мальчики и девочки. '
         f'Каждый мальчик {verb} ровно с {wa[a]} девочками, а каждая девочка {verb_f} ровно с {wa[b]} мальчиками. '
         f'{"Сколько мальчиков" if ask_boys else "Сколько девочек"} {"в классе" if st == 0 else "среди них"}?')

    def chk():
        ms = [mm for mm in range(1, N) if mm * a == (N - mm) * b]
        return ms and (ms[0] if ask_boys else N - ms[0]) == ans
    return a_card(q, ans, f'm·{a} = d·{b}, m + d = {N}. Ответ: {ans}.'), chk


@P('eb21-pigeon', 'Среди любых k предметов есть хотя бы один данного вида',
   '«Среди любых k есть хотя бы один X» ⇒ предметов другого вида не больше k − 1; две оценки вместе дают точное число.',
   'Сюжет (грибы, шары, карандаши, рыбы), общее число, два порога, что спрашивают.',
   'другого вида = k − 1',
   r'среди любых \d+ \w+ (имеется|есть) хотя бы один',
   ['берут k вместо k − 1'],
   '«В корзине лежит … грибов: рыжики и грузди. Известно, что среди любых … грибов имеется хотя бы один рыжик …»')
def gen_eb21_pigeon(r):
    A = r.randint(5, 40)
    B = r.randint(5, 40)
    N = A + B
    # среди любых B+1 есть хотя бы один A-предмет; среди любых A+1 есть хотя бы один B-предмет
    st = r.randrange(4)
    K = [('В ящике', ('яблоко', 'яблока', 'яблок'), ('антоновка', 'антоновки', 'антоновок', 'хотя бы одна антоновка'),
          ('ранетка', 'ранетки', 'ранеток', 'хотя бы одна ранетка'), 'в ящике', ''),
         ('В коробке', ('шар', 'шара', 'шаров'), ('красный', 'красные', 'красных', 'хотя бы один красный'),
          ('синий', 'синие', 'синих', 'хотя бы один синий'), 'в коробке', ' шаров'),
         ('В наборе', ('карандаш', 'карандаша', 'карандашей'), ('простой', 'простые', 'простых', 'хотя бы один простой'),
          ('цветной', 'цветные', 'цветных', 'хотя бы один цветной'), 'в наборе', ' карандашей'),
         ('В аквариуме', ('рыбка', 'рыбки', 'рыбок'), ('гуппи', 'гуппи', 'гуппи', 'хотя бы одна гуппи'),
          ('меченосец', 'меченосцы', 'меченосцев', 'хотя бы один меченосец'), 'в аквариуме', '')][st]
    ask_a = r.random() < 0.5
    ans = A if ask_a else B
    gen = {0: ('яблока', 'яблок', 'яблок'), 1: ('шара', 'шаров', 'шаров'), 2: ('карандаша', 'карандашей', 'карандашей'),
           3: ('рыбки', 'рыбок', 'рыбок')}[st]
    q = (f'{K[0]} {pl(N, *K[1])}: {K[2][1]} и {K[3][1]}. Известно, что среди любых {pl(B + 1, *gen)} найдётся {K[2][3]}, а среди '
         f'любых {pl(A + 1, *gen)} — {K[3][3]}. Сколько {K[2][2] if ask_a else K[3][2]}{K[5]} {K[4]}?')
    q = q.replace('В ящике', 'В ящике лежат').replace('В коробке', 'В коробке лежат').replace('В наборе', 'В наборе').replace('В аквариуме', 'В аквариуме плавают')
    if st == 3 and (N % 10 == 1 and N % 100 != 11):
        q = q.replace('плавают', 'плавает')
    if st in (0, 1) and (N % 10 == 1 and N % 100 != 11):
        q = q.replace('лежат', 'лежит')

    def chk():
        sols = [x for x in range(N + 1) if (N - x) <= B and x <= A]  # x — число предметов первого вида
        return len(sols) == 1 and (sols[0] if ask_a else N - sols[0]) == ans
    return a_card(q, ans, f'Второго вида не больше {B}, первого не больше {A}, а всего {N}. Ответ: {ans}.'), chk


def tennis_states(T):
    """Все возможные тройки (сыграно партий каждым) после T партий «на вылет» при старте любой пары."""
    res = set()
    for start in ((0, 1), (0, 2), (1, 2)):
        frontier = {(start, (0, 0, 0))}
        for _ in range(T):
            nxt = set()
            for (pair, cnt) in frontier:
                c = list(cnt)
                for i in pair:
                    c[i] += 1
                out = 3 - pair[0] - pair[1]
                for winner in pair:
                    nxt.add((tuple(sorted((winner, out))), tuple(c)))
            frontier = nxt
        res |= {cnt for _, cnt in frontier}
    return res


@P('eb21-tennis', 'Игра «на вылет» втроём: сколько партий сыграл третий',
   'Игрок не пропускает две партии подряд: пропустил не больше, чем сыграл + 1; отсюда общее число партий и ответ.',
   'Игра (настольный теннис, шахматы, армрестлинг, шашки), числа партий двух игроков.',
   'T = b, третий сыграл 2T − a − b',
   r'игрок, проигравший партию, уступает место',
   ['считают, что все сыграли поровну'],
   '«Миша, Коля и Лёша играют в настольный теннис: игрок, проигравший партию, уступает место …»')
def gen_eb21_tennis(r):
    a = r.randint(3, 11)
    b = 2 * a + 1
    ans = b - a
    names = r.sample(['Антон', 'Борис', 'Вадим', 'Гриша', 'Денис', 'Егор', 'Жора', 'Илья', 'Костя', 'Олег'], 3)
    game = r.choice([('в шашки', 'партию', 'партии', 'партий'), ('в настольный хоккей', 'матч', 'матча', 'матчей'),
                     ('в армрестлинг', 'поединок', 'поединка', 'поединков'), ('в пинг-понг', 'партию', 'партии', 'партий')])
    q = (f'{names[0]}, {names[1]} и {names[2]} играют {game[0]} на вылет: проигравший уступает место тому, кто не участвовал в '
         f'игре, ничьих не бывает. Когда закончили, выяснилось, что {names[0]} сыграл {pl(a, *game[1:])}, а {names[1]} — '
         f'{pl(b, *game[1:])}. Сколько {game[3]} сыграл {names[2]}?')

    def chk():
        found = set()
        for T in range(b, 2 * b + 2):
            for cnt in tennis_states(T):
                if cnt[0] == a and cnt[1] == b:
                    found.add(cnt[2])
        return found == {ans}
    return a_card(q, ans, f'Всего партий не больше {a} + {a} + 1 = {b} и не меньше {b}; третий сыграл 2·{b} − {a} − {b} = {ans}.'), chk


@P('eb21-exchange', 'Обмен фишек: сколько обменов',
   'Каждый обмен меняет общее число на (получил − отдал); число обменов = изменение / (изменение за обмен).',
   'Сюжет (фишки, марки, наклейки, купоны), курс обмена, было и стало.',
   '(N₀ − N₁) / (s − g)',
   r'меняет маленькие фишки на большие',
   ['делят на число отданных, а не на разность'],
   '«Петя меняет маленькие фишки на большие. За один обмен он получает … До обменов у Пети было …»')
def gen_eb21_exchange(r):
    g = r.randint(1, 6)
    sgive = r.randint(g + 2, 15)
    k = r.randint(3, 20)
    N1 = r.randint(20, 90)
    N0 = N1 + k * (sgive - g)
    if N0 < k * sgive:
        return None
    ans = k
    w = Who(r)
    obj = r.choice([('обычные наклейки', ('обычную наклейку', 'обычные наклейки', 'обычных наклеек'), 'на голографические',
                     ('голографическую', 'голографические', 'голографических'), ('наклейка', 'наклейки', 'наклеек')),
                    ('простые марки', ('простую марку', 'простые марки', 'простых марок'), 'на юбилейные',
                     ('юбилейную', 'юбилейные', 'юбилейных'), ('марка', 'марки', 'марок')),
                    ('медные жетоны', ('медный жетон', 'медных жетона', 'медных жетонов'), 'на серебряные',
                     ('серебряный', 'серебряных', 'серебряных'), ('жетон', 'жетона', 'жетонов')),
                    ('бумажные купоны', ('бумажный купон', 'бумажных купона', 'бумажных купонов'), 'на золотые',
                     ('золотой', 'золотых', 'золотых'), ('купон', 'купона', 'купонов'))])
    q = (f'{w.n} обменивает {obj[0]} {obj[2]}: за каждый обмен {w.n} отдаёт {pl(sgive, *obj[1])} и получает '
         f'{pl(g, *obj[3])}. Сначала у {w.g} было {pl(N0, *obj[4])} (и тех, и других), а после нескольких обменов стало {N1}. '
         f'Сколько обменов {w.v("совершил")} {w.n}?')

    def chk():
        cur, cnt = N0, 0
        while cur > N1:
            cur += g - sgive
            cnt += 1
        return cur == N1 and cnt == ans
    return a_card(q, ans, f'Каждый обмен уменьшает число на {sgive - g}: ({N0} − {N1}) : {sgive - g} = {ans}.'), chk


@P('eb21-coins', 'Обменный пункт с двумя операциями',
   'x операций первого вида, y второго: баланс золота (или другой валюты) даёт уравнение, число медных — второе; ответ — изменение серебра.',
   'Коэффициенты обмена, число появившихся медных монет, сюжет (монеты, жетоны, баллы).',
   'система: a·x = d·y, x + y = K; ответ c·y − b·x',
   r'В обменном пункте можно совершить одну из двух операций',
   ['путают, какая операция увеличивает серебро'],
   '«В обменном пункте можно совершить одну из двух операций … На сколько уменьшилось количество серебряных монет …?»')
def gen_eb21_coins(r):
    a, b = r.randint(2, 8), r.randint(2, 16)
    c, d = r.randint(2, 9), r.randint(1, 6)
    # золото: −a·x + d·y = 0, медь: x + y = K
    g = math.gcd(a, d)
    x0, y0 = d // g, a // g
    t = r.randint(1, 8)
    x, y = x0 * t, y0 * t
    K = x + y
    dec_ = c * y - b * x
    if dec_ <= 0 or K > 80:
        return None
    ans = dec_
    st = r.randrange(3)
    # формы: (вин. ед., 2–4, 5+) для каждой валюты
    G = [(('золотую монету', 'золотые монеты', 'золотых монет'), ('серебряную монету', 'серебряные монеты', 'серебряных монет'),
          ('медную монету', 'медные монеты', 'медных монет'), 'одну медную монету', 'серебряные монеты', 'золотых монет', 'серебряных монет', 'медных монет', 'В обменном пункте'),
         (('красный жетон', 'красных жетона', 'красных жетонов'), ('синий жетон', 'синих жетона', 'синих жетонов'),
          ('зелёный жетон', 'зелёных жетона', 'зелёных жетонов'), 'один зелёный жетон', 'синие жетоны', 'красных жетонов', 'синих жетонов', 'зелёных жетонов', 'В игровом автомате'),
         (('рубин', 'рубина', 'рубинов'), ('изумруд', 'изумруда', 'изумрудов'), ('алмаз', 'алмаза', 'алмазов'), 'один алмаз',
          'изумруды', 'рубинов', 'изумрудов', 'алмазов', 'В лавке торговца в компьютерной игре')][st]
    cn = lambda n, f: f'{n} {plural(n, *f)}' if n > 1 else f'1 {f[0]}'
    q = (f'{G[8]} можно выполнять только два вида обмена: 1) отдать {cn(a, G[0])} и получить {cn(b, G[1])} и {G[3]}; '
         f'2) отдать {cn(c, G[1])} и получить {cn(d, G[0])} и {G[3]}. Сначала у игрока были только {G[4]}. После нескольких '
         f'обменов {G[5]} у него не оказалось, {G[6]} стало меньше, зато появилось {K} {plural(K, *G[2])}. На сколько уменьшилось '
         f'количество {G[6]}?')
    q = q.replace(f'появилось {K} ', f'появилось {K} ' if K % 10 != 1 or K % 100 == 11 else f'появился {K} ' if st else f'появилась {K} ')
    X, Y = sp.symbols('X Y')

    def chk():
        sol = sp.solve([sp.Eq(-a * X + d * Y, 0), sp.Eq(X + Y, K)], [X, Y])
        return sol[X].is_integer and c * sol[Y] - b * sol[X] == ans
    return a_card(q, ans, f'x обменов первого вида, y второго: {a}x = {d}y, x + y = {K} ⇒ x = {x}, y = {y}; {c}·{y} − {b}·{x} = {ans}.'), chk





@P('eb21-globe', 'Параллели и меридианы на глобусе: число частей',
   'Параллели делят сферу на p + 1 пояс, меридианы режут каждый пояс на m частей (при m ≥ 1): (p + 1)·m.',
   'Предмет (глобус, мяч, ёлочный шар, арбуз), число параллелей и меридианов.',
   '(p + 1)·m',
   r'параллелей и \d+ меридиан',
   ['считают p·m', 'забывают, что один меридиан сферу не делит'],
   '«На поверхности глобуса фломастером проведены … параллелей и … меридианов. На сколько частей …?»')
def gen_eb21_globe(r):
    p_ = r.randint(2, 30)
    m = r.randint(2, 30)
    ans = (p_ + 1) * m
    st = r.randrange(4)
    obj = ['На школьном глобусе маркером нарисовали', 'На резиновом мяче краской нанесли', 'На ёлочном шаре кисточкой провели',
           'На поверхности модели Земли провели'][st]
    q = (f'{obj} {pl(p_, "параллель", "параллели", "параллелей")} и {pl(m, "меридиан", "меридиана", "меридианов")}. На сколько частей '
         f'эти линии разбивают поверхность{" шара" if st in (1, 2) else ""}? (Меридиан — дуга окружности от Северного полюса до '
         f'Южного, параллель — окружность в плоскости, параллельной плоскости экватора.)')

    def chk():
        # формула Эйлера: V − E + F = 2; V = 2 + p·m, E = m(p + 1) + p·m
        V = 2 + p_ * m
        E = m * (p_ + 1) + p_ * m
        return 2 - V + E == ans
    return a_card(q, ans, f'{pl(p_, "параллель делит", "параллели делят", "параллелей делят")} поверхность на '
                          f'{pl(p_ + 1, "пояс", "пояса", "поясов")}, меридианы режут каждый пояс на {pl(m, "часть", "части", "частей")}: '
                          f'{p_ + 1} · {m} = {ans}.'), chk


@P('eb21-snail', 'Улитка: вверх днём, вниз ночью',
   'Пока не достигнута вершина, за сутки подъём на (a − b); в последний день поднимается на a без сползания.',
   'Сюжет (улитка, лягушка в колодце, гусеница на столбе, альпинист), a, b, высота.',
   '⌈(H − a)/(a − b)⌉ + 1',
   r'Улитка за день заползает',
   ['делят H на (a − b)', 'забывают про последний день'],
   '«Улитка за день заползает вверх по дереву на … м, а за ночь сползает на … м …»')
def gen_eb21_snail(r):
    a = r.randint(3, 9)
    b = r.randint(1, a - 1)
    H = r.randint(a + 3, 50)
    if (H - a) % (a - b) == 0 and r.random() < 0.5:
        return None
    ans = -(-(H - a) // (a - b)) + 1
    if ans < 3:
        return None
    st = r.randrange(4)
    mm = lambda n: pl(n, 'метр', 'метра', 'метров')
    if st == 0:
        q = (f'Гусеница ползёт вверх по столбу высотой {mm(H)}: за день она поднимается на {mm(a)}, а за ночь сползает на {mm(b)}. '
             f'На какой день гусеница впервые окажется на верхушке столба, если начала путь утром от земли?')
    elif st == 1:
        q = (f'Лягушка выбирается из колодца глубиной {mm(H)}. Днём она поднимается на {mm(a)}, а ночью соскальзывает на {mm(b)}. '
             f'За сколько дней лягушка выберется из колодца, если начала подъём утром со дна?')
    elif st == 2:
        q = (f'Жук ползёт вверх по стволу дерева высотой {mm(H)}: за день он поднимается на {mm(a)}, а за ночь сползает на {mm(b)}. '
             f'За сколько дней жук доберётся до вершины дерева, если начал путь утром от земли?')
    else:
        q = (f'Улитка поднимается по стеблю высотой {pl(H * 10, "сантиметр", "сантиметра", "сантиметров")}: за день — на '
             f'{pl(a * 10, "сантиметр", "сантиметра", "сантиметров")}, а за ночь сползает на {pl(b * 10, "сантиметр", "сантиметра", "сантиметров")}. '
             f'За сколько дней улитка доберётся до верхушки стебля, если утром первого дня она была у его основания?')

    def chk():
        h, day = 0, 0
        while True:
            day += 1
            h += a
            if h >= H:
                return day == ans
            h -= b
    u, un = (10, 'см') if st == 3 else (1, 'м')
    return a_card(q, ans, f'К утру k-го дня подъём составляет {(a - b) * u}·(k − 1) {un}, а за k-й день добавляется ещё {a * u} {un}: '
                          f'нужно {(a - b) * u}·(k − 1) + {a * u} ≥ {H * u}. Ответ: {ans}.'), chk


@P('eb21-grasshopper', 'Прыжки на единицу по прямой: сколько различных точек',
   'После n прыжков координата имеет ту же чётность, что n, и |x| ≤ n: n + 1 точка; «не более n» — 2n + 1.',
   'Сюжет (кузнечик, робот, фишка, лягушка), n, «ровно»/«не более».',
   'n + 1 или 2n + 1',
   r'Кузнечик прыгает вдоль координатной прямой',
   ['считают 2n + 1 для «ровно n»'],
   '«Кузнечик прыгает вдоль координатной прямой … Сколько существует различных точек …, совершив ровно … прыжков?»')
def gen_eb21_grasshopper(r):
    n = r.randint(4, 30)
    exact = r.random() < 0.65
    ans = n + 1 if exact else 2 * n + 1
    st = r.randrange(4)
    who = [('Робот-игрушка', 'шаг', 'шага', 'шагов', 'сделав'), ('Фишка на бесконечной клетчатой полосе', 'ход', 'хода', 'ходов', 'сделав'),
           ('Лягушка', 'прыжок', 'прыжка', 'прыжков', 'совершив'), ('Точка на числовой оси', 'сдвиг', 'сдвига', 'сдвигов', 'сделав')][st]
    mv = {0: 'каждым шагом перемещается влево или вправо на единичный отрезок координатной прямой, начиная из точки 0',
          1: 'каждым ходом сдвигается на одну клетку влево или вправо; её начальная клетка отмечена нулём',
          2: 'прыгает по координатной прямой из начала координат, каждый раз на 1 влево или вправо',
          3: 'из начала координат сдвигается каждый раз на 1 в одном из двух направлений'}[st]
    q = (f'{who[0]} {mv}. Сколько различных положений {"она" if st in (1, 2, 3) else "он"} может занять, '
         f'{who[4]} {"ровно" if exact else "не более"} {pl(n, who[1], who[2], who[3])}?')
    if st == 1:
        q = q.replace('Сколько различных положений она может занять, сделав', 'На скольких различных клетках может оказаться фишка, если она сделает')

    def chk():
        cur = {0}
        seen = {0}
        for _ in range(n):
            cur = {x + d for x in cur for d in (-1, 1)}
            seen |= cur
        return len(cur if exact else seen) == ans
    return a_card(q, ans, f'{"Ровно" if exact else "Не более"} {n}: {"n + 1" if exact else "2n + 1"} = {ans}.'), chk


@P('eb21-ribbon', 'Две метки по разные стороны от середины',
   'Разрез в точке на расстоянии x от середины даёт разность частей 2x; метки по разные стороны: расстояние (d₁ + d₂)/2.',
   'Предмет (лента, верёвка, доска, кабель), разности частей, по разные / по одну сторону.',
   '(d₁ + d₂)/2 или |d₁ − d₂|/2',
   r'по разные стороны от (её )?середины',
   ['складывают разности без деления на 2'],
   '«На ленте по разные стороны от её середины отмечены две тонкие поперечные полоски …»')
def gen_eb21_ribbon(r):
    d1, d2 = r.sample(range(4, 90, 2), 2)
    same_side = r.random() < 0.3
    ans = F(abs(d1 - d2), 2) if same_side else F(d1 + d2, 2)
    st = r.randrange(4)
    obj = [('На верёвке', 'верёвку', 'узелка', 'белый', 'чёрный', 'узелку', 'узелками'), ('На доске', 'доску', 'риски', 'левой', 'правой', 'риске', 'рисками'),
           ('На кабеле', 'кабель', 'метки', 'жёлтой', 'зелёной', 'метке', 'метками'), ('На рулоне обоев', 'полосу обоев', 'линии', 'первой', 'второй', 'линии', 'линиями')][st]
    unit = r.choice([('сантиметров', 'сантиметрах', ('сантиметр', 'сантиметра', 'сантиметров')),
                     ('миллиметров', 'миллиметрах', ('миллиметр', 'миллиметра', 'миллиметров'))])
    side = 'по одну сторону от середины' if same_side else 'по разные стороны от середины'
    q = (f'{obj[0]} {side} сделаны две отметки. Если разрезать {obj[1]} по первой отметке, одна часть окажется на {pl(d1, *unit[2])} '
         f'длиннее другой, а если по второй — на {pl(d2, *unit[2])}. Найдите расстояние между отметками. Ответ дайте в {unit[1]}.')

    def chk():
        L = 1000
        x1 = F(L + d1, 2)
        for x2 in (F(L + d2, 2), F(L - d2, 2)):
            if ((x1 - F(L, 2)) * (x2 - F(L, 2)) > 0) == same_side:
                return abs(x1 - x2) == ans
    return a_card(q, ans, f'Каждая отметка в d/2 от середины. Ответ: {num(ans)}.'), chk


@P('eb21-vases', 'Три вазы в ряд: сколько в средней',
   'Слева от правой вазы — две остальные, справа от левой — две остальные; средняя учтена дважды: m = L + R − всего.',
   'Сюжет (вазы с розами, корзины, полки, коробки), числа, цвета.',
   'L + R − S',
   r'вазы с розами',
   ['складывают без вычитания суммы'],
   '«На прилавке цветочного магазина стоят 3 вазы с розами … Сколько роз в … вазе?»')
def gen_eb21_vases(r):
    x, y, z = r.randint(2, 20), r.randint(2, 20), r.randint(2, 20)
    cols = r.sample(['белая', 'синяя', 'красная', 'жёлтая', 'зелёная', 'розовая'], 3)
    # порядок слева направо: cols[0] (x), cols[1] (y), cols[2] (z)
    left_of_right = x + y
    right_of_left = y + z
    S = x + y + z
    ans = y
    st = r.randrange(4)
    it = [('корзины с яблоками', 'корзины', 'яблоко', 'яблока', 'яблок', 'корзине', 'На полу в ряд стоят три'),
          ('коробки с карандашами', 'коробки', 'карандаш', 'карандаша', 'карандашей', 'коробке', 'На столе в ряд стоят три'),
          ('ведёрка с ракушками', 'ведёрка', 'ракушка', 'ракушки', 'ракушек', 'ведёрке', 'На песке в ряд стоят три'),
          ('полки с книгами', 'полки', 'книга', 'книги', 'книг', 'полке', 'В шкафу три')][st]
    g = lambda c: c[:-2] + ('ой' if c.endswith('ая') else 'ей')
    gp = lambda c: c[:-2] + ('ой' if c.endswith('ая') else 'ей')
    if st == 3:
        q = (f'В книжном шкафу три полки одна над другой: {cols[0]}, {cols[1]} и {cols[2]}, но в каком порядке — неизвестно. '
             f'Выше {g(cols[2])} полки стоят {pl(left_of_right, "книга", "книги", "книг")}, ниже {g(cols[0])} — '
             f'{pl(right_of_left, "книга", "книги", "книг")}. Всего на полках {pl(S, "книга", "книги", "книг")}. Сколько книг на '
             f'{g(cols[1])} полке?')
        # сверху вниз: cols[2]? переопределим: «выше c2» — это две другие, значит c2 нижняя; «ниже c0» — две другие, c0 верхняя
    else:
        noun = {'корзины с яблоками': 'корзин', 'коробки с карандашами': 'коробок', 'ведёрка с ракушками': 'ведёрок'}[it[0]]
        cname = lambda c: (c[:-2] + ('ое' if c.endswith('ая') else 'ее')) if st == 2 else c
        gname = lambda c: (c[:-2] + ('ого' if c.endswith('ая') else 'его')) if st == 2 else g(c)
        q = (f'{it[6]} {it[0]}: {cname(cols[0])}, {cname(cols[1])} и {cname(cols[2])} (порядок не указан). Слева от '
             f'{gname(cols[2])} {it[5].replace("корзине", "корзины").replace("коробке", "коробки").replace("ведёрке", "ведёрка")} '
             f'{pl(left_of_right, it[2], it[3], it[4])}, справа от {gname(cols[0])} — {pl(right_of_left, it[2], it[3], it[4])}. '
             f'Всего {pl(S, it[2], it[3], it[4])}. Сколько {it[4]} в {gname(cols[1]).replace("ого", "ом").replace("его", "ем") if st == 2 else g(cols[1])} '
             f'{it[5]}?')
        q = q.replace('Всего', f'Всего в трёх {it[5].replace("корзине", "корзинах").replace("коробке", "коробках").replace("ведёрке", "ведёрках")}', 1)

    def chk():
        found = set()
        cnt = {cols[0]: x, cols[1]: y, cols[2]: z}
        for perm in itertools.permutations(cols):
            for a_ in range(0, 25):
                for b_ in range(0, 25):
                    c_ = S - a_ - b_
                    if c_ < 0:
                        continue
                    v = dict(zip(perm, (a_, b_, c_)))
                    i2, i0 = perm.index(cols[2]), perm.index(cols[0])
                    lsum = sum(v[perm[k]] for k in range(i2))
                    rsum = sum(v[perm[k]] for k in range(i0 + 1, 3))
                    if lsum == left_of_right and rsum == right_of_left:
                        found.add(v[cols[1]])
        return found == {ans}
    return a_card(q, ans, f'{left_of_right} + {right_of_left} − {S} = {ans}: средний предмет учтён дважды.'), chk



@P('eb21-cell-pairs', 'Раскраска таблицы: пары соседних клеток',
   'Всего пар соседних клеток m(n − 1) + n(m − 1); белых пар = всего − разноцветных − чёрных.',
   'Размер таблицы, числа пар, сюжет (таблица, плитка на полу, шахматная доска, витраж).',
   'm(n − 1) + n(m − 1) − D − B',
   r'пар соседних клеток',
   ['считают пары как клетки', 'ошибаются в числе всех пар'],
   '«Клетки таблицы … раскрашены в чёрный и белый цвета так, что получилось … пар соседних клеток разного цвета …»')
def gen_eb21_cell_pairs(r):
    m, n = r.randint(3, 9), r.randint(3, 9)
    # реальная раскраска — чтобы числа были достижимы
    grid = [[r.random() < r.choice([0.3, 0.5, 0.7]) for _ in range(n)] for _ in range(m)]
    diff = same_b = same_w = 0
    for i in range(m):
        for j in range(n):
            for di, dj in ((0, 1), (1, 0)):
                ii, jj = i + di, j + dj
                if ii < m and jj < n:
                    if grid[i][j] != grid[ii][jj]:
                        diff += 1
                    elif grid[i][j]:
                        same_b += 1
                    else:
                        same_w += 1
    ask_white = r.random() < 0.6
    ans = same_w if ask_white else same_b
    known = same_b if ask_white else same_w
    st = r.randrange(4)
    obj = [('Клетки прямоугольной таблицы', 'чёрный', 'белый', 'чёрных', 'белых', 'клеток', 'клетки'),
           ('Квадратные плитки прямоугольного пола', 'серый', 'бежевый', 'серых', 'бежевых', 'плиток', 'плитки'),
           ('Стёкла прямоугольного витража', 'синий', 'жёлтый', 'синих', 'жёлтых', 'стёкол', 'стёкла'),
           ('Клетки прямоугольного поля', 'зелёный', 'красный', 'зелёных', 'красных', 'клеток', 'клетки')][st]
    sz = f'{m} × {n}'
    k1, k2 = (obj[3], obj[4]) if ask_white else (obj[4], obj[3])
    q = (f'{obj[0]} размером {sz} окрашены в {obj[1]} и {obj[2]} цвета. Оказалось, что соседних {obj[5]} разного цвета — {pl(diff, "пара", "пары", "пар")}, '
         f'а пар соседних {k1} {obj[5]} — {known}. (Соседними считаются {obj[6]} с общей стороной.) Сколько пар соседних {k2} {obj[5]}?')
    q = q.replace(f'соседних {obj[5]} разного цвета — {pl(diff, "пара", "пары", "пар")}', f'{pl(diff, "пара", "пары", "пар")} соседних {obj[5]} разного цвета')
    q = q.replace('Оказалось, что ', 'Оказалось ') .replace('Оказалось ' + str(diff), 'Получилось ' + str(diff))

    def chk():
        total = sum(1 for i in range(m) for j in range(n) for di, dj in ((0, 1), (1, 0)) if i + di < m and j + dj < n)
        return total - diff - known == ans
    return a_card(q, ans, f'Всего пар {m}·{n - 1} + {n}·{m - 1} = {m * (n - 1) + n * (m - 1)}. Ответ: {ans}.'), chk


@P('eb21-swap-eat', 'Двое меняются занятиями: кто сколько сделал',
   'Второй в k раз быстрее в обоих делах; условие «первого дела поровну» даёт t₁ = k·t₂; второе дело делится в отношении k² : 1.',
   'Сюжет (едят печенье и варенье, красят забор и ворота, копают и сажают), k, количество.',
   'C·k² / (k² + 1)',
   r'Маша и Медведь',
   ['делят в отношении k : 1 вместо k² : 1'],
   '«Маша и Медведь съели … печений и банку варенья, начав и закончив одновременно …»')
def gen_eb21_swap_eat(r):
    k = r.choice([2, 2, 3, 3, 4])
    unit = r.randint(2, 12)
    C = (k * k + 1) * unit
    ask_fast = r.random() < 0.6
    ans = C * k * k // (k * k + 1) if ask_fast else C // (k * k + 1)
    kw = {2: 'в два раза', 3: 'в три раза', 4: 'в четыре раза'}[k]
    st = r.randrange(4)
    # количества как в жизни: пирожков — до полусотни, досок забора и вёдер картошки — до сотни с небольшим
    if C > {0: 50, 1: 120, 2: 400, 3: 120}[st]:
        return None
    if st == 0:
        q = (f'Папа и сын съели {pl(C, "пирожок", "пирожка", "пирожков")} и тарелку салата, начав и закончив одновременно. Сначала '
             f'сын ел салат, а папа — пирожки, потом они поменялись. Папа ест и то и другое {kw} быстрее сына. Сколько пирожков '
             f'съел {"папа" if ask_fast else "сын"}, если салата они съели поровну?')
    elif st == 1:
        q = (f'Мастер и ученик покрасили {pl(C, "доску", "доски", "досок")} забора и калитку, начав и закончив одновременно. '
             f'Сначала ученик красил калитку, а мастер — забор, затем они поменялись. Мастер любую работу выполняет {kw} быстрее '
             f'ученика. Сколько досок покрасил {"мастер" if ask_fast else "ученик"}, если калитку они покрасили поровну?')
    elif st == 2:
        q = (f'Экскаватор и бульдозер вместе переместили {pl(C, "кубометр", "кубометра", "кубометров")} грунта и выровняли площадку, '
             f'начав и закончив работу одновременно. Сначала бульдозер ровнял площадку, а экскаватор копал, потом они поменялись. '
             f'Экскаватор любую из этих работ делает {kw} быстрее бульдозера. Сколько кубометров грунта переместил '
             f'{"экскаватор" if ask_fast else "бульдозер"}, если площадку они выровняли поровну?')
    else:
        q = (f'Старший и младший брат собрали {pl(C, "ведро", "ведра", "вёдер")} картошки и полили грядки, начав и закончив одновременно. '
             f'Сначала младший поливал, а старший собирал картошку, потом они поменялись. Старший и то и другое делает {kw} быстрее '
             f'младшего. Сколько вёдер картошки собрал {"старший" if ask_fast else "младший"} брат, если полили они поровну?')
    x, y = sp.symbols('x y', positive=True)  # x — время первой фазы, y — второй; скорость медленного 1

    def chk():
        sol = sp.solve([sp.Eq(x, k * y), sp.Eq(k * x + y, C)], [x, y])
        fast, slow = k * sol[x], sol[y]
        return (fast if ask_fast else slow) == ans
    return a_card(q, ans, f'Делятся в отношении {k * k} : 1: {C} · {k * k}/{k * k + 1}. Ответ: {ans}.'), chk


@P('eb21-residents', 'Квартиры с 1–3 жильцами: суммарное число жильцов',
   'Если в группе квартир жильцов минимально (по одному) или максимально (по трое), то число жильцов в пересечении известно.',
   'Число квартир, границы групп, суммы, сюжет (дом, общежитие, лодки, купе).',
   'S₁ + S₂ − (пересечение)',
   r'не меньше одного и не больше трёх',
   ['складывают суммы, забыв про пересечение'],
   '«В доме всего … квартир … В каждой квартире живёт не меньше одного и не больше трёх человек …»')
def gen_eb21_residents(r):
    N = r.randint(12, 25)
    a = r.randint(N // 2, N - 3)
    b = r.randint(3, a - 1)
    # группа 1: 1..a; группа 2: b..N; пересечение b..a
    ext = r.choice(['min1', 'max1', 'min2', 'max2'])
    ppl = [r.randint(1, 3) for _ in range(N)]
    if ext == 'min1':
        ppl[:a] = [1] * a
    elif ext == 'max1':
        ppl[:a] = [3] * a
    elif ext == 'min2':
        ppl[b - 1:] = [1] * (N - b + 1)
    else:
        ppl[b - 1:] = [3] * (N - b + 1)
    S1, S2 = sum(ppl[:a]), sum(ppl[b - 1:])
    ans = sum(ppl)
    st = r.randrange(3)
    hum = lambda v: pl(v, 'человек', 'человека', 'человек')
    if st == 0:
        q = (f'В небольшом доме {pl(N, "квартира", "квартиры", "квартир")}, они пронумерованы от 1 до {N}. В каждой квартире '
             f'прописано от одного до трёх человек. В квартирах № 1–{a} прописан{"о" if S1 % 10 != 1 or S1 % 100 == 11 else ""} '
             f'{hum(S1)}, в квартирах № {b}–{N} — {hum(S2)}. Сколько человек прописано во всём доме?')
    elif st == 1:
        q = (f'В хостеле {pl(N, "номер", "номера", "номеров")} с порядковыми номерами 1, 2, …, {N}. Сегодня в каждом номере ночует '
             f'один, два или три гостя. В номерах с первого по {a}-й включительно ночует {pl(S1, "гость", "гостя", "гостей")}, '
             f'а в номерах с {b}-го по {N}-й включительно — {pl(S2, "гость", "гостя", "гостей")}. Сколько всего гостей ночует в хостеле?')
    else:
        q = (f'По реке сплавляются {pl(N, "лодка", "лодки", "лодок")}, у каждой свой номер от 1 до {N}; в любой лодке от одного до '
             f'трёх туристов. В лодках с номерами от 1 до {a} суммарно {pl(S1, "турист", "туриста", "туристов")}, а в лодках с номерами '
             f'от {b} до {N} — {pl(S2, "турист", "туриста", "туристов")}. Сколько всего туристов в лодках?')

    def chk():
        # перебор недоступен (3^N); проверяем, что пересечение определено однозначно через оценки
        o = a - b + 1
        lo1, hi1 = max(o, S1 - 3 * (a - o)), min(3 * o, S1 - (a - o))
        lo2, hi2 = max(o, S2 - 3 * (N - b + 1 - o)), min(3 * o, S2 - (N - b + 1 - o))
        lo, hi = max(lo1, lo2), min(hi1, hi2)
        return lo == hi and S1 + S2 - lo == ans
    g = (1, a) if ext[-1] == '1' else (b, N)
    return a_card(q, ans, f'В группе с номерами {g[0]}–{g[1]} везде {"по одному" if ext[:3] == "min" else "по трое"} '
                          f'({"меньше" if ext[:3] == "min" else "больше"} быть не может), поэтому в общей части с номерами {b}–{a} '
                          f'их {a - b + 1 if ext[:3] == "min" else 3 * (a - b + 1)}. Всего {S1} + {S2} − '
                          f'{a - b + 1 if ext[:3] == "min" else 3 * (a - b + 1)} = {ans}.'), chk


@functools.lru_cache(None)
def grade_products(L):
    """Все произведения, которые можно получить из последовательности L отметок 2–5 расстановкой знаков умножения."""
    res = {}
    for seq in itertools.product((2, 3, 4, 5), repeat=L):
        for mask in range(1 << (L - 1)):
            nums, cur = [], seq[0]
            for i in range(1, L):
                if mask >> (i - 1) & 1:
                    nums.append(cur)
                    cur = seq[i]
                else:
                    cur = cur * 10 + seq[i]
            nums.append(cur)
            pr = math.prod(nums)
            res.setdefault(pr, set()).add(seq)
    return res



@P('eb21-grades', 'Отметки со знаками умножения: итоговая отметка',
   'Раскладываем произведение на множители-«числа из отметок» (2–5 и числа из этих цифр); находим отметки и округляем их среднее.',
   'Число отметок, произведение, сюжет (четверть, семестр, олимпиада-баллы).',
   'единственное среднее, округлённое по правилам',
   r'поставил между некоторыми из них знаки умножения',
   ['забывают про многозначные сомножители', 'округляют неверно'],
   '«В конце четверти Петя выписал подряд все свои отметки … и поставил между некоторыми из них знаки умножения …»')
def gen_eb21_grades(r):
    L = r.choice([4, 5, 5])
    table = grade_products(L)
    seq = tuple(r.choice((2, 3, 4, 5)) for _ in range(L))
    splits = []
    for mask in range(1, 1 << (L - 1)):
        nums, cur = [], seq[0]
        for i in range(1, L):
            if mask >> (i - 1) & 1:
                nums.append(cur)
                cur = seq[i]
            else:
                cur = cur * 10 + seq[i]
        nums.append(cur)
        if len(nums) < L:
            splits.append(math.prod(nums))
    if not splits:
        return None
    P_ = r.choice(splits)
    rnd = lambda sq: int(F(sum(sq), len(sq)) + F(1, 2))
    marks = {rnd(sq) for sq in table[P_]}
    if len(marks) != 1 or P_ < 100:
        return None
    ans = marks.pop()
    w = Who(r)
    per = r.choice(['четверти', 'полугодия', 'триместра'])
    subj = r.choice(['по истории', 'по химии', 'по физике', 'по литературе', 'по географии'])
    q = (f'В конце {per} {w.n} {w.v("записал")} в строчку все свои отметки {subj} — их оказалось {L}, — а затем между некоторыми '
         f'соседними цифрами {w.v("поставил")} знаки умножения. Произведение получившихся чисел равно {P_}. Какую отметку '
         f'{w.n} {w.v("получит")} за {per.replace("и", "ь") if per == "четверти" else per.replace("ия", "ие").replace("а", "")}, если '
         f'учитель ставит только «2», «3», «4» и «5», а итоговая отметка — это среднее арифметическое текущих, округлённое по '
         f'правилам округления (например, 3,5 округляется до 4, а 4,4 — до 4)?')
    q = q.replace('получита', 'получит').replace('за триместр', 'за триместр')
    q = q.replace('за четверть', 'за четверть').replace('за полугодие', 'за полугодие')

    def chk():
        found = set()
        for sq in itertools.product((2, 3, 4, 5), repeat=L):
            digits_ = ''.join(map(str, sq))
            for mask in range(1 << (L - 1)):
                parts, start = [], 0
                for i in range(1, L):
                    if mask >> (i - 1) & 1:
                        parts.append(int(digits_[start:i]))
                        start = i
                parts.append(int(digits_[start:]))
                if math.prod(parts) == P_:
                    avg = F(sum(sq), L)
                    found.add(math.floor(avg + F(1, 2)))
        return found == {ans}
    return a_card(q, ans, f'Раскладываем {P_} на множители-отметки. Ответ: {ans}.'), chk


@P('eb21-pages', 'Выпавшие листы книги',
   'Лист — две страницы (нечётная и следующая чётная); последняя страница перед выпавшими чётная, первая после — нечётная; '
   'подбираем перестановку цифр.',
   'Номер страницы, сюжет (книга, журнал, альбом, дневник).',
   '(m − n − 1) / 2',
   r'Из книги выпало несколько идущих подряд листов',
   ['считают страницы вместо листов', 'не проверяют чётность'],
   '«Из книги выпало несколько идущих подряд листов. Номер последней страницы перед выпавшими листами — …»')
def gen_eb21_pages(r):
    n = r.randrange(100, 999, 2)
    ds = str(n)
    cands = {int(''.join(p_)) for p_ in itertools.permutations(ds) if p_[0] != '0'}
    ok = [m for m in cands if m > n and m % 2 == 1]
    if len(ok) != 1:
        return None
    m = ok[0]
    ans = (m - n - 1) // 2
    # в журнале и ежедневнике — до пары сотен страниц, в толстом словаре и энциклопедии — до тысячи
    pool = [('Из старого учебника', 'учебника'), ('Из толстого словаря', 'словаря'), ('Из энциклопедии', 'энциклопедии')]
    if m < 300:
        pool += [('Из журнала', 'журнала'), ('Из ежедневника', 'ежедневника'), ('Из фотоальбома', 'альбома')]
    obj = r.choice(pool)
    q = (f'{obj[0]} выпал блок из нескольких идущих подряд листов. Страница перед ним имеет номер {n}, а номер страницы сразу '
         f'после выпавшего блока записан теми же цифрами, только в другом порядке. Сколько листов выпало? (Страницы {obj[1]} '
         f'пронумерованы подряд, начиная с 1, на каждом листе две страницы.)')

    def chk():
        found = set()
        for last in range(n + 1, 1000):
            if sorted(str(last)) == sorted(str(n)) and last != n:
                # листы: (1,2), (3,4), … ; n — чётная (конец листа), last — нечётная (начало листа)
                if n % 2 == 0 and last % 2 == 1:
                    found.add((last - 1 - n) // 2)
        return found == {ans}
    return a_card(q, ans, f'Следующая страница — {m}; выпали страницы {n + 1}–{m - 1}, это {pl(m - n - 1, "страница", "страницы", "страниц")}, '
                          f'то есть {pl(ans, "лист", "листа", "листов")}.'), chk


@P('eb21-rays', 'Три луча из одной точки: сколько значений у среднего угла',
   'x + y + z = 360, z = k·x, x < y < z — перебираем целые x и считаем допустимые y.',
   'Коэффициент k, «разных углов», что спрашивают (число значений среднего или наименьшего угла).',
   'подсчёт перебором',
   r'Три луча',
   ['допускают равные углы', 'забывают про целые градусы'],
   '«Три луча, выходящие из одной точки, разбивают плоскость на 3 разных угла … Сколько значений может принимать величина среднего угла?»')
def gen_eb21_rays(r):
    k = r.choice([2, 3, 4, 5, 6, 7, 8, 9, 10])
    ask = r.choice(['mid', 'min', 'max'])
    vals = set()
    for x in range(1, 360):
        z = k * x
        y = 360 - x - z
        if x < y < z:
            vals.add({'mid': y, 'min': x, 'max': z}[ask])
    ans = len(vals)
    if ans == 0:
        return None
    st = r.randrange(3)
    kw = raz(k)
    if st == 0:
        q = (f'Из одной точки провели три луча, и они разбили плоскость на три попарно различных угла, каждый из которых содержит '
             f'целое число градусов. Наибольший из углов {kw} больше наименьшего. Сколько различных значений может принимать '
             f'{ {"mid": "средний по величине угол", "min": "наименьший угол", "max": "наибольший угол"}[ask]}?')
    elif st == 1:
        q = (f'Три стрелки часов-игрушки выходят из центра циферблата и делят его на три разных угла, выраженных целым числом '
             f'градусов. Самый большой угол {kw} больше самого маленького. Сколько существует возможных значений '
             f'{ {"mid": "среднего угла", "min": "самого маленького угла", "max": "самого большого угла"}[ask]}?')
    else:
        q = (f'Круглый торт разрезали из центра тремя разрезами на три куска разного размера; центральный угол каждого куска — '
             f'целое число градусов. Угол самого большого куска {kw} больше угла самого маленького. Сколько значений может '
             f'принимать угол { {"mid": "среднего", "min": "самого маленького", "max": "самого большого"}[ask]} куска?')

    def chk():
        cnt = 0
        seen = set()
        for x in range(1, 121):
            for y in range(x + 1, 360):
                z = 360 - x - y
                if z > y and z == k * x:
                    seen.add({'mid': y, 'min': x, 'max': z}[ask])
        return len(seen) == ans
    return a_card(q, ans, f'x + y + {k}x = 360, x < y < {k}x. Ответ: {ans}.'), chk


@P('eb21-factors', 'Изменение произведения при увеличении множителей',
   '(a + p)(b + p) − ab = p(a + b) + p² ⇒ a + b; затем q(a + b) + q².',
   'p, q, прирост, сюжет (множители, стороны прямоугольника, размеры грядки).',
   'q·(a + b) + q²',
   r'каждый из двух множителей увеличили',
   ['считают прирост пропорциональным'],
   '«Если бы каждый из двух множителей увеличили на …, то их произведение увеличилось бы на … На сколько увеличится …?»')
def gen_eb21_factors(r):
    p_, q_ = r.sample([1, 2, 3, 4, 5], 2)
    sab = r.randint(3, 40)
    D = p_ * sab + p_ * p_
    ans = q_ * sab + q_ * q_
    st = r.randrange(3)
    if st == 0:
        q = (f'Если каждый из двух сомножителей увеличить на {p_}, их произведение станет больше на {D}. На сколько увеличится '
             f'произведение, если каждый из сомножителей увеличить на {q_}?')
    elif st == 1:
        q = (f'Если каждую сторону прямоугольника удлинить на {pl(p_, "метр", "метра", "метров")}, его площадь увеличится на {D} м². '
             f'На сколько квадратных метров увеличится площадь, если каждую сторону удлинить на {pl(q_, "метр", "метра", "метров")}?')
    else:
        q = (f'Длину и ширину прямоугольной грядки увеличили на {p_} дм каждую, и площадь грядки выросла на {D} дм². На сколько '
             f'квадратных дециметров выросла бы площадь, если бы длину и ширину увеличили на {q_} дм каждую?')
    a_, b_ = sp.symbols('a b')

    def chk():
        s_ = sp.solve(sp.Eq(sp.expand((a_ + p_) * (b_ + p_) - a_ * b_), D), a_)[0]
        return sp.simplify((s_ + q_) * (b_ + q_) - s_ * b_) == ans
    return a_card(q, ans, f'{p_}(a + b) + {p_ * p_} = {D} ⇒ a + b = {sab}; {q_}·{sab} + {q_ * q_} = {ans}.'), chk


@P('eb21-guess', 'Загаданное число и три неизвестных множителя',
   'x·A + B − C = R, A, B, C из узкого диапазона ⇒ B − C мало, x = (R − (B − C))/A — единственный вариант с целым x.',
   'Диапазон A, B, C, R, сюжет (фокус, робот, калькулятор).',
   'x из перебора A, B − C',
   r'Про натуральные числа A, B и С',
   ['не учитывают, что B − C может быть отрицательным'],
   '«Про натуральные числа A, B и С известно, что каждое из них больше 4, но меньше 8. Загадали натуральное число …»')
def gen_eb21_guess(r):
    lo = r.randint(2, 8)
    hi = lo + 4
    A, B, C = [r.randint(lo + 1, hi - 1) for _ in range(3)]
    x = r.randint(20, 150)
    R = x * A + B - C
    sols = {(R - (b_ - c_)) // a_ for a_ in range(lo + 1, hi) for b_ in range(lo + 1, hi) for c_ in range(lo + 1, hi)
            if (R - (b_ - c_)) % a_ == 0 and (R - (b_ - c_)) > 0}
    if sols != {x}:
        return None
    ans = x
    st = r.randrange(3)
    if st == 0:
        q = (f'Числа A, B и C натуральные, и каждое больше {lo}, но меньше {hi}. Задумали натуральное число, умножили его на A, к '
             f'результату прибавили B, а затем отняли C. Вышло {R}. Какое число задумали?')
    elif st == 1:
        q = (f'Робот получает натуральное число, умножает его на A, прибавляет B и вычитает C, где A, B, C — натуральные числа, '
             f'большие {lo} и меньшие {hi}. На выходе робот выдал {R}. Какое число получил робот на входе?')
    else:
        q = (f'Фокусник попросил зрителя задумать натуральное число, умножить на A, прибавить B и отнять C. Про натуральные A, B и C '
             f'известно только, что каждое из них заключено строго между {lo} и {hi}. Зритель назвал результат {R}. Какое число '
             f'он задумал?')

    def chk():
        found = set()
        for a_ in range(lo + 1, hi):
            for b_ in range(lo + 1, hi):
                for c_ in range(lo + 1, hi):
                    for xx in range(1, R + 10):
                        if xx * a_ + b_ - c_ == R:
                            found.add(xx)
        return found == {ans}
    return a_card(q, ans, f'B − C принимает значения от {tnum(lo + 1 - (hi - 1))} до {hi - 1 - (lo + 1)}, поэтому {R} − (B − C) — одно из '
                          f'чисел {R - (hi - 1 - (lo + 1))}, …, {R + (hi - 1 - (lo + 1))}; на A из допустимых делится только '
                          f'{ans * next(a_ for a_ in range(lo + 1, hi) if (R - (B - C)) % a_ == 0 and (R - (B - C)) // a_ == ans)}. Ответ: {ans}.'), chk


@P('eb21-thirds', 'Каждый забирает долю остатка: сколько было сначала',
   'Идём с конца: остаток после каждого — (1 − доля) от предыдущего количества; R·(1/(1 − d))ⁿ.',
   'Число участников, доля (треть, четверть, половина), остаток, сюжет.',
   'R / (1 − d)ⁿ',
   r'забрал треть всех',
   ['делят остаток на долю'],
   '«На столе лежали тетради для трёх учеников. Сначала пришёл первый, забрал треть всех тетрадей …»')
def gen_eb21_thirds(r):
    frac = r.choice([F(1, 3), F(1, 4), F(1, 2), F(1, 5)])
    n = r.choice([2, 3, 3])
    keep = 1 - frac
    base = r.randint(1, 6)
    R_ = base * frac.denominator ** n // math.gcd(frac.denominator ** n, 1)
    R_ = base * (keep.numerator ** n)
    X = R_ / keep ** n
    if X.denominator != 1 or X > 1000:
        return None
    ans = int(X)
    fw = {F(1, 3): ('треть', 'трети'), F(1, 4): ('четверть', 'четверти'), F(1, 2): ('половину', 'половины'), F(1, 5): ('пятую часть', 'пятой части')}[frac]
    who = {2: 'двух', 3: 'трёх'}[n]
    st = r.randrange(3)
    item = [('конфет', 'конфеты', 'конфета', 'В вазе лежали конфеты', 'гостей'), ('яблок', 'яблока', 'яблоко', 'В корзине лежали яблоки', 'путников'),
            ('листов бумаги', 'листа бумаги', 'лист бумаги', 'В лотке принтера лежала пачка бумаги', 'сотрудников')][st]
    q = (f'{item[3]} для {who} {item[4]}. Первый, не дождавшись остальных, взял {fw[0]} всех {item[0].split()[0]} и ушёл. Второй, не зная '
         f'об этом, взял {fw[0]} от того, что осталось{"" if n == 2 else ", третий поступил так же"}. После этого осталось '
         f'{pl(R_, item[2], item[1], item[0])}. Сколько {item[0]} было вначале?')

    def chk():
        cur = F(ans)
        for _ in range(n):
            if (cur * frac).denominator != 1:
                return False
            cur -= cur * frac
        return cur == R_
    return a_card(q, ans, f'Каждый раз остаётся {num(keep) if keep.denominator == 1 else f"{keep.numerator}/{keep.denominator}"}; '
                          f'{R_} : ({keep.numerator}/{keep.denominator})^{n} = {ans}.'), chk


